// SPDX-License-Identifier: MIT

pragma solidity 0.8.26;

import {IDiamondCut} from "./../interfaces/IDiamondCut.sol";
import {LibDiamond} from "./../libraries/LibDiamond.sol";

/// @notice Upgrade surface for a pool diamond. Every write is gated to `ds.FACTORY` — the
///         RainDeployer, whose owner is the protocol multisig — and every post-construction cut
///         must sit queued for `upgradeDelay` before it can be applied.
///
///         There is deliberately NO instant-cut path, not even a pause. If an emergency
///         entrypoint is ever wanted it must be proposed as its own change with its own scope,
///         not folded in here.
///
///         Pools created with `upgradeDelay == 0` are immutable and revert on every path below.
///         The heavy lifting is implemented in LibDiamond.
contract DiamondCutFacet is IDiamondCut {
    /// @inheritdoc IDiamondCut
    /// @dev Construction-time only. `LibDiamond.diamondCut` latches `isInitialized`, so on a
    ///      live pool this reverts `AlreadyInitialized` — the instant path stays closed.
    function diamondCut(FacetCut[] calldata _diamondCut, address _init, bytes calldata _calldata) external override {
        // enforce ownership inside library
        LibDiamond.enforceIsFactory();
        LibDiamond.diamondCut(_diamondCut, _init, _calldata);
    }

    /// @inheritdoc IDiamondCut
    function proposeDiamondCut(
        FacetCut[] calldata _diamondCut,
        address _init,
        bytes calldata _calldata
    ) external override returns (bytes32 proposalId, uint256 eta) {
        LibDiamond.enforceIsFactory();
        return LibDiamond.proposeCut(_diamondCut, _init, _calldata);
    }

    /// @inheritdoc IDiamondCut
    function executeDiamondCut(
        FacetCut[] calldata _diamondCut,
        address _init,
        bytes calldata _calldata
    ) external override {
        LibDiamond.enforceIsFactory();
        LibDiamond.executeCut(_diamondCut, _init, _calldata);
    }

    /// @inheritdoc IDiamondCut
    function cancelDiamondCut(bytes32 proposalId) external override {
        LibDiamond.enforceIsFactory();
        LibDiamond.cancelCut(proposalId);
    }

    /// @inheritdoc IDiamondCut
    function diamondCutProposalId(
        FacetCut[] calldata _diamondCut,
        address _init,
        bytes calldata _calldata
    ) external pure override returns (bytes32) {
        return LibDiamond.cutProposalId(_diamondCut, _init, _calldata);
    }

    /// @inheritdoc IDiamondCut
    function upgradeDelay() external view override returns (uint256) {
        return LibDiamond.diamondStorage().upgradeDelay;
    }

    /// @inheritdoc IDiamondCut
    function cutEta(bytes32 proposalId) external view override returns (uint256) {
        return LibDiamond.diamondStorage().cutEta[proposalId];
    }

    /// @inheritdoc IDiamondCut
    function upgradeGracePeriod() external pure override returns (uint256) {
        return LibDiamond.UPGRADE_GRACE_PERIOD;
    }
}

