// SPDX-License-Identifier: MIT

pragma solidity 0.8.26;

import { IERC20, SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";

import { LibDiamond } from "../libraries/LibDiamond.sol";

import { Accounted } from "./base/Accounted.sol";


import { LibUtils } from "../libraries/LibUtils.sol";

import { ITrading } from "../interfaces/ITrading.sol";

import { _revert } from "../../utils/Globals.sol";

import { LinkedListLogic } from "../../libraries/LinkedList.sol";
import { LinkedListStorage } from "../../interfaces/LinkedListStorage.sol";

import { IRainPool } from "../../interfaces/IRainPool.sol";

/**
 * @title TradingFacet
 * @author Rain Team
 * @notice External interface for the rain pool trading facet.
 */
contract TradingFacet is ITrading, Accounted {
    using SafeERC20 for IERC20;
    using LinkedListLogic for LinkedListStorage.LinkedList;

    /**
     * @inheritdoc ITrading
     */
    function enterOption(
        uint256 option,
        uint8 optionSide,
        uint256 amount,
        uint256 minSharesOut,
        uint256 deadline
    ) external accounted {
        if (block.timestamp > deadline) {
            _revert(IRainPool.DeadlineExpired.selector);
        }

        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (block.timestamp < ds.startTime) {
            _revert(IRainPool.SaleNotLive.selector);
        }
        if (option == 0 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }
        if (optionSide != 1 && optionSide != 2) {
            _revert(IRainPool.InvalidSide.selector);
        }
        if (amount <= 0) {
            _revert(IRainPool.InsufficientAmount.selector);
        }

        // Phase routing: AMM pools run the CPMM swap during their trading window,
        // then flip to the OB walk between endTime/finalized and the claim window.
        // OB pools always run the OB walk. Once the claim window opens, both revert.
        bool ammPhase = LibDiamond.isAMMPhase(option);
        bool obPhase = LibDiamond.isOBPhase(option);
        if (!ammPhase && !obPhase) {
            _revert(IRainPool.PoolClosed.selector);
        }

        IERC20(ds.baseToken).safeTransferFrom(msg.sender, address(this), amount);

        uint256 totalAmountUsed;
        uint256 totalSharesReceived;

        if (ammPhase) {
            if (ds.totalOptionLPShares[option] == 0 || ds.ammYesReserve[option] == 0 || ds.ammNoReserve[option] == 0) {
                _revert(IRainPool.InvalidPoolState.selector);
            }

            // AMM has no partial-fill concept: the swap consumes the full amount.
            uint256 swapFee = (amount * ds.liquidityFee) / ds.FEE_MAGNIFICATION;
            if (swapFee == 0) {
                _revert(IRainPool.AmountTooSmall.selector);
            }
            // Protocol fee is taken from the taker up front and credited to the
            // per-option fee accumulators. It never enters optionTotalFunds, so
            // winners claim the full pot with no deduction at claim.
            uint256 protocolFee = LibDiamond.collectTradeFee(option, amount);
            uint256 netAmount = amount - swapFee - protocolFee;
            _accrueSwapFee(ds, option, swapFee);

            uint256 sharesReceived = getReturnedShares(option, optionSide, netAmount);

            {
                uint256 ammOut = sharesReceived - netAmount;
                if (optionSide == 1) {
                    ds.ammYesReserve[option] -= ammOut;
                    ds.ammNoReserve[option] += netAmount;
                } else {
                    ds.ammNoReserve[option] -= ammOut;
                    ds.ammYesReserve[option] += netAmount;
                }
            }

            ds.userOptionPerSideShares[option][optionSide][msg.sender] += sharesReceived;

            ds.optionPerSideFunds[option][1] += netAmount;
            ds.optionPerSideFunds[option][2] += netAmount;
            ds.optionPerSideShares[option][1] += netAmount;
            ds.optionPerSideShares[option][2] += netAmount;

            ds.optionTotalFunds[option] += netAmount;
            ds.optionTotalShares[option] += netAmount;

            ds.totalMarketFunds += netAmount;
            ds.totalMarketShares += netAmount;

            totalSharesReceived = sharesReceived;
            totalAmountUsed = amount;
        } else {
            // OrderBook path: walk the sell book from the best (lowest) available price upward.
            // Works identically whether the option is live or finalized — late buyers just drain
            // whatever liquidity remains and get the unfilled remainder refunded below.
            uint256 head = ds.firstSellOrderPrice[option][optionSide];
            uint256 usedAmount;
            uint256 sharesReceived;
            int256 idx;
            bool orderRemoved;

            while (amount > 1 && head > 0 && head <= 0.99 ether) {
                LinkedListStorage.LinkedList storage linkedList = ds.sellOrders[option][optionSide][head];

                if (linkedList.isInitialized && !linkedList.isEmpty()) {
                    idx = linkedList.first();
                    while (idx != linkedList.tailIndex && amount > 0) {
                        LinkedListStorage.Order memory order = linkedList.getData(idx);
                        idx = linkedList.next(idx);
                        (usedAmount, sharesReceived, orderRemoved) = _executeSellOrder(
                            option,
                            optionSide,
                            head,
                            amount,
                            order.orderID,
                            msg.sender
                        );
                        amount -= usedAmount;
                        totalAmountUsed += usedAmount;
                        totalSharesReceived += sharesReceived;
                    }
                }

                if (linkedList.isEmpty()) {
                    head += ds.TICK_SPACING;

                    ds.firstSellOrderPrice[option][optionSide] = head > 0.99 ether ? 0.99 ether : head;
                } else {
                    break;
                }
            }

            // Normalize the best-ask pointer off any empty tick a sweep left it on (F-2026-17921).
            _syncBestAsk(ds, option, optionSide, ds.firstSellOrderPrice[option][optionSide]);

            // Refund any unfilled remainder (shallow book or dust below the minimum fill).
            if (amount > 0) {
                IERC20(ds.baseToken).safeTransfer(msg.sender, amount);
            }
        }

        if (totalSharesReceived < minSharesOut) {
            _revert(IRainPool.SlippageExceeded.selector);
        }

        // Only emit EnterOption for the AMM swap path. On the OrderBook path each fill already
        // emits ExecuteSellOrder, so an additional EnterOption would be redundant.
        if (ammPhase) {
            emit IRainPool.EnterOption({
                option: option,
                optionSide: optionSide,
                baseAmount: totalAmountUsed,
                sharesAmount: totalSharesReceived,
                wallet: msg.sender
            });

            emit IRainPool.Price(
                option,
                ds.ammYesReserve[option],
                ds.ammNoReserve[option],
                ds.optionTotalFunds[option]
            );
        }
    }

    /**
     * @inheritdoc ITrading
     */
    function sellOption(
        uint256 option,
        uint8 optionSide,
        uint256 amount,
        uint256 minAmountOut,
        uint256 deadline
    ) external accounted {
        if (block.timestamp > deadline) {
            _revert(IRainPool.DeadlineExpired.selector);
        }

        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (option == 0 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }
        if (optionSide != 1 && optionSide != 2) {
            _revert(IRainPool.InvalidSide.selector);
        }
        // The OB matcher fills in whole-share steps and leaves dust (<= 1) unfilled,
        // mirroring enterOption / placeSellOrder, so reject sub-dust sell sizes upfront.
        if (amount <= 1) {
            _revert(IRainPool.InsufficientAmount.selector);
        }

        // Selling == walking the BUY book, which only exists in an OB phase (OB pools
        // always; AMM pools once they flip post-endTime/finalized). Phase A (AMM live)
        // and Phase C (claim) both revert here. In Phase A, exit via merge()/placeSellOrder.
        LibDiamond.enforceOBPhase(option);

        // Mirror the placeSellOrder abuse guard: a user who already claimed must not be
        // able to keep moving shares around the book.
        if (ds.optionClaimed[option][msg.sender]) {
            _revert(IRainPool.AlreadyClaimed.selector);
        }

        // Caller must own `amount` directly-held (un-escrowed) shares on this side.
        // Shares already locked behind a resting sell order cannot be market-sold; the
        // caller must cancel that order first to release them.
        uint256 available = ds.userOptionPerSideShares[option][optionSide][msg.sender] -
            ds.userSharesPerSideInEscrow[option][optionSide][msg.sender];
        if (available < amount) {
            _revert(IRainPool.InsufficientUserShares.selector);
        }

        // Net base proceeds are paid to the seller directly inside _executeBuyOrder
        // (gross minus burn fee minus maker rebate). Measuring the caller's balance
        // delta is the simplest exact read of what they actually pocket, which is the
        // quantity the slippage floor should bind against.
        uint256 balanceBefore = IERC20(ds.baseToken).balanceOf(msg.sender);

        uint256 remaining = amount;
        uint256 head = ds.firstBuyOrderPrice[option][optionSide];
        int256 idx;
        uint256 sharesFilled;
        bool orderRemoved;

        // Market sell: sweep every resting bid from the best (highest) price downward,
        // with no price limit, until the seller's shares run out or the book is dry.
        while (remaining > 1 && head >= ds.TICK_SPACING) {
            LinkedListStorage.LinkedList storage linkedListBuy = ds.buyOrders[option][optionSide][head];

            if (linkedListBuy.isInitialized && !linkedListBuy.isEmpty()) {
                idx = linkedListBuy.first();
                while (idx != linkedListBuy.tailIndex && remaining > 1) {
                    LinkedListStorage.Order memory order = linkedListBuy.getData(idx);
                    idx = linkedListBuy.next(idx);
                    // Seller's perspective: only `sharesFilled` is needed to decrement the
                    // remaining sell size; the base proceeds are transferred to msg.sender
                    // directly inside _executeBuyOrder.
                    (, sharesFilled, orderRemoved) = _executeBuyOrder(
                        option,
                        optionSide,
                        head,
                        remaining,
                        order.orderID,
                        msg.sender
                    );

                    remaining -= sharesFilled;
                }
            }

            if (linkedListBuy.isEmpty()) {
                // Level drained — scan down to the next non-empty bid (pointer hygiene) instead
                // of parking the head on an adjacent empty tick, so firstBuyOrderPrice always
                // points at real liquidity (or the 0.01 sentinel when the book is dry).
                if (head <= ds.TICK_SPACING) {
                    ds.firstBuyOrderPrice[option][optionSide] = ds.TICK_SPACING;
                    break;
                }
                unchecked {
                    head -= ds.TICK_SPACING;
                }

                ds.firstBuyOrderPrice[option][optionSide] = head;
            } else {
                // Level still has resting bids but the seller is out of shares — stop here
                // and leave firstBuyOrderPrice pointing at this still-active level.
                break;
            }
        }

        // Normalize the best-bid pointer off any empty tick a sweep left it on (F-2026-17921).
        _syncBestBid(ds, option, optionSide, ds.firstBuyOrderPrice[option][optionSide]);

        // Slippage floor binds on the NET base actually received. Any shares that went
        // unfilled (shallow book) simply remain in the caller's balance — nothing was
        // escrowed, so there is no refund step.
        uint256 received = IERC20(ds.baseToken).balanceOf(msg.sender) - balanceBefore;
        if (received < minAmountOut) {
            _revert(IRainPool.SlippageExceeded.selector);
        }

        emit IRainPool.SellOption({
            option: option,
            optionSide: optionSide,
            baseAmount: received,
            sharesAmount: amount - remaining,
            wallet: msg.sender
        });
    }

    /**
     * @inheritdoc ITrading
     */
    function enterLiquidity(
        uint256 option,
        uint256 totalAmount,
        uint256 minYesToDeposit,
        uint256 minNoToDeposit,
        uint256 deadline
    ) external accounted {
        if (block.timestamp > deadline) {
            _revert(IRainPool.DeadlineExpired.selector);
        }

        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        address user = msg.sender;
        if (option == 0 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }
        // Add-liquidity is only valid while the AMM window is open (Phase A).
        // Post-endTime / post-finalized pools are frozen — adding liquidity
        // to a frozen AMM has no semantics.
        LibDiamond.enforceAMMPhase(option);
        if (totalAmount == 0) {
            _revert(IRainPool.InsufficientAmount.selector);
        }

        IERC20(ds.baseToken).safeTransferFrom(user, address(this), totalAmount);
        _addLiquidityToOption(ds, user, option, totalAmount, minYesToDeposit, minNoToDeposit);
    }

    /**
     * @notice Adds liquidity across every option in a single call.
     * @dev Pulls `totalAmount` once, then distributes slices per `percentages` (basis points)
     *      into each option's AMM via `_addLiquidityToOption`. Each `percentages[i]` must be
     *      at least 100 bps (1%) and the array must sum to 10_000 (100%).
     * @param totalAmount Total base-token amount to distribute across all options.
     * @param percentages Per-option share in basis points; length == numberOfOptions, sum == 10_000.
     */
    function enterLiquidityBatch(
        uint256 totalAmount,
        uint256[] calldata percentages,
        uint256[] calldata minYesToDeposit,
        uint256[] calldata minNoToDeposit,
        uint256 deadline
    ) external accounted {
        if (block.timestamp > deadline) {
            _revert(IRainPool.DeadlineExpired.selector);
        }

        LibDiamond.enforceAMMMode();
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        address user = msg.sender;
        uint256 numberOfOptions = ds.numberOfOptions;

        if (
            percentages.length != numberOfOptions ||
            minYesToDeposit.length != numberOfOptions ||
            minNoToDeposit.length != numberOfOptions
        ) {
            _revert(IRainPool.ArrayLengthMismatch.selector);
        }
        if (block.timestamp < ds.startTime) {
            _revert(IRainPool.SaleNotLive.selector);
        }
        // Pool-wide AMM window upper bound — once endTime passes, every option
        // has flipped to Phase B and the AMM is frozen across the board.
        if (block.timestamp > ds.endTime) {
            _revert(IRainPool.PoolClosed.selector);
        }
        if (totalAmount == 0) {
            _revert(IRainPool.InsufficientAmount.selector);
        }

        uint256 percentageSum;
        for (uint256 i = 0; i < numberOfOptions; ) {
            if (percentages[i] < 100) {
                _revert(IRainPool.InvalidLiquidityPercentage.selector);
            }
            percentageSum += percentages[i];
            unchecked {
                ++i;
            }
        }
        if (percentageSum != 10_000) {
            _revert(IRainPool.InvalidLiquidityPercentage.selector);
        }

        IERC20(ds.baseToken).safeTransferFrom(user, address(this), totalAmount);

        uint256 unusedSlice;
        for (uint256 i = 1; i <= numberOfOptions; ) {
            uint256 slice = (totalAmount * percentages[i - 1]) / 10_000;
            // Per-option finalization can happen mid-pool (resolver closes early);
            // skip frozen options to keep the batch atomic without forcing revert.
            // The slice was pulled upfront, so accumulate it and refund after the loop.
            if (ds.optionFinalized[i]) {
                unusedSlice += slice;
                unchecked {
                    ++i;
                }
                continue;
            }
            if (slice > 0) {
                _addLiquidityToOption(ds, user, i, slice, minYesToDeposit[i - 1], minNoToDeposit[i - 1]);
            }
            unchecked {
                ++i;
            }
        }

        // Refund the cumulative slices of any frozen options that were skipped.
        if (unusedSlice > 0) {
            IERC20(ds.baseToken).safeTransfer(user, unusedSlice);
        }
    }

    /**
     * @inheritdoc ITrading
     */
    function removeLiquidity(
        uint256 option,
        uint256 lpShares,
        uint256 minYesOut,
        uint256 minNoOut,
        uint256 deadline
    ) external accounted {
        if (block.timestamp > deadline) {
            _revert(IRainPool.DeadlineExpired.selector);
        }

        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        address user = msg.sender;

        if (option == 0 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }
        // LPs can exit anytime before claim opens — Phase A (active AMM) or
        // Phase B (post-AMM, frozen reserves). Once the dispute window ends
        // and claim opens, LP redemption flows through claim() instead.
        LibDiamond.enforceAMMMode();
        if (!LibDiamond.isAMMPhase(option) && !LibDiamond.isOBPhase(option)) {
            _revert(IRainPool.PoolClosed.selector);
        }
        if (lpShares == 0) {
            _revert(IRainPool.InvalidAmount.selector);
        }
        if (ds.userOptionLPShares[option][user] < lpShares) {
            _revert(IRainPool.InsufficientLPShares.selector);
        }

        uint256 totalLP = ds.totalOptionLPShares[option];

        // ── 1. Claim accrued swap fees on the user's full LP position ────────
        //    Must use the user's full pre-burn LP balance, not just `lpShares`.
        //    Step 5 below resets userFeeDebtX128 to accum for whatever shares
        //    remain, so partial-paid fees would be silently forfeited otherwise.
        uint256 feesEarned;
        uint256 accum = ds.feePerLPShareX128[option];
        uint256 debt = ds.userFeeDebtX128[option][user];
        if (accum > debt) {
            feesEarned = ((accum - debt) * ds.userOptionLPShares[option][user]) >> 128;
        }

        // ── 2. Proportional reserves (mulDiv prevents overflow) ──────────────
        uint256 yesBack = Math.mulDiv(lpShares, ds.ammYesReserve[option], totalLP);
        uint256 noBack = Math.mulDiv(lpShares, ds.ammNoReserve[option], totalLP);

        // Slippage guard: the returned YES/NO composition tracks live reserves at
        // execution time, so honour the caller-declared floors before mutating state.
        if (yesBack < minYesOut || noBack < minNoOut) {
            _revert(IRainPool.SlippageExceeded.selector);
        }

        // ── 3. Remove from AMM reserves ──────────────────────────────────────
        ds.ammYesReserve[option] -= yesBack;
        ds.ammNoReserve[option] -= noBack;

        // ── 4. Burn LP shares ─────────────────────────────────────────────────
        ds.userOptionLPShares[option][user] -= lpShares;
        ds.totalOptionLPShares[option] -= lpShares;

        // ── 5. Reset fee debt for remaining LP shares ─────────────────────────
        ds.userFeeDebtX128[option][user] = accum;

        // ── 6. Credit withdrawn shares to user's direct balance ──────────────
        //    Shares move from AMM-held to user-held; totalFunds is unchanged.
        ds.userOptionPerSideShares[option][1][user] += yesBack;
        ds.userOptionPerSideShares[option][2][user] += noBack;

        // ── 7. Merge ALL matched pairs — return collateral ─────────────────────
        uint256 mergeableAmount;
        if (!ds.optionFinalized[option]) {
            uint256 availableYes = ds.userOptionPerSideShares[option][1][user] -
                ds.userSharesPerSideInEscrow[option][1][user];
            uint256 availableNo = ds.userOptionPerSideShares[option][2][user] -
                ds.userSharesPerSideInEscrow[option][2][user];
            mergeableAmount = availableYes < availableNo ? availableYes : availableNo;

            if (mergeableAmount > 0) {
                ds.userOptionPerSideShares[option][1][user] -= mergeableAmount;
                ds.userOptionPerSideShares[option][2][user] -= mergeableAmount;
                ds.optionPerSideFunds[option][1] -= mergeableAmount;
                ds.optionPerSideFunds[option][2] -= mergeableAmount;
                ds.optionPerSideShares[option][1] -= mergeableAmount;
                ds.optionPerSideShares[option][2] -= mergeableAmount;
                ds.optionTotalFunds[option] -= mergeableAmount;
                ds.optionTotalShares[option] -= mergeableAmount;
                ds.totalMarketFunds -= mergeableAmount;
                ds.totalMarketShares -= mergeableAmount;
            }
        }

        // ── 8. Transfer accrued swap fees ─────────────────────────────────────
        if (feesEarned > 0) {
            mergeableAmount += feesEarned;
        }
        if (mergeableAmount > 0) {
            IERC20(ds.baseToken).safeTransfer(user, mergeableAmount);
        }

        emit IRainPool.RemoveLiquidity(
            option,
            lpShares,
            mergeableAmount,
            ds.userOptionPerSideShares[option][1][user],
            ds.userOptionPerSideShares[option][2][user],
            feesEarned,
            user
        );
        emit IRainPool.Price(option, ds.ammYesReserve[option], ds.ammNoReserve[option], ds.optionTotalFunds[option]);
    }

    function placeSellOrder(
        uint256 option,
        uint8 optionSide,
        uint256 price, // 1e18
        uint256 shares,
        bool postOnly
    ) external accounted returns (uint256 orderID) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (option == 0 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }
        // Explicit side guard, mirroring placeBuyOrder / enterOption. The
        // share-availability check below would already revert for side != 1, 2
        // (no one ever holds shares for an invalid side), but an explicit early
        // reject keeps the failure mode consistent across order-book entry points.
        if (optionSide != 1 && optionSide != 2) {
            _revert(IRainPool.InvalidSide.selector);
        }
        // Order placement is allowed in any OB phase: OB pools always, AMM pools
        // once they flip post-endTime/finalized and until claim opens.
        LibDiamond.enforceOBPhase(option);
        // Seed book sentinels on first order for an AMM pool entering Phase B;
        // no-op for OB pools and after the first call.
        LibDiamond.ensureOBBookInitialized(option, optionSide);
        if (price < ds.TICK_SPACING || price > 0.99 ether || price % ds.TICK_SPACING != 0) {
            _revert(IRainPool.InvalidPrice.selector);
        }
        if (ds.baseToken == ds.usdt) {
            if ((shares * price) / (ds.PRICE_MAGNIFICATION) < 1 * ds.baseTokenDecimals) {
                _revert(IRainPool.InvalidAmount.selector);
            }
        } else {
            uint256 usdtPriceOrder = LibUtils.getQuoteOut(
                ds.baseToken,
                (shares * price) / ds.PRICE_MAGNIFICATION,
                ds.tokenData
            );
            if (usdtPriceOrder < 1 * 1e6) {
                _revert(IRainPool.InvalidAmount.selector);
            }
        }
        if (ds.userActiveSellOrdersPerOption[option][msg.sender] >= 50) {
            _revert(IRainPool.UserSellOrderLimitReached.selector);
        }

        // Check to prevent orderBook abuse
        if (ds.optionClaimed[option][msg.sender]) {
            _revert(IRainPool.AlreadyClaimed.selector);
        }

        uint256 userVotesAvbForSale = ds.userOptionPerSideShares[option][optionSide][msg.sender] -
            ds.userSharesPerSideInEscrow[option][optionSide][msg.sender];

        if (shares <= 0 || userVotesAvbForSale < shares) {
            _revert(IRainPool.InsufficientUserShares.selector);
        }

        uint256 sharesReceived;
        uint256 usedAmount;

        int256 idx;
        uint256 head = ds.firstBuyOrderPrice[option][optionSide];
        bool orderRemoved;

        if (postOnly) {
            // Maker-only (F-2026-17840): never route the caller through the matching loop.
            // Reject if the ask would cross a resting bid (best bid >= ask price); otherwise
            // fall through and rest the full size as a pure maker order.
            if (price <= head) {
                _revert(IRainPool.OrderWouldCross.selector);
            }
        } else {
            for (; price <= head && shares > 1; ) {
                LinkedListStorage.LinkedList storage linkedListBuy = ds.buyOrders[option][optionSide][head];

                if (!linkedListBuy.isEmpty()) {
                    idx = linkedListBuy.first();
                    while (idx != linkedListBuy.tailIndex && shares > 0) {
                        LinkedListStorage.Order memory order = linkedListBuy.getData(idx);

                        idx = linkedListBuy.next(idx);

                        (usedAmount, sharesReceived, orderRemoved) = _executeBuyOrder(
                            option,
                            optionSide,
                            head,
                            shares,
                            order.orderID,
                            msg.sender
                        );

                        shares -= sharesReceived;
                    }
                }

                if (linkedListBuy.isEmpty()) {
                    // Level fully drained — step the best-bid pointer one tick lower.
                    if (head <= ds.TICK_SPACING) {
                        ds.firstBuyOrderPrice[option][optionSide] = ds.TICK_SPACING;
                        break;
                    }
                    unchecked {
                        head -= ds.TICK_SPACING;
                    }
                    ds.firstBuyOrderPrice[option][optionSide] = head;
                } else {
                    // Level still has resting bids but the seller's shares are spent — stop here
                    // and leave firstBuyOrderPrice on this still-live level. Advancing past it
                    // would strand the higher bid below the pointer, invisible to later sellers.
                    break;
                }
            }
        }

        // Normalize the best-bid pointer off any empty tick the match left it on (F-2026-17921).
        _syncBestBid(ds, option, optionSide, ds.firstBuyOrderPrice[option][optionSide]);

        // Dust guard (F-2026-17920): only rest a remainder worth >= $0.10; smaller dust would
        // park a phantom ask that crosses the book. A dropped remainder was never escrowed, so
        // the shares simply stay in the seller's available balance (no event needed).
        if (shares > 0 && _remainderWorthResting(ds, (shares * price) / ds.PRICE_MAGNIFICATION)) {
            orderID = uint256(
                keccak256(
                    abi.encodePacked(
                        price,
                        block.number, // or block.timestamp if you really want time
                        ds.ordersAdded,
                        msg.sender
                    )
                )
            );

            if (ds.orderBook[option][optionSide][price][orderID].exists == true) {
                _revert(IRainPool.OrderAlreadyExists.selector);
            }

            LinkedListStorage.LinkedList storage linkedList = ds.sellOrders[option][optionSide][price];

            if (!linkedList.isInitialized) {
                linkedList.initialize();
            }

            LinkedListStorage.Order memory newOrder = LinkedListStorage.Order({
                orderID: orderID,
                timestamp: block.timestamp,
                amount: shares,
                maker: msg.sender
            });

            idx = linkedList.append(newOrder);
            ds.orderBook[option][optionSide][price][orderID].exists = true;
            ds.orderBook[option][optionSide][price][orderID].index = idx;

            ds.userActiveSellOrdersPerOption[option][msg.sender]++;
            ds.userSharesPerSideInEscrow[option][optionSide][msg.sender] += shares;
            ++ds.ordersAdded;

            // head-of-book must be the *cheapest* outstanding price
            if (price < ds.firstSellOrderPrice[option][optionSide]) {
                ds.firstSellOrderPrice[option][optionSide] = price;
            }

            emit IRainPool.PlaceSellOrder({
                orderOption: option,
                orderOptionSide: optionSide,
                orderPrice: price,
                sharesAmount: shares,
                orderID: orderID,
                maker: msg.sender
            });
        }
    }

    function placeBuyOrder(
        uint256 option,
        uint8 optionSide,
        uint256 price, // 1e18
        uint256 amount,
        bool postOnly
    ) external accounted returns (uint256 orderID) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (option == 0 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }
        // Reject any side outside {1, 2}. Without this guard, the funds transfer
        // and userActiveBuyOrdersPerOption counter below would record into
        // userFundsPerSideInEscrow[option][optionSide][user] for an unreachable
        // side: cancelBuyOrders rejects side != 1, 2 and claim() only checks
        // sides 1 and 2 for buy escrow, so the funds + slot would be permanently
        // stuck. Mirrors the InvalidSide check already in enterOption.
        if (optionSide != 1 && optionSide != 2) {
            _revert(IRainPool.InvalidSide.selector);
        }
        LibDiamond.enforceOBPhase(option);
        LibDiamond.ensureOBBookInitialized(option, optionSide);
        if (price < ds.TICK_SPACING || price > 0.99 ether || price % ds.TICK_SPACING != 0) {
            _revert(IRainPool.InvalidPrice.selector);
        }
        if (ds.baseToken == ds.usdt) {
            if (amount < 1 * ds.baseTokenDecimals) {
                _revert(IRainPool.InvalidAmount.selector);
            }
        } else {
            uint256 usdtPriceToken = LibUtils.getQuoteOut(ds.baseToken, amount, ds.tokenData);
            if (usdtPriceToken < 1 * 1e6) {
                _revert(IRainPool.InvalidAmount.selector);
            }
        }
        if (ds.userActiveBuyOrdersPerOption[option][msg.sender] >= 50) {
            _revert(IRainPool.UserBuyOrderLimitReached.selector);
        }

        IERC20(ds.baseToken).safeTransferFrom(msg.sender, address(this), amount);

        uint256 usedAmount;
        int256 idx;
        uint256 head = ds.firstSellOrderPrice[option][optionSide];
        bool orderRemoved;

        if (postOnly) {
            // Maker-only (F-2026-17840): never route the caller through the matching loop.
            // Reject if the bid would cross a resting ask (best ask <= bid price); otherwise
            // fall through and rest the full size as a pure maker order.
            if (price >= head) {
                _revert(IRainPool.OrderWouldCross.selector);
            }
        } else {
            for (; head <= price && amount > 1; ) {
                LinkedListStorage.LinkedList storage linkedListSell = ds.sellOrders[option][optionSide][head];

                if (!linkedListSell.isEmpty()) {
                    idx = linkedListSell.first();
                    while (idx != linkedListSell.tailIndex && amount > 0) {
                        LinkedListStorage.Order memory order = linkedListSell.getData(idx);
                        idx = linkedListSell.next(idx);
                        // Buyer's perspective: only `usedAmount` (funds spent) is needed to
                        // decrement `amount`; the shares delivered are written directly into
                        // the buyer's per-side balance inside `_executeSellOrder`.
                        (usedAmount, , orderRemoved) = _executeSellOrder(
                            option,
                            optionSide,
                            head,
                            amount,
                            order.orderID,
                            msg.sender
                        );

                        amount -= usedAmount;
                    }
                }

                if (linkedListSell.isEmpty()) {
                    // Level fully drained — advance one tick and keep the best-ask pointer in
                    // sync. Everything below was just consumed, so stepping up is safe.
                    unchecked {
                        head += ds.TICK_SPACING;
                    }
                    ds.firstSellOrderPrice[option][optionSide] = head > 0.99 ether ? 0.99 ether : head;
                } else {
                    // Level still has resting asks but the buyer's funds are spent — stop here
                    // and leave firstSellOrderPrice on this still-live level. Advancing past it
                    // would strand the cheaper ask above the pointer, invisible to later buyers.
                    break;
                }
            }
        }

        // Normalize the best-ask pointer off any empty tick the match left it on (F-2026-17921).
        _syncBestAsk(ds, option, optionSide, ds.firstSellOrderPrice[option][optionSide]);

        // Dust guard (F-2026-17920): only rest a remainder worth >= $0.10; smaller dust would
        // park a phantom bid that crosses the book. A sub-floor remainder can't rest, so it is
        // refunded to the taker (see the else branch below).
        if (_remainderWorthResting(ds, amount)) {
            orderID = uint256(
                keccak256(
                    abi.encodePacked(
                        price,
                        block.number, // or block.timestamp if you really want time
                        ds.ordersAdded,
                        msg.sender
                    )
                )
            );

            if (ds.orderBook[option][optionSide][price][orderID].exists == true) {
                _revert(IRainPool.OrderAlreadyExists.selector);
            }

            LinkedListStorage.LinkedList storage linkedList = ds.buyOrders[option][optionSide][price];

            if (!linkedList.isInitialized) {
                linkedList.initialize();
            }

            LinkedListStorage.Order memory newOrder = LinkedListStorage.Order({
                orderID: orderID,
                timestamp: block.timestamp,
                amount: amount,
                maker: msg.sender
            });

            idx = linkedList.append(newOrder);
            ds.orderBook[option][optionSide][price][orderID].exists = true;
            ds.orderBook[option][optionSide][price][orderID].index = idx;

            ds.userActiveBuyOrdersPerOption[option][msg.sender]++;
            ds.userFundsPerSideInEscrow[option][optionSide][msg.sender] += amount;
            ++ds.ordersAdded;

            // head-of-book must be the *highest* (best) outstanding bid price
            if (price > ds.firstBuyOrderPrice[option][optionSide]) {
                ds.firstBuyOrderPrice[option][optionSide] = price;
            }

            emit IRainPool.PlaceBuyOrder({
                orderOption: option,
                orderOptionSide: optionSide,
                orderPrice: price,
                baseAmount: amount,
                orderID: orderID,
                maker: msg.sender
            });
        } else if (amount > 0) {
            // Remainder below the $0.10 resting floor: it can't rest, so refund it to the taker
            // (same as the enterOption OB path) rather than keep it in the pool. No event — the
            // fills already emitted ExecuteSellOrder.
            IERC20(ds.baseToken).safeTransfer(msg.sender, amount);
        }
    }

    /**
     * @dev True when a partial-fill remainder (`notionalBase`, in base token) clears the $0.10
     *      resting floor; below that it's dust and is dropped/returned instead of rested. This
     *      floor is intentionally below the $1 entry minimum — a remnant may be smaller than a
     *      fresh order yet still worth resting.
     */
    function _remainderWorthResting(LibDiamond.DiamondStorage storage ds, uint256 notionalBase) private returns (bool) {
        if (ds.baseToken == ds.usdt) {
            // baseTokenDecimals == 10**decimals, so /10 == $0.10 in base-token units.
            return notionalBase >= ds.baseTokenDecimals / 10;
        }
        // getQuoteOut returns the USDT-equivalent (6-dp); 1e5 == $0.10.
        return LibUtils.getQuoteOut(ds.baseToken, notionalBase, ds.tokenData) >= 1e5;
    }

    /**
     * @dev Normalize firstBuyOrderPrice down to the highest tick with a resting bid (0.01 sentinel
     *      if dry). Walkers step the pointer one tick and rely on the loop to keep scanning, but a
     *      size-exhausted sweep can exit with it parked on an empty tick — a stale best-bid that
     *      reads as a crossed book to readers/post-only/UI (F-2026-17921). Call after a sweep;
     *      no-op (single SLOAD) when already correct.
     */
    function _syncBestBid(
        LibDiamond.DiamondStorage storage ds,
        uint256 option,
        uint8 optionSide,
        uint256 fromLevel
    ) private {
        uint256 best = fromLevel;
        // 1-SLOAD/tick probe (LinkedListLogic.hasOrders) vs isEmpty's 3.
        while (best > ds.TICK_SPACING && !ds.buyOrders[option][optionSide][best].hasOrders()) {
            unchecked {
                best -= ds.TICK_SPACING;
            }
        }
        ds.firstBuyOrderPrice[option][optionSide] = best < ds.TICK_SPACING ? ds.TICK_SPACING : best;
    }

    /**
     * @dev Ask-side mirror of {_syncBestBid}: normalize firstSellOrderPrice to the lowest tick
     *      that still holds a resting ask at or above `fromLevel`, clamping to the 0.99 sentinel
     *      when the ask book is dry. Guards against the same size-exhausted-sweep stale pointer.
     */
    function _syncBestAsk(
        LibDiamond.DiamondStorage storage ds,
        uint256 option,
        uint8 optionSide,
        uint256 fromLevel
    ) private {
        uint256 best = fromLevel;
        // 1-SLOAD/tick probe (LinkedListLogic.hasOrders) vs isEmpty's 3.
        while (best < 0.99 ether && !ds.sellOrders[option][optionSide][best].hasOrders()) {
            unchecked {
                best += ds.TICK_SPACING;
            }
        }
        ds.firstSellOrderPrice[option][optionSide] = best > 0.99 ether ? 0.99 ether : best;
    }

    /**
     * @dev Per-option LP deposit: split into YES/NO shares, proportionally seed the AMM,
     *      claim any pending swap fees, and credit LP shares. Assumes `amount` base tokens
     *      have already been transferred into this contract by the caller.
     */
    function _addLiquidityToOption(
        LibDiamond.DiamondStorage storage ds,
        address user,
        uint256 option,
        uint256 amount,
        uint256 minYesToDeposit,
        uint256 minNoToDeposit
    ) private {
        if (ds.optionFinalized[option] || block.timestamp > ds.optionEndTime[option]) {
            _revert(IRainPool.SaleNotLive.selector);
        }

        // Initial-LP guard: when there is no outstanding LP supply, the AMM
        // must also be empty. Otherwise a fresh LP would be minted shares from
        // only their own deposit while gaining proportional ownership over
        // pre-existing reserves left behind by prior activity.
        if (ds.totalOptionLPShares[option] == 0 && (ds.ammYesReserve[option] != 0 || ds.ammNoReserve[option] != 0)) {
            _revert(IRainPool.InvalidPoolState.selector);
        }

        // ── 1. Split: collateral → equal YES + NO shares ────────────────────────
        ds.optionTotalFunds[option] += amount;
        ds.optionTotalShares[option] += amount;
        ds.optionPerSideFunds[option][1] += amount;
        ds.optionPerSideFunds[option][2] += amount;
        ds.optionPerSideShares[option][1] += amount;
        ds.optionPerSideShares[option][2] += amount;
        ds.userOptionPerSideShares[option][1][user] += amount;
        ds.userOptionPerSideShares[option][2][user] += amount;
        ds.totalMarketFunds += amount;
        ds.totalMarketShares += amount;


        // ── 2. Compute proportional deposit into AMM ────────────────────────────
        uint256 x = ds.ammYesReserve[option];
        uint256 y = ds.ammNoReserve[option];

        uint256 yesToDeposit;
        uint256 noToDeposit;

        if (x == 0 && y == 0) {
            yesToDeposit = amount / 2;
            noToDeposit = amount - yesToDeposit;
        } else {
            uint256 totalReserves = x + y;
            yesToDeposit = (amount * x) / totalReserves;
            noToDeposit = amount - yesToDeposit;
        }

        // Slippage guard: the split tracks the live reserve ratio, so a deposit ordered
        // behind a swap/deposit that skewed the pool can deploy a composition the LP
        // never consented to. Honour the caller-declared per-side floors.
        if (yesToDeposit < minYesToDeposit || noToDeposit < minNoToDeposit) {
            _revert(IRainPool.SlippageExceeded.selector);
        }

        // ── 3. Move the proportional shares from user's balance into AMM ────────
        ds.userOptionPerSideShares[option][1][user] -= yesToDeposit;
        ds.userOptionPerSideShares[option][2][user] -= noToDeposit;

        ds.ammYesReserve[option] += yesToDeposit;
        ds.ammNoReserve[option] += noToDeposit;

        // ── 3a. Emit events for leftover direct shares ──────────────────────────
        uint256 yesLeftover = amount - yesToDeposit;
        uint256 noLeftover = amount - noToDeposit;

        if (yesLeftover > 0) {
            emit IRainPool.EnterOption({
                option: option,
                optionSide: 1,
                baseAmount: yesLeftover,
                sharesAmount: yesLeftover,
                wallet: user
            });
        }

        if (noLeftover > 0) {
            emit IRainPool.EnterOption({
                option: option,
                optionSide: 2,
                baseAmount: noLeftover,
                sharesAmount: noLeftover,
                wallet: user
            });
        }

        // ── 4. Claim pending swap fees before updating LP shares ─────────────────
        if (ds.userOptionLPShares[option][user] > 0) {
            uint256 pendingFees = ((ds.feePerLPShareX128[option] - ds.userFeeDebtX128[option][user]) *
                ds.userOptionLPShares[option][user]) >> 128;

            if (pendingFees > 0) {
                IERC20(ds.baseToken).safeTransfer(user, pendingFees);
                emit IRainPool.ClaimSwapFees(option, pendingFees, user);
            }
        }

        // ── 5. Calculate and issue LP shares ────────────────────────────────────
        uint256 lpShares;
        uint256 currentTotalLPShares = ds.totalOptionLPShares[option];

        if (currentTotalLPShares == 0) {
            lpShares = amount;
        } else {
            // Use the AMM-reserve total captured before the deposit. `optionTotalFunds`
            // is unsafe here: split()/merge() can move it independently of AMM reserves,
            // which would let an attacker manipulate the LP-share denominator.
            lpShares = Math.mulDiv(amount, currentTotalLPShares, x + y);
        }

        if (lpShares == 0) {
            _revert(IRainPool.LPSharesZero.selector);
        }

        ds.userOptionLPShares[option][user] += lpShares;
        ds.totalOptionLPShares[option] += lpShares;

        // ── 6. Snapshot fee debt at current accumulator ──────────────────────────
        ds.userFeeDebtX128[option][user] = ds.feePerLPShareX128[option];

        emit IRainPool.AddLiquidity(option, amount, lpShares, user);
        emit IRainPool.Price(option, ds.ammYesReserve[option], ds.ammNoReserve[option], ds.optionTotalFunds[option]);
    }

    /**
     * @dev Accrues swap fee to LP reward accumulator (fee-per-share pattern).
     *      Fee tokens stay in the contract; LPs claim them via removeLiquidity or enterLiquidity.
     */
    function _accrueSwapFee(LibDiamond.DiamondStorage storage ds, uint256 option, uint256 fee) private {
        uint256 totalLP = ds.totalOptionLPShares[option];
        if (fee > 0 && totalLP > 0) {
            ds.feePerLPShareX128[option] += (fee << 128) / totalLP;
        }
    }

    function getCurrentPrice(uint256 option, uint8 optionSide) internal view returns (uint256) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        uint256 x = ds.ammYesReserve[option];
        uint256 y = ds.ammNoReserve[option];
        uint256 total = x + y;
        if (total == 0) return 0;
        // CPMM: price(YES=1) = y/(x+y),  price(NO=2) = x/(x+y)
        return optionSide == 1 ? (y * ds.PRICE_MAGNIFICATION) / total : (x * ds.PRICE_MAGNIFICATION) / total;
    }

    function getReturnedShares(uint256 option, uint8 optionSide, uint256 amount) internal view returns (uint256) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        uint256 x = ds.ammYesReserve[option];
        uint256 y = ds.ammNoReserve[option];
        // CPMM: split A tokens → A YES + A NO, then sell opposite side into AMM
        // Buying YES: total shares = A * (x + y + A) / (y + A)
        // Buying NO:  total shares = A * (x + y + A) / (x + A)
        uint256 denom = optionSide == 1 ? y + amount : x + amount;
        return Math.mulDiv(amount, x + y + amount, denom);
    }

    function getAmountRequired(
        uint256 targetPrice,
        uint256 option,
        uint8 optionSide
    ) internal view returns (uint256 requiredAmount) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        uint256 M = ds.PRICE_MAGNIFICATION;
        uint256 x = ds.ammYesReserve[option];
        uint256 y = ds.ammNoReserve[option];

        if (x == 0 || y == 0) {
            _revert(IRainPool.InvalidPoolState.selector);
        }
        if (targetPrice >= M) {
            _revert(IRainPool.EndPriceTooHigh.selector);
        }

        // CPMM: to reach price p on the bought side, the opposite reserve must reach:
        //   reserveTarget = sqrt(k * p / (M - p))  where k = x * y
        // Amount of base token needed = reserveTarget - currentOppositeReserve
        uint256 kTimesP = Math.mulDiv(x, Math.mulDiv(y, targetPrice, M - targetPrice), 1);
        uint256 reserveTarget = Math.sqrt(kTimesP);
        // Ceiling sqrt to ensure we actually reach the target price
        if (reserveTarget * reserveTarget < kTimesP) {
            unchecked {
                ++reserveTarget;
            }
        }

        // For YES (side 1): NO reserve (y) must grow → amount = reserveTarget - y
        // For NO  (side 2): YES reserve (x) must grow → amount = reserveTarget - x
        uint256 currentReserve = optionSide == 1 ? y : x;
        if (reserveTarget <= currentReserve) return 1;
        requiredAmount = reserveTarget - currentReserve;
    }

    /**
     * @dev Terminally removes a resting sell order and releases the maker's share escrow for the
     *      removed `amount`. Shared by both dust-eviction paths in {_executeSellOrder} (the
     *      zero-proceeds guard and the sub-$0.10 partial-fill remainder). The freed shares stay in
     *      the maker's available balance (`userOptionPerSideShares` is intentionally NOT touched —
     *      nothing is burned). State-only: the caller emits CancelSellOrder so the event can be
     *      ordered AFTER the ExecuteSellOrder of the same fill.
     */
    function _evictSellOrder(
        LibDiamond.DiamondStorage storage ds,
        uint256 option,
        uint8 optionSide,
        uint256 price,
        uint256 orderID,
        address sellerAddress,
        uint256 amount
    ) private {
        int256 nodeIndex = ds.orderBook[option][optionSide][price][orderID].index;
        ds.sellOrders[option][optionSide][price].remove(nodeIndex);
        ds.orderBook[option][optionSide][price][orderID].exists = false;
        ds.orderBook[option][optionSide][price][orderID].index = 0;
        ds.userActiveSellOrdersPerOption[option][sellerAddress]--;
        ++ds.ordersRemoved;
        ds.userSharesPerSideInEscrow[option][optionSide][sellerAddress] -= amount;
    }

    /**
     * @dev Executes a specific sell order in the order book.
     * Validates the order ID, order existence, price tick spacing, and updates or removes the order accordingly.
     * @param option The index of the option being bought.
     * @param optionSide The side of the option (1 or 2).
     * @param price The price per unit for the sell order.
     * @param fundsAmount The amount of funds user provides to buy the order.
     * @param orderID The unique identifier of the sell order to be fulfilled.
     * @param buyerAddress THe address of the buyer executing the order.
     * @return amountExecuted The amount in baseToken recieved by the seller.
     * @return shareAmount The amount of shares recieved by the buyer.
     */
    function _executeSellOrder(
        uint256 option,
        uint8 optionSide,
        uint256 price,
        uint256 fundsAmount,
        uint256 orderID,
        address buyerAddress
    ) private returns (uint256 amountExecuted, uint256 shareAmount, bool orderRemoved) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        LinkedListStorage.LinkedList storage linkedList = ds.sellOrders[option][optionSide][price];

        int256 nodeIndex = ds.orderBook[option][optionSide][price][orderID].index;

        uint256 orderAmount = LinkedListLogic.getAmount(linkedList, nodeIndex);
        address sellerAddress = LinkedListLogic.getMaker(linkedList, nodeIndex);

        // Taker (buyerAddress) pays the maker rebate AND the protocol fee on top of the
        // maker's notional, so size the fillable shares down to leave room for both:
        // gross·(MAG + rebate + protocolFeeRate)/MAG must fit inside the taker's `fundsAmount`.
        uint256 maxGross = (fundsAmount * ds.FEE_MAGNIFICATION) /
            (ds.FEE_MAGNIFICATION + ds.MAKER_REBATE_FEE + LibDiamond.tradeFeeRate());
        shareAmount = (maxGross * ds.PRICE_MAGNIFICATION) / price;
        {
            uint256 fillShares = orderAmount <= shareAmount ? orderAmount : shareAmount;
            if ((fillShares * price) / ds.PRICE_MAGNIFICATION == 0) {
                if (orderAmount <= shareAmount) {
                    // Zero-proceeds dust: resting order too small to yield any base. Evict it so it
                    // doesn't strand as "open" off-chain (F-2026-17847). No fill here, so emit now.
                    _evictSellOrder(ds, option, optionSide, price, orderID, sellerAddress, orderAmount);
                    emit IRainPool.CancelSellOrder({
                        orderOption: option,
                        orderOptionSide: optionSide,
                        sharesAmount: orderAmount,
                        orderPrice: price,
                        orderID: orderID,
                        orderCreator: sellerAddress
                    });
                    return (0, 0, true);
                }
                return (0, 0, false);
            }
        }

        uint256 evictedRemainder;
        if (orderAmount <= shareAmount) {
            linkedList.remove(nodeIndex);
            ds.orderBook[option][optionSide][price][orderID].exists = false;
            ds.orderBook[option][optionSide][price][orderID].index = 0;
            ds.userActiveSellOrdersPerOption[option][sellerAddress]--;
            ++ds.ordersRemoved;
            shareAmount = orderAmount;
            orderRemoved = true;
        } else {
            uint256 remaining = orderAmount - shareAmount;
            // Maker-dust eviction (F-2026-17922): if the fill leaves a sub-$0.10 remainder, evict
            // it rather than leave a dust order that locks escrow and blocks the maker's claim.
            // Escrow is released; the sliver shares stay available (NOT burned — burning could
            // forfeit far more than $0.10 of face value on low-priced orders). Cancel is emitted
            // after ExecuteSellOrder below (fill first, then leftover eviction).
            if (_remainderWorthResting(ds, (remaining * price) / ds.PRICE_MAGNIFICATION)) {
                ds.sellOrders[option][optionSide][price].nodes[nodeIndex].data.amount -= shareAmount;
            } else {
                _evictSellOrder(ds, option, optionSide, price, orderID, sellerAddress, remaining);
                evictedRemainder = remaining;
                orderRemoved = true;
            }
            orderAmount = shareAmount;
        }

        ds.userSharesPerSideInEscrow[option][optionSide][sellerAddress] -= orderAmount;

        ds.userOptionPerSideShares[option][optionSide][buyerAddress] += orderAmount;
        ds.userOptionPerSideShares[option][optionSide][sellerAddress] -= orderAmount;

        {
            uint256 grossProceeds = (orderAmount * price) / (ds.PRICE_MAGNIFICATION);

            // 1.2% rebate credited to the maker (the resting sell order that got filled).
            uint256 makerRebate = (grossProceeds * ds.MAKER_REBATE_FEE) / ds.FEE_MAGNIFICATION;

            // Protocol fee: taker (buyer) also pays this on top; it stays in the
            // contract, credited to the per-option fee accumulators for claim-time payout.
            uint256 protocolFee = LibDiamond.collectTradeFee(option, grossProceeds);

            // Taker pays the maker's full notional plus the rebate plus the protocol fee.
            amountExecuted = grossProceeds + makerRebate + protocolFee;

            // Maker is made whole on their notional and earns the rebate on top.
            IERC20(ds.baseToken).safeTransfer(sellerAddress, grossProceeds + makerRebate);

            emit IRainPool.ExecuteSellOrder({
                orderOption: option,
                orderOptionSide: optionSide,
                orderPrice: price,
                sharesAmount: orderAmount,
                baseAmount: grossProceeds,
                orderID: orderID,
                maker: sellerAddress,
                taker: buyerAddress
            });

            if (makerRebate > 0) {
                emit IRainPool.MakerRebate(sellerAddress, option, optionSide, makerRebate);
            }
        }

        // Eviction Cancel after the fill above, so the log reads "filled, then evicted".
        if (evictedRemainder > 0) {
            emit IRainPool.CancelSellOrder({
                orderOption: option,
                orderOptionSide: optionSide,
                sharesAmount: evictedRemainder,
                orderPrice: price,
                orderID: orderID,
                orderCreator: sellerAddress
            });
        }
    }

    /**
     * @dev Buy-side mirror of {_evictSellOrder}: terminally removes a resting buy order, releases
     *      the maker's funds escrow and REFUNDS `amount` base tokens to the maker. Unlike the sell
