// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

import { IDiamondCut } from "../interfaces/IDiamondCut.sol";

import { IDiamondLoupe } from "../interfaces/IDiamondLoupe.sol";

import { IERC165 } from "../interfaces/IERC165.sol";

import { LinkedListStorage } from "../../interfaces/LinkedListStorage.sol";

import { LinkedListLogic } from "../../libraries/LinkedList.sol";

import { IRainPool } from "../../interfaces/IRainPool.sol";

import { IRainDeployer } from "../../interfaces/IRainDeployer.sol";

import { Types } from "../shared/Types.sol";

import { LibUtils } from "./LibUtils.sol";

import { _revert } from "../../utils/Globals.sol";

// Remember to add the loupe functions from DiamondLoupeFacet to the diamond.
// The loupe functions are required by the EIP2535 Diamonds standard

error NoSelectorsProvidedForFacetForCut(address _facetAddress);
error CannotAddSelectorsToZeroAddress(bytes4[] _selectors);
error NoBytecodeAtAddress(address _contractAddress, string _message);
error IncorrectFacetCutAction(uint8 _action);
error CannotAddFunctionToDiamondThatAlreadyExists(bytes4 _selector);
error CannotReplaceFunctionsFromFacetWithZeroAddress(bytes4[] _selectors);
error CannotReplaceImmutableFunction(bytes4 _selector);
error CannotReplaceFunctionWithTheSameFunctionFromTheSameFacet(bytes4 _selector);
error CannotReplaceFunctionThatDoesNotExists(bytes4 _selector);
error RemoveFacetAddressMustBeZeroAddress(address _facetAddress);
error CannotRemoveFunctionThatDoesNotExist(bytes4 _selector);
error CannotRemoveImmutableFunction(bytes4 _selector);
error InitializationFunctionReverted(address _initializationContractAddress, bytes _calldata);

/**
 * @title LibDiamond
 * @author Rain Team
 * @notice Library for accessing, managing and initializing the diamond's shared application storage.
 * @dev Implements EIP-2535 Diamond Standard to ensure consistent state access across all facets in the diamond.
 */
library LibDiamond {
    using LinkedListLogic for LinkedListStorage.LinkedList;

    event DiamondCut(IDiamondCut.FacetCut[] _diamondCut, address _init, bytes _calldata);

    bytes32 internal constant DIAMOND_STORAGE_POSITION = keccak256("diamond.standard.diamond.storage");

    struct FacetAddressAndSelectorPosition {
        address facetAddress;
        uint16 selectorPosition;
    }

    /**
     * @title DiamondStorage
     * @notice Main storage structure for the RainPool diamond proxy.
     * @dev Uses diamond storage pattern to avoid storage collisions between facets.
     * @dev See {IGetter}.
     */
    struct DiamondStorage {
        ////////////////////////
        // Diamond Based Storage
        ////////////////////////
        mapping(bytes4 => FacetAddressAndSelectorPosition) facetAddressAndSelectorPosition;
        bytes4[] selectors;
        mapping(bytes4 => bool) supportedInterfaces;
        bool isInitialized;
        ////////////////////
        // App Based Storage
        ////////////////////
        uint256 PRICE_MAGNIFICATION;
        uint256 FEE_MAGNIFICATION;
        uint256 TICK_SPACING;
        uint256 ORDER_EXECUTION_FEE;
        uint256 MAKER_REBATE_FEE;
        uint256 DISPUTE_WINDOW;
        uint256 PHASE_B_DELAY;
        uint256 DISPUTE_FEE_MAX;
        uint256 DISPUTE_FEE_MIN;
        uint256 APPEAL_FEE_MIN;
        uint256 RESOLUTION_FEE_MIN;
        uint256 RESOLUTION_FEE_MAX;
        uint256 MINIMUM_LIQUIDITY;
        uint256 startTime;
        uint256 endTime;
        uint256 numberOfOptions;
        uint256 platformFee;
        uint256 liquidityFee;
        uint256 creatorFee;
        uint256 closingFee;
        uint256 resultResolverFee;
        // MUST be 0. A too-early appeal reopens the option; a nonzero oracleFixedFee would then
        // be paid twice (once to the too-early oracle, again on re-resolution) out of the shared
        // oracle-fee buffer — a solvency drain. See ResolutionFacet.resolveAppealTooEarly.

        uint256 oracleFixedFee;
        // Duration (seconds) of the appeal oracle voting window. Consumed at
        // openDispute (appeal branch) as `block.timestamp + oracleEndTime`.
        // Not an absolute timestamp — see IRainPool.Params docs.
        uint256 oracleEndTime;
        uint256 ordersAdded;
        uint256 ordersRemoved;
        uint256 baseTokenDecimals;
        string ipfsUri;
        address FACTORY;
        address baseToken;
        address rainToken;
        address usdt;
        address poolOwner;
        address platformAddress;
        address resolver;
        address disputeResolver;
        address referrer;
        bool isPublic;
        bool resolverIsAI;
        ////////////////////
        // Level 3 — Global (across all options and sides)
        ////////////////////
        uint256 totalMarketFunds;
        uint256 totalMarketShares;
        ////////////////////
        // V2 AMM — Per Option
        ////////////////////
        mapping(uint256 option => uint256) ammYesReserve;
        mapping(uint256 option => uint256) ammNoReserve;
        /// @dev DEPRECATED — never written, always reads 0.
        mapping(uint256 option => uint256) resolverShareUSDT;
        ///////////////////
        // V2 LP Shares — Per Option
        ////////////////////
        mapping(uint256 option => uint256) totalOptionLPShares;
        mapping(uint256 option => mapping(address user => uint256)) userOptionLPShares;
        ////////////////////
        // V2 Swap Fee Accumulator — Per Option
        ////////////////////
        mapping(uint256 option => uint256) feePerLPShareX128;
        mapping(uint256 option => mapping(address user => uint256)) userFeeDebtX128;
        ////////////////////
        // Level 2 — Per Option (Yes + No combined)
        ////////////////////
        mapping(uint256 option => bool) optionFinalized;
        mapping(uint256 option => uint256 funds) optionTotalFunds;
        mapping(uint256 option => uint256 shares) optionTotalShares;
        ////////////////////
        // Level 1 — Per Option Per Side (1 or 2)
        ////////////////////
        mapping(uint256 option => mapping(uint8 optionSide => uint256 funds)) optionPerSideFunds;
        mapping(uint256 option => mapping(uint8 optionSide => uint256 shares)) optionPerSideShares;
        mapping(uint256 option => mapping(uint8 optionSide => mapping(address user => uint256 shares))) userOptionPerSideShares;
        mapping(uint256 option => mapping(uint8 optionSide => mapping(address user => uint256 shares))) userSharesPerSideInEscrow;
        mapping(uint256 option => mapping(uint8 optionSide => mapping(address user => uint256 amount))) userFundsPerSideInEscrow;
        ////////////////////
        // Order Book — Per Option Per Side (1 or 2)
        ////////////////////
        mapping(uint256 option => mapping(uint8 optionSide => mapping(uint256 price => LinkedListStorage.LinkedList orderID))) sellOrders;
        mapping(uint256 option => mapping(uint8 optionSide => mapping(uint256 price => LinkedListStorage.LinkedList orderID))) buyOrders;
        mapping(uint256 option => mapping(uint8 optionSide => mapping(uint256 price => mapping(uint256 orderID => IRainPool.OrderExists orderExists)))) orderBook;
        mapping(uint256 option => mapping(uint8 optionSide => uint256 firstSellOrderPrice)) firstSellOrderPrice;
        mapping(uint256 option => mapping(uint8 optionSide => uint256 firstBuyOrderPrice)) firstBuyOrderPrice;
        ////////////////////
        // Resolution — Per Option
        ////////////////////
        mapping(uint256 option => uint8 optionSide) optionWinner;
        mapping(uint256 option => bool resolved) optionResolved;
        mapping(uint256 option => mapping(address user => bool claimed)) optionClaimed;
        mapping(uint256 option => address) optionResolutionProposer;
        mapping(uint256 option => uint256) optionResolverBond;
        mapping(uint256 option => uint8) optionProposedWinner;
        mapping(uint256 option => uint256) optionEndTime;
        mapping(uint256 option => uint256) optionEndTimeCache;
        mapping(uint256 option => uint256) optionPhaseBActivationTime;
        ////////////////////
        // Fee Shares — Per Option
        ////////////////////
        mapping(uint256 option => uint256) optionWinningPoolShare;
        mapping(uint256 option => uint256) optionPlatformShare;
        mapping(uint256 option => uint256) optionCreatorShare;
        mapping(uint256 option => uint256) optionResolverShare;
        mapping(uint256 option => uint256) optionClosingShare;
        mapping(uint256 option => uint256) optionOrderBookShare;
        mapping(uint256 option => bool) optionFirstClaim;
        ////////////////////
        // User order counts — per option (each option's book has its own 50-order cap)
        ////////////////////
        mapping(uint256 option => mapping(address user => uint256 activeOrders)) userActiveSellOrdersPerOption;
        mapping(uint256 option => mapping(address user => uint256 activeOrders)) userActiveBuyOrdersPerOption;
        ////////////////////
        // Other
        ////////////////////
        mapping(uint256 option => IRainPool.Dispute) optionDispute;
        mapping(uint256 option => IRainPool.Dispute) optionAppeal;
        mapping(uint256 option => IRainPool.PoolState) optionState;
        mapping(uint256 option => bool) isOptionAppealed;
        mapping(uint256 option => address) optionResolver;
        mapping(uint256 option => bool) isOptionDisputed;
        IRainDeployer.TokenData tokenData;
        IRainPool.TradingModel tradingModel;
        uint256 CLOSE_GRACE_PERIOD;
        // Flat, non-refundable USDT charge added on top of the appeal stake and forwarded straight to the oracle deployed for that appeal.
        uint256 appealOracleCost;
    }

    /**
     * @notice Initializes the diamond storage with pool parameters and initial liquidity.
     * @dev Sets up all core pool parameters, validates inputs, and distributes initial liquidity
     *      across options, splitting each option's liquidity equally between Yes and No sides.
     * @param params The initialization parameters containing all pool configuration.
     */
    function initializeDiamond(IRainPool.Params memory params) internal {
        DiamondStorage storage ds = diamondStorage();

        if (params.baseToken == address(0) || params.rainToken == address(0)) {
            _revert(IRainPool.NoTokenSet.selector);
        }
        if (params.poolOwner == address(0)) {
            _revert(IRainPool.NoOwnerSet.selector);
        }
        if (params.platformAddress == address(0)) {
            _revert(IRainPool.NoPlatformSet.selector);
        }
        if (params.startTime <= block.timestamp) {
            _revert(IRainPool.StartTimeEnded.selector);
        }
        if (params.endTime <= params.startTime) {
            _revert(IRainPool.EndTImeLessThanStartTime.selector);
        }
        if (params.numberOfOptions == 0) {
            _revert(IRainPool.InvalidOptions.selector);
        }
        if (params.numberOfOptions > 50) {
            _revert(IRainPool.MaximumOptionsExceeded.selector);
        }
        // oracleFixedFee is deliberately unvalidated and expected to be 0 — the appeal oracle is
        // funded by the accumulated resolver share alone.
        // oracleEndTime is a duration consumed at openDispute(appeal) as
        // block.timestamp + oracleEndTime. Zero would create an instantly-expired
        // oracle deadline and strand appealed claims at ClaimFacet's timeout gate.
        if (params.oracleEndTime == 0) {
            _revert(IRainPool.InvalidOracleEndTime.selector);
        }

        ds.isPublic = params.isPublic;
        ds.resolverIsAI = params.resolverIsAI;
        ds.FACTORY = params.deployerContract;
        ds.baseToken = params.baseToken;
        ds.poolOwner = params.poolOwner;
        ds.resolver = params.resolver;

        ds.disputeResolver = params.disputeResolver;
        ds.startTime = params.startTime;
        ds.endTime = params.endTime;
        ds.numberOfOptions = params.numberOfOptions;
        ds.platformAddress = params.platformAddress;
        ds.platformFee = params.platformFee;
        ds.rainToken = params.rainToken;
        ds.usdt = params.usdt;
        ds.referrer = params.referrer;
        ds.liquidityFee = params.liquidityFee;
        ds.creatorFee = params.creatorFee;
        ds.resultResolverFee = params.resultResolverFee;
        ds.closingFee = params.closingFee;
        ds.oracleFixedFee = params.oracleFixedFee;
        ds.appealOracleCost = params.appealOracleCost;
        ds.oracleEndTime = params.oracleEndTime;
        ds.ipfsUri = params.ipfsUri;
        ds.baseTokenDecimals = 10 ** params.baseTokenDecimals;
        ds.tokenData = params.tokenData;
        ds.tradingModel = params.tradingModel;

        ds.PRICE_MAGNIFICATION = 10 ** 18;
        ds.FEE_MAGNIFICATION = 10 ** 3;
        ds.TICK_SPACING = 0.01 ether;
        // Order-book burn fee removed — OB fills only charge the maker rebate below.
        ds.ORDER_EXECUTION_FEE = 0;
        ds.MAKER_REBATE_FEE = 12;

        uint256 maxFee = ds.FEE_MAGNIFICATION / 5;
        if (
            ds.platformFee > maxFee || ds.creatorFee > maxFee || ds.resultResolverFee > maxFee || ds.closingFee > maxFee
        ) {
            _revert(IRainDeployer.InvalidFeeConfiguration.selector);
        }
        if (ds.platformFee + ds.creatorFee + ds.resultResolverFee + ds.closingFee >= ds.FEE_MAGNIFICATION) {
            _revert(IRainDeployer.InvalidFeeConfiguration.selector);
        }

        ds.supportedInterfaces[type(IERC165).interfaceId] = true;
        ds.supportedInterfaces[type(IDiamondCut).interfaceId] = true;
        ds.supportedInterfaces[type(IDiamondLoupe).interfaceId] = true;

        ds.DISPUTE_WINDOW = 5 minutes;
        ds.PHASE_B_DELAY = 60 seconds;
        ds.CLOSE_GRACE_PERIOD = 30 minutes;
        ds.DISPUTE_FEE_MAX = 1000 * (10 ** ERC20(ds.usdt).decimals());
        ds.DISPUTE_FEE_MIN = 10 * (10 ** ERC20(ds.usdt).decimals());
        ds.APPEAL_FEE_MIN = 20 * (10 ** ERC20(ds.usdt).decimals());
        ds.RESOLUTION_FEE_MIN = 300 * (10 ** ERC20(ds.usdt).decimals());
        ds.RESOLUTION_FEE_MAX = 1000 * (10 ** ERC20(ds.usdt).decimals());
        ds.MINIMUM_LIQUIDITY = 10 * (10 ** ERC20(ds.usdt).decimals());
        // Validate liquidityPercentages — one per option, must sum to 10_000
        // 100 = 1%, so 10_000 = 100%
        if (params.liquidityPercentages.length != params.numberOfOptions) {
            _revert(IRainPool.ArrayLengthMismatch.selector);
        }

        // Validate initialYesPrices — one opening YES price per option.
        // Per-entry tick/range validation happens in the AMM branch below where
        // the price is consumed; OrderBook pools ignore the values.
        if (params.initialYesPrices.length != params.numberOfOptions) {
            _revert(IRainPool.ArrayLengthMismatch.selector);
        }

        uint256 liquidityPercentageSum = 0;
        uint256 i = 0;
        for (; i < params.liquidityPercentages.length; ) {
            if (params.liquidityPercentages[i] < 100) {
                _revert(IRainPool.InvalidLiquidityPercentage.selector);
            }
            liquidityPercentageSum += params.liquidityPercentages[i];
            unchecked {
                ++i;
            }
        }
        if (liquidityPercentageSum != 10_000) {
            _revert(IRainPool.InvalidLiquidityPercentage.selector);
        }

        // Minimum initial liquidity floor, denominated in USDT:
        //   - AMM pools:       $10 (MINIMUM_LIQUIDITY)
        //   - OrderBook pools:  $100 — this liquidity is seeded as real resting
        //     asks on both sides of every option (see the OB branch below), so the
        //     floor is raised to guarantee a meaningful opening book rather than a
        //     no-op charge.
        // If baseToken != USDT, convert via Uniswap quoter with 1% slippage pad.
        uint256 minRequiredLiquidity = params.tradingModel == Types.TradingModel.OrderBook
            ? 100 * (10 ** ERC20(ds.usdt).decimals())
            : ds.MINIMUM_LIQUIDITY;
        if (ds.baseToken != ds.usdt) {
            minRequiredLiquidity = LibUtils.getQuoteIn(minRequiredLiquidity, ds.tokenData);
            minRequiredLiquidity = (minRequiredLiquidity * 1010) / 1000;
        }
        if (params.initialLiquidity < minRequiredLiquidity) {
            _revert(IRainPool.InvalidInitialLiquidity.selector);
        }

        i = 1;
        for (; i <= ds.numberOfOptions; ) {
            // Total funds allocated to this option based on its percentage
            // e.g. 6000 = 60% → optionAllocation = 60% of initialLiquidity
            uint256 optionAllocation = (params.initialLiquidity * params.liquidityPercentages[i - 1]) / 10_000;

            // Shared invariants (both modes): split optionAllocation into equal YES + NO
            // on per-side / per-option / global totals.
            ds.optionPerSideFunds[i][1] = optionAllocation;
            ds.optionPerSideFunds[i][2] = optionAllocation;
            ds.optionPerSideShares[i][1] = optionAllocation;
            ds.optionPerSideShares[i][2] = optionAllocation;

            ds.optionTotalFunds[i] = optionAllocation;
            ds.optionTotalShares[i] = optionAllocation;

            ds.totalMarketFunds += optionAllocation;
            ds.totalMarketShares += optionAllocation;

            ds.optionResolved[i] = false;
            ds.optionEndTime[i] = params.endTime;
            ds.optionResolver[i] = params.resolverIsAI ? params.resolver : params.disputeResolver;

            emit IRainPool.ResolverSet({ resolver: ds.optionResolver[i], option: i });

            if (params.tradingModel == Types.TradingModel.AMM) {
                uint256 yesPrice = params.initialYesPrices[i - 1];
                if (yesPrice < ds.TICK_SPACING || yesPrice > 0.99 ether || yesPrice % ds.TICK_SPACING != 0) {
                    _revert(IRainPool.InvalidPrice.selector);
                }

                uint256 noReserve = (optionAllocation * yesPrice) / ds.PRICE_MAGNIFICATION;
                uint256 yesReserve = optionAllocation - noReserve;

                if (yesReserve == 0 || noReserve == 0) {
                    _revert(IRainPool.InvalidPoolState.selector);
                }

                // Pool owner holds residual shares (portion not deposited into AMM),
                // mirroring what enterLiquidity() does for normal LPs.
                ds.userOptionPerSideShares[i][1][ds.poolOwner] = optionAllocation - yesReserve;
                ds.userOptionPerSideShares[i][2][ds.poolOwner] = optionAllocation - noReserve;

                // LP shares — credit pool owner with initial liquidity per option
                ds.totalOptionLPShares[i] = optionAllocation;
                ds.userOptionLPShares[i][ds.poolOwner] = optionAllocation;

                // AMM reserves — seed by the creator's opening price
                ds.ammYesReserve[i] = yesReserve;
                ds.ammNoReserve[i] = noReserve;

                emit IRainPool.EnterOption({
                    option: i,
                    optionSide: 1,
                    baseAmount: yesReserve,
                    sharesAmount: optionAllocation - yesReserve,
                    wallet: params.poolOwner
                });
                emit IRainPool.EnterOption({
                    option: i,
                    optionSide: 2,
                    baseAmount: noReserve,
                    sharesAmount: optionAllocation - noReserve,
                    wallet: params.poolOwner
                });
                emit IRainPool.Price(i, ds.ammYesReserve[i], ds.ammNoReserve[i], ds.optionTotalFunds[i]);
                emit IRainPool.AddLiquidity(i, optionAllocation, optionAllocation, params.poolOwner);
            } else {
                // OrderBook: the pool owner's optionAllocation is split into YES + NO
                // shares and immediately seeded as real resting asks on both sides at the
                // creator's chosen price. Selling NO @ (1 - yesPrice) is economically a bid
                // on YES @ yesPrice, so the two asks together open a two-sided book at the
                // creator's odds. No AMM reserves, no LP shares.
                uint256 yesPrice = params.initialYesPrices[i - 1];
                if (yesPrice < ds.TICK_SPACING || yesPrice > 0.99 ether || yesPrice % ds.TICK_SPACING != 0) {
                    _revert(IRainPool.InvalidPrice.selector);
                }
                // Complement price for the NO side. yesPrice is a 0.01-multiple in
                // [0.01, 0.99] ether, so noPrice lands in the same valid, tick-aligned range.
                uint256 noPrice = ds.PRICE_MAGNIFICATION - yesPrice;

                // Owner holds the full optionAllocation (gross) on both sides.
                ds.userOptionPerSideShares[i][1][ds.poolOwner] = optionAllocation;
                ds.userOptionPerSideShares[i][2][ds.poolOwner] = optionAllocation;

                // Buy books start empty (bid-side liquidity lives as the complementary asks).
                ds.firstBuyOrderPrice[i][1] = 0.01 ether;
                ds.firstBuyOrderPrice[i][2] = 0.01 ether;

                // Split event mirrors the owner splitting collateral into YES + NO shares.
                emit IRainPool.Split(i, optionAllocation, params.poolOwner);

                // Price event carries the creator's opening odds for the indexer (same
                // encoding as the AMM path: pseudo-reserves derived from yesPrice).
                uint256 noReserve = (optionAllocation * yesPrice) / ds.PRICE_MAGNIFICATION;
                uint256 yesReserve = optionAllocation - noReserve;
                emit IRainPool.Price(i, yesReserve, noReserve, ds.optionTotalFunds[i]);

                // Seed the resting asks: YES @ yesPrice and NO @ noPrice, each for the full
                // per-side allocation. Emits a standard PlaceSellOrder per ask so the indexer
                // treats them as ordinary book orders (zero backend changes).
                _seedOrderBookAsk(ds, i, 1, yesPrice, optionAllocation);
                _seedOrderBookAsk(ds, i, 2, noPrice, optionAllocation);
            }

            unchecked {
                ++i;
            }
        }
    }

    /**
     * @notice Seeds a single resting sell order (ask) on the book during initialization.
     * @dev Replicates the exact storage writes and event of a runtime {TradingFacet-placeSellOrder}
     *      so the indexer treats the seeded order as an ordinary book order (no backend changes).
     *      Used only by {initializeDiamond} for OrderBook pools. The runtime phase / order-limit /
     *      min-value / matching guards are intentionally omitted: the order is owner-funded from the
     *      already-validated initial liquidity, priced by the caller-validated opening odds, and
     *      placed before the pool is live, so none of those guards apply.
     * @param ds Diamond storage reference.
     * @param option 1-indexed option the ask belongs to.
     * @param side Option side (1 = YES, 2 = NO).
     * @param price Order price (1e18-scaled, tick-aligned; validated by the caller).
     * @param shares Share amount to rest, fully backed by the pool owner's gross per-side balance.
     */
    function _seedOrderBookAsk(
        DiamondStorage storage ds,
        uint256 option,
        uint8 side,
        uint256 price,
        uint256 shares
    ) private {
        address maker = ds.poolOwner;

        // Same preimage as runtime placeSellOrder, but with poolOwner as maker (init has no
        // msg.sender ask placer). ordersAdded increments per seeded order, keeping IDs unique
        // across both sides and every option even within the same block.
        uint256 orderID = uint256(keccak256(abi.encodePacked(price, block.number, ds.ordersAdded, maker)));

        LinkedListStorage.LinkedList storage linkedList = ds.sellOrders[option][side][price];
        if (!linkedList.isInitialized) {
            linkedList.initialize();
        }

        int256 idx = linkedList.append(
            LinkedListStorage.Order({ orderID: orderID, timestamp: block.timestamp, amount: shares, maker: maker })
        );

        ds.orderBook[option][side][price][orderID].exists = true;
        ds.orderBook[option][side][price][orderID].index = idx;

        ds.userActiveSellOrdersPerOption[option][maker]++;
        ds.userSharesPerSideInEscrow[option][side][maker] += shares;
        ++ds.ordersAdded;

        // Sole ask on this side at init, so it is the best (lowest) ask by construction.
        ds.firstSellOrderPrice[option][side] = price;

        emit IRainPool.PlaceSellOrder({
            orderOption: option,
            orderOptionSide: side,
            orderPrice: price,
            sharesAmount: shares,
            orderID: orderID,
            maker: maker
        });
    }

    function diamondStorage() internal pure returns (DiamondStorage storage ds) {
        bytes32 position = DIAMOND_STORAGE_POSITION;
        // solhint-disable-next-line no-inline-assembly
        assembly {
            ds.slot := position
        }
    }

    function enforceIsFactory() internal view {
        if (msg.sender != diamondStorage().FACTORY) {
            _revert(IRainPool.OnlyAuthority.selector);
        }
    }

    function enforceIsNotInitialized() internal view {
        if (diamondStorage().isInitialized == true) {
            _revert(IRainPool.AlreadyInitialized.selector);
        }
    }

    /// @dev Live-read of the deployer's primary AI resolver.
    ///
    ///      Late-bound on purpose. `RainDeployer.resolverAI` is owner-settable, so a single
    ///      `setResolverAI` call rotates the resolver for EVERY pool carrying this code at once.
    ///      That is the compromise-recovery path: `createdPools` is a plain mapping with no
    ///      on-chain enumeration, so a per-pool rotation loop could never reach every pool, and
    ///      `optionResolver` is keyed per option (up to 50 per pool) on top of that.
    ///
    ///      Adds no trust surface: the deployer is a UUPS proxy whose owner can already upgrade
    ///      its implementation, and every pool already depends on it for `createOracle`.
    ///
    ///      Only pools deployed with this facet follow the deployer — pools already live read
    ///      their own stored copy and cannot be migrated (`diamondCut` is locked post-init).
    function liveResolver(DiamondStorage storage ds) internal view returns (address) {
        return IRainDeployer(ds.FACTORY).resolverAI();
    }

    /// @dev Live-read of the deployer's dispute resolver. See {liveResolver}.
    function liveDisputeResolver(DiamondStorage storage ds) internal view returns (address) {
        return IRainDeployer(ds.FACTORY).disputeResolverAI();
    }

    /// @dev The resolver a freshly-created option answers to, mirroring the assignment this
    ///      library used to bake into `optionResolver` at init:
    ///      `resolverIsAI ? params.resolver : params.disputeResolver`.
    function baseResolver(DiamondStorage storage ds) internal view returns (address) {
        return ds.resolverIsAI ? liveResolver(ds) : liveDisputeResolver(ds);
    }

    /// @dev Authority entitled to call `chooseWinner` / `tooEarly` for `option`, derived from
    ///      resolution state rather than a stored copy.
    ///
    ///      Appealed options are the one carve-out and read the STORED slot: `optionResolver`
    ///      then holds the oracle CONTRACT deployed for that specific option
    ///      (see DisputeFacet.openDispute). That is a per-option address, not a rotatable role,
    ///      so it must never be late-bound — doing so would break the `IQuestion` reads in
    ///      ClaimFacet._firstClaimCheck.
    function currentResolver(DiamondStorage storage ds, uint256 option) internal view returns (address) {
        if (ds.isOptionAppealed[option]) {
            return ds.optionResolver[option];
        }
        if (ds.isOptionDisputed[option]) {
            return liveDisputeResolver(ds);
        }
        return baseResolver(ds);
    }

    function enforceAMMMode() internal view {
        if (diamondStorage().tradingModel != Types.TradingModel.AMM) {
            _revert(IRainPool.InvalidCall.selector);
        }
    }

    function enforceOrderBookMode() internal view {
        if (diamondStorage().tradingModel != Types.TradingModel.OrderBook) {
            _revert(IRainPool.InvalidCall.selector);
        }
    }

    /// @dev True only on AMM pools while the AMM trading window is live.
    ///      Pre-start, post-endTime, or once the option is finalized → false.
    function isAMMPhase(uint256 option) internal view returns (bool) {
        DiamondStorage storage ds = diamondStorage();
        if (ds.tradingModel != Types.TradingModel.AMM) return false;
        if (ds.optionFinalized[option]) return false;
        if (block.timestamp < ds.startTime) return false;
        if (block.timestamp > ds.endTime) return false;
        return true;
    }

    /// @dev True whenever order-book trading is permitted on this option.
    ///      OB pool: open from startTime, indefinitely, until closePool finalizes the option.
    ///      AMM pool: open once endTime passes or the option is finalized,
    ///                and stays open through any dispute/appeal cycle until claim opens.
    ///      For the manual closePool path (optionFinalized), a 60-second PHASE_B_DELAY
    ///      applies so in-flight AMM transactions can still land at fair AMM prices.
    ///      The natural endTime path has no delay — time-based transitions cannot be front-run.
    ///
    ///      Phase B does NOT end on a wall-clock timer. The dispute window
    ///      (optionEndTime + DISPUTE_WINDOW) only gates the handoff to claims AFTER the
    ///      option is finalized via closePool. Until then, OB trading stays open past
    ///      endTime so funds are never locked away on an option nobody has resolved yet.
    ///      Note closePool is no longer permissionless — see {isOptionParticipant} — but
    ///      every party with money at stake (the pool owner, and any trader or LP in the
    ///      option) is entitled to call it once CLOSE_GRACE_PERIOD has elapsed, so the
    ///      option can always be moved to resolution by someone who wants their funds.
    function isOBPhase(uint256 option) internal view returns (bool) {
        DiamondStorage storage ds = diamondStorage();
        if (
            ds.optionFinalized[option] &&
            ds.optionWinner[option] != 0 &&
            block.timestamp > ds.optionEndTime[option] + ds.DISPUTE_WINDOW
        ) {
            return false;
        }
        if (ds.tradingModel == Types.TradingModel.OrderBook) {
            return block.timestamp >= ds.startTime;
        }
        if (ds.optionFinalized[option]) {
            return block.timestamp >= ds.optionPhaseBActivationTime[option];
        }
        return block.timestamp > ds.endTime;
    }

    function enforceAMMPhase(uint256 option) internal view {
        if (!isAMMPhase(option)) {
            _revert(IRainPool.InvalidCall.selector);
        }
    }

    function enforceOBPhase(uint256 option) internal view {
        if (!isOBPhase(option)) {
            _revert(IRainPool.OrderBookPhaseNotOpen.selector);
        }
    }

    /// @dev True when `user` holds an economic position in `option`: outcome shares on
    ///      either side, an AMM LP position, or base token locked in a resting buy order.
    ///
    ///      `userSharesPerSideInEscrow` is deliberately not consulted — placeSellOrder
    ///      escrows shares without decrementing `userOptionPerSideShares` (see the note on
    ///      TradingFacet._executeSellOrder), so sell-order escrow is already a subset of the
    ///      gross balance. Buy-order escrow is NOT: a user whose only position is a resting
    ///      bid holds zero shares, which is why `userFundsPerSideInEscrow` is checked.
    ///
    ///      Used by ResolutionFacet to decide who may close an option — see the caller gate
    ///      in `_validateClosePool`.
    function isOptionParticipant(uint256 option, address user) internal view returns (bool) {
        DiamondStorage storage ds = diamondStorage();
        return
            ds.userOptionPerSideShares[option][1][user] > 0 ||
            ds.userOptionPerSideShares[option][2][user] > 0 ||
            ds.userOptionLPShares[option][user] > 0 ||
            ds.userFundsPerSideInEscrow[option][1][user] > 0 ||
            ds.userFundsPerSideInEscrow[option][2][user] > 0;
    }

    /// @dev Collects the protocol fee on `notional` at trade time and credits the
    ///      per-option fee accumulators (platform / creator / resolver / closing)
    ///      that claim() later distributes. The fee is paid by the taker on every
    ///      fill and is NOT added to optionTotalFunds, so winners claim the full pot
    ///      with no settlement deduction. Returns the total fee so the caller can net
    ///      it out of the trade. Rate is governed by the existing fee params, so the
    ///      total protocol fee is tunable in config without a code change.
    function collectTradeFee(uint256 option, uint256 notional) internal returns (uint256 totalFee) {
        DiamondStorage storage ds = diamondStorage();

        uint256 platformCut = (notional * ds.platformFee) / ds.FEE_MAGNIFICATION;
        uint256 creatorCut = (notional * ds.creatorFee) / ds.FEE_MAGNIFICATION;
        uint256 resolverCut = (notional * ds.resultResolverFee) / ds.FEE_MAGNIFICATION;
        uint256 closingCut = (notional * ds.closingFee) / ds.FEE_MAGNIFICATION;

        ds.optionPlatformShare[option] += platformCut;
        ds.optionCreatorShare[option] += creatorCut;
        ds.optionResolverShare[option] += resolverCut;
        ds.optionClosingShare[option] += closingCut;

        totalFee = platformCut + creatorCut + resolverCut + closingCut;
    }

    /// @dev Sum of the four protocol-fee rates. Used to size order-book fills so the
    ///      taker's funds cover gross + maker rebate + protocol fee.
    function tradeFeeRate() internal view returns (uint256) {
        DiamondStorage storage ds = diamondStorage();
        return ds.platformFee + ds.creatorFee + ds.resultResolverFee + ds.closingFee;
    }

    /// @dev Idempotently seeds order-book head/tail sentinels for an AMM pool that
    ///      has just entered Phase B. OB pools already have these set at init,
    ///      so the storage reads short-circuit and no writes occur.
    function ensureOBBookInitialized(uint256 option, uint8 side) internal {
        DiamondStorage storage ds = diamondStorage();
        if (ds.firstSellOrderPrice[option][side] == 0) {
            ds.firstSellOrderPrice[option][side] = 0.99 ether;
        }
        if (ds.firstBuyOrderPrice[option][side] == 0) {
            ds.firstBuyOrderPrice[option][side] = 0.01 ether;
        }
    }

    // Internal function version of diamondCut
    function diamondCut(IDiamondCut.FacetCut[] memory _diamondCut, address _init, bytes memory _calldata) internal {
        enforceIsNotInitialized();
        for (uint256 facetIndex; facetIndex < _diamondCut.length; facetIndex++) {
            bytes4[] memory functionSelectors = _diamondCut[facetIndex].functionSelectors;
            address facetAddress = _diamondCut[facetIndex].facetAddress;
            if (functionSelectors.length == 0) {
                revert NoSelectorsProvidedForFacetForCut(facetAddress);
            }
            IDiamondCut.FacetCutAction action = _diamondCut[facetIndex].action;
            if (action == IDiamondCut.FacetCutAction.Add) {
                addFunctions(facetAddress, functionSelectors);
            } else if (action == IDiamondCut.FacetCutAction.Replace) {
                replaceFunctions(facetAddress, functionSelectors);
            } else if (action == IDiamondCut.FacetCutAction.Remove) {
                removeFunctions(facetAddress, functionSelectors);
            } else {
                revert IncorrectFacetCutAction(uint8(action));
            }
        }
        emit DiamondCut(_diamondCut, _init, _calldata);
        initializeDiamondCut(_init, _calldata);
        diamondStorage().isInitialized = true;
    }

    function addFunctions(address _facetAddress, bytes4[] memory _functionSelectors) internal {
        if (_facetAddress == address(0)) {
            revert CannotAddSelectorsToZeroAddress(_functionSelectors);
        }
        DiamondStorage storage ds = diamondStorage();
        uint16 selectorCount = uint16(ds.selectors.length);
        enforceHasContractCode(_facetAddress, "LibDiamondCut: Add facet has no code");
        for (uint256 selectorIndex; selectorIndex < _functionSelectors.length; selectorIndex++) {
            bytes4 selector = _functionSelectors[selectorIndex];
            address oldFacetAddress = ds.facetAddressAndSelectorPosition[selector].facetAddress;
            if (oldFacetAddress != address(0)) {
                revert CannotAddFunctionToDiamondThatAlreadyExists(selector);
            }
            ds.facetAddressAndSelectorPosition[selector] = FacetAddressAndSelectorPosition(
                _facetAddress,
                selectorCount
            );
            ds.selectors.push(selector);
            selectorCount++;
        }
    }

    function replaceFunctions(address _facetAddress, bytes4[] memory _functionSelectors) internal {
        DiamondStorage storage ds = diamondStorage();
        if (_facetAddress == address(0)) {
            revert CannotReplaceFunctionsFromFacetWithZeroAddress(_functionSelectors);
        }
        enforceHasContractCode(_facetAddress, "LibDiamondCut: Replace facet has no code");
        for (uint256 selectorIndex; selectorIndex < _functionSelectors.length; selectorIndex++) {
            bytes4 selector = _functionSelectors[selectorIndex];
            address oldFacetAddress = ds.facetAddressAndSelectorPosition[selector].facetAddress;
            // can't replace immutable functions -- functions defined directly in the diamond in this case
            if (oldFacetAddress == address(this)) {
                revert CannotReplaceImmutableFunction(selector);
            }
            if (oldFacetAddress == _facetAddress) {
                revert CannotReplaceFunctionWithTheSameFunctionFromTheSameFacet(selector);
            }
            if (oldFacetAddress == address(0)) {
                revert CannotReplaceFunctionThatDoesNotExists(selector);
            }
            // replace old facet address
            ds.facetAddressAndSelectorPosition[selector].facetAddress = _facetAddress;
        }
    }

    function removeFunctions(address _facetAddress, bytes4[] memory _functionSelectors) internal {
        DiamondStorage storage ds = diamondStorage();
        uint256 selectorCount = ds.selectors.length;
        if (_facetAddress != address(0)) {
            revert RemoveFacetAddressMustBeZeroAddress(_facetAddress);
        }
        for (uint256 selectorIndex; selectorIndex < _functionSelectors.length; selectorIndex++) {
            bytes4 selector = _functionSelectors[selectorIndex];
            FacetAddressAndSelectorPosition memory oldFacetAddressAndSelectorPosition = ds
                .facetAddressAndSelectorPosition[selector];
            if (oldFacetAddressAndSelectorPosition.facetAddress == address(0)) {
                revert CannotRemoveFunctionThatDoesNotExist(selector);
            }

            // can't remove immutable functions -- functions defined directly in the diamond
            if (oldFacetAddressAndSelectorPosition.facetAddress == address(this)) {
                revert CannotRemoveImmutableFunction(selector);
            }
            // replace selector with last selector
            selectorCount--;
            if (oldFacetAddressAndSelectorPosition.selectorPosition != selectorCount) {
                bytes4 lastSelector = ds.selectors[selectorCount];
                ds.selectors[oldFacetAddressAndSelectorPosition.selectorPosition] = lastSelector;
                ds.facetAddressAndSelectorPosition[lastSelector].selectorPosition = oldFacetAddressAndSelectorPosition
                    .selectorPosition;
            }
            // delete last selector
            ds.selectors.pop();
            delete ds.facetAddressAndSelectorPosition[selector];
        }
    }

    function initializeDiamondCut(address _init, bytes memory _calldata) internal {
        if (_init == address(0)) {
            return;
        }
        enforceHasContractCode(_init, "LibDiamondCut: _init address has no code");
        (bool success, bytes memory error) = _init.delegatecall(_calldata);
        if (!success) {
            if (error.length > 0) {
                // bubble up error
                /// @solidity memory-safe-assembly
                assembly {
                    let returndata_size := mload(error)
                    revert(add(32, error), returndata_size)
                }
            } else {
                revert InitializationFunctionReverted(_init, _calldata);
            }
        }
    }

    function enforceHasContractCode(address _contract, string memory _errorMessage) internal view {
        uint256 contractSize;
        assembly {
            contractSize := extcodesize(_contract)
        }
        if (contractSize == 0) {
            revert NoBytecodeAtAddress(_contract, _errorMessage);
        }
    }
}

