// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { LibAccounting } from "../../libraries/LibAccounting.sol";

/**
 * @title Accounted
 * @notice Base for facets whose entrypoints move the pool's base token.
 * @dev Applied to entrypoints that can move the base token, counting the helpers they call. When
 *      a transfer is added to an entrypoint that does not have it, the modifier has to be added in
 *      the same change -- a missing hook does not fail, it drifts the ledger silently.
 *
 *      NEVER apply it to `DisputeFacet.unlockCallback`: that runs inside the already-wrapped
 *      `openDispute`, so it would count the same movement twice.
 */
abstract contract Accounted {
    /// @dev A modifier rather than calls at the end of the body, because Solidity runs the code
    ///      after `_;` even when the body returns early.
    modifier accounted() {
        uint256 snapshot = LibAccounting.snapshot();
        _;
        LibAccounting.settle(snapshot);
    }
}

src/diamond/facets/ResolutionFacet.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.8.26;

import { IERC20, SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import { IResolution } from "../interfaces/IResolution.sol";

import { Types } from "../shared/Types.sol";

import { LibUtils } from "../libraries/LibUtils.sol";

import { LibDiamond } from "../libraries/LibDiamond.sol";

import { Accounted } from "./base/Accounted.sol";

import { IRainPool } from "../../interfaces/IRainPool.sol";
import { IQuestion } from "../../interfaces/IQuestion.sol";

import { _revert } from "../../utils/Globals.sol";

/**
 * @title ResolutionFacet
 * @author Rain Team
 * @notice Handles closing individual options and choosing winners per option.
 * @dev Each option is treated as an independent binary market with its own
 *      resolution lifecycle: close → chooseWinner → (dispute window) → claim.
 */
contract ResolutionFacet is IResolution, Accounted {
    using SafeERC20 for IERC20;

    /**
     * @inheritdoc IResolution
     */
    function closePool(uint256 option) external accounted {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        _validateClosePool(ds, option);

        if (!ds.resolverIsAI) {
            _revert(IRainPool.InvalidCall.selector);
        }

        ds.optionResolutionProposer[option] = msg.sender;

        if (msg.sender != ds.poolOwner && msg.sender != LibDiamond.liveResolver(ds)) {
            _calculateAndEscrowBond(option);
        }

        ds.optionFinalized[option] = true;

        if (block.timestamp <= ds.endTime) {
            ds.optionPhaseBActivationTime[option] = block.timestamp + ds.PHASE_B_DELAY;
        } else {
            ds.optionPhaseBActivationTime[option] = block.timestamp;
        }
        ds.optionEndTimeCache[option] = ds.optionEndTime[option];
        ds.optionEndTime[option] = block.timestamp;

        emit IRainPool.ClosePool(option, 0);
        emit IRainPool.ResolutionProposed({
            option: option,
            optionSide: 0, // Side is zero in case AI
            resolutionProposer: ds.optionResolutionProposer[option],
            resolverBond: ds.optionResolverBond[option],
            proposedWinner: ds.optionProposedWinner[option]
        });
    }

    /**
     * @inheritdoc IResolution
     */
    function closePool(uint256 option, uint8 proposedWinner) external accounted {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        _validateClosePool(ds, option);

        if (ds.resolverIsAI) {
            _revert(IRainPool.InvalidCall.selector);
        }

        _validateOptionSide(proposedWinner);

        ds.optionResolutionProposer[option] = msg.sender;

        if (msg.sender != ds.poolOwner && msg.sender != LibDiamond.liveResolver(ds)) {
            _calculateAndEscrowBond(option);
        }

        _calculateOptionFees(option);

        ds.optionFinalized[option] = true;

        if (block.timestamp <= ds.endTime) {
            ds.optionPhaseBActivationTime[option] = block.timestamp + ds.PHASE_B_DELAY;
        } else {
            ds.optionPhaseBActivationTime[option] = block.timestamp;
        }
        ds.optionEndTimeCache[option] = ds.optionEndTime[option];
        ds.optionEndTime[option] = block.timestamp;
        ds.optionWinner[option] = proposedWinner;
        ds.optionProposedWinner[option] = proposedWinner;
        ds.optionResolved[option] = true;

        emit IRainPool.ClosePool(option, proposedWinner);
        emit IRainPool.ChooseWinner({
            option: option,
            optionSide: proposedWinner,
            platformShare: ds.optionPlatformShare[option],
            winningShare: ds.optionWinningPoolShare[option]
        });
        emit IRainPool.ResolutionProposed({
            option: option,
            optionSide: proposedWinner,
            resolutionProposer: ds.optionResolutionProposer[option],
            resolverBond: ds.optionResolverBond[option],
            proposedWinner: ds.optionProposedWinner[option]
        });
    }

    /**
     * @inheritdoc IResolution
     */
    function chooseWinner(uint256 option, uint8 optionSide) external {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (option < 1 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }
        if (msg.sender != LibDiamond.currentResolver(ds, option)) {
            _revert(IRainPool.OnlyResolver.selector);
        }
        if (ds.optionResolved[option]) {
            _revert(IRainPool.WinnerAlreadyFinalized.selector);
        }
        if (!ds.optionFinalized[option]) {
            _revert(IRainPool.PoolOpen.selector);
        }
        if (!ds.resolverIsAI && ds.optionState[option] == Types.PoolState.NotDisputed) {
            _revert(IRainPool.InvalidCall.selector);
        }

        _validateOptionSide(optionSide);
        _calculateOptionFees(option);

        ds.optionWinner[option] = optionSide;
        ds.optionResolved[option] = true;
        ds.optionEndTime[option] = block.timestamp;

        if (ds.optionState[option] == Types.PoolState.NotDisputed) {
            emit IRainPool.ChooseWinner({
                option: option,
                optionSide: optionSide,
                platformShare: ds.optionPlatformShare[option] + ds.optionOrderBookShare[option],
                winningShare: ds.optionWinningPoolShare[option]
            });
        } else if (ds.optionState[option] == Types.PoolState.Disputed) {
            emit IRainPool.ChooseWinnerDispute({
                option: option,
                optionSide: optionSide,
                platformShare: ds.optionPlatformShare[option] + ds.optionOrderBookShare[option],
                winningShare: ds.optionWinningPoolShare[option]
            });
        }
    }

    /**
     * @inheritdoc IResolution
     * @dev Bond accounting: the resolver bond was escrowed by the proposer when they called
     *      `closePool`. Because `tooEarly` represents a finding that the close was
     *      premature/invalid, the bond is FORFEITED — never returned to the proposer. It is
     *      paid to the disputer when one challenged this close (they were right), and otherwise
     *      to the platform, since with no challenger there is no eligible recipient.
     *      A correct, undisputed close instead refunds the proposer at first claim via
     *      `_refundResolverBond` in `ClaimFacet`.
     */
    function tooEarly(uint256 option) external accounted {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (option < 1 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }
        if (msg.sender != LibDiamond.currentResolver(ds, option)) {
            _revert(IRainPool.OnlyResolver.selector);
        }
        if (!ds.optionFinalized[option]) {
            _revert(IRainPool.PoolOpen.selector);
        }

        if (ds.optionFirstClaim[option]) {
            _revert(IRainPool.AlreadyClaimed.selector);
        }

        if (ds.optionState[option] == Types.PoolState.Appealed) {
            _revert(IRainPool.InvalidPoolState.selector);
        }

        if (block.timestamp >= ds.endTime && ds.optionState[option] != Types.PoolState.Disputed) {
            _revert(IRainPool.InvalidCall.selector);
        }

        uint256 bond = ds.optionResolverBond[option];
        bool wasDisputed = ds.optionState[option] == Types.PoolState.Disputed;

        if (bond > 0 && !wasDisputed) {
            IERC20(ds.baseToken).safeTransfer(ds.platformAddress, bond);
            emit IRainPool.PlatformClaim({ wallet: ds.platformAddress, amount: bond, option: option });
        }

        emit IRainPool.TooEarly({
            option: option,
            resolutionProposer: ds.optionResolutionProposer[option],
            resolverBond: bond,
            proposedWinner: ds.optionProposedWinner[option]
        });

        ds.optionResolutionProposer[option] = address(0);
        ds.optionResolverBond[option] = 0;
        ds.optionFinalized[option] = false;
        ds.optionResolved[option] = false;
        ds.optionWinner[option] = 0;
        ds.optionProposedWinner[option] = 0;
        ds.optionPhaseBActivationTime[option] = 0;
        ds.optionEndTime[option] = ds.optionEndTimeCache[option];
        ds.optionEndTimeCache[option] = 0;

        if (ds.optionState[option] == Types.PoolState.Disputed) {
            ds.optionResolver[option] = LibDiamond.baseResolver(ds);
            emit IRainPool.ResolverSet({ resolver: ds.optionResolver[option], option: option });

            address disputer = ds.optionDispute[option].disputer;
            uint256 disputeFee = ds.optionDispute[option].disputeFee;

            uint256 resolverShare = ds.optionResolverShare[option];
            ds.optionResolverShare[option] = 0;
            uint256 shareToDisputer = resolverShare / 2;
            uint256 shareToResolver = resolverShare - shareToDisputer;

            uint256 bondToDisputer = bond / 2;
            uint256 bondToPlatform = bond - bondToDisputer;

            uint256 disputerReward = bondToDisputer + shareToDisputer;
            IERC20(ds.baseToken).safeTransfer(disputer, disputeFee + disputerReward);
            emit IRainPool.DisputeFeeRefunded({
                option: option,
                disputer: disputer,
                disputeFee: disputeFee,
                disputedWinner: uint8(ds.optionDispute[option].disputedWinner)
            });
            if (disputerReward > 0) {
                emit IRainPool.ResolverClaim({ wallet: disputer, option: option, amount: disputerReward });
            }

            uint256 resolverReward = shareToResolver;
            if (resolverReward > 0) {
                IERC20(ds.baseToken).safeTransfer(msg.sender, resolverReward);
                emit IRainPool.ResolverClaim({ wallet: msg.sender, option: option, amount: resolverReward });
            }

            if (bondToPlatform > 0) {
                IERC20(ds.baseToken).safeTransfer(ds.platformAddress, bondToPlatform);
                emit IRainPool.PlatformClaim({ wallet: ds.platformAddress, amount: bondToPlatform, option: option });
            }

            delete ds.optionDispute[option];
            ds.optionState[option] = Types.PoolState.NotDisputed;
            ds.isOptionDisputed[option] = false;
        }
    }

    /**
     * @inheritdoc IResolution
     * @dev Appeal "too early" resolution. When an appealed option's oracle resolves to
     *      winner == 3, the option was resolved prematurely: only the closer (A) was wrong.
     *      The disputer (B) and the appealer (C) both correctly rejected the substantive
     *      answers, so both are vindicated.
     */
    function resolveAppealTooEarly(uint256 option) external accounted {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (option < 1 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }
        if (ds.optionState[option] != Types.PoolState.Appealed) {
            _revert(IRainPool.InvalidPoolState.selector);
        }
        if (!ds.optionFinalized[option]) {
            _revert(IRainPool.PoolOpen.selector);
        }
        if (ds.optionFirstClaim[option]) {
            _revert(IRainPool.AlreadyClaimed.selector);
        }

        try IQuestion(ds.optionResolver[option]).calculateWinnerReadOnly() returns (uint256 oracleWinner, uint256) {
            if (oracleWinner != 3) {
                _revert(IRainPool.OracleNotFinalized.selector);
            }
        } catch {
            _revert(IRainPool.OracleNotFinalized.selector);
        }

        // Snapshot everything consumed below before any zeroing / struct deletes.
        address proposer = ds.optionResolutionProposer[option];
        address disputer = ds.optionDispute[option].disputer;
        address appealer = ds.optionAppeal[option].disputer;
        uint256 bond = ds.optionResolverBond[option];
        uint256 firstDisputeFee = ds.optionDispute[option].disputeFee;
        uint256 appealFee = ds.optionAppeal[option].disputeFee;
        address originalResolver = LibDiamond.baseResolver(ds);
        uint8 proposedWinner = ds.optionProposedWinner[option];

        uint256 resolverShare = ds.optionResolverShare[option];
        ds.optionResolverShare[option] = 0;
        uint256 shareToDisputer = resolverShare / 2;
        uint256 shareToAppealer = resolverShare - shareToDisputer;

        uint256 bondQuarter = bond / 4;

        emit IRainPool.DisputeFeeRefunded({
            option: option,
            disputer: disputer,
            disputeFee: firstDisputeFee,
            disputedWinner: uint8(ds.optionDispute[option].disputedWinner)
        });
        emit IRainPool.AppealFeeRefunded({
            option: option,
            appealer: appealer,
            appealFee: appealFee,
            appealedWinner: ds.optionAppeal[option].disputedWinner
        });

        emit IRainPool.TooEarly({
            option: option,
            resolutionProposer: proposer,
            resolverBond: bond,
            proposedWinner: proposedWinner
        });

        ds.optionResolutionProposer[option] = address(0);
        ds.optionResolverBond[option] = 0;
        ds.optionFinalized[option] = false;
        ds.optionResolved[option] = false;
        ds.optionWinner[option] = 0;
        ds.optionProposedWinner[option] = 0;
        ds.optionPhaseBActivationTime[option] = 0;
        ds.optionEndTime[option] = ds.optionEndTimeCache[option];
        ds.optionEndTimeCache[option] = 0;

        ds.optionResolver[option] = originalResolver;
        ds.optionState[option] = Types.PoolState.NotDisputed;
        ds.isOptionDisputed[option] = false;
        ds.isOptionAppealed[option] = false;
        delete ds.optionDispute[option];
        delete ds.optionAppeal[option];

        IERC20(ds.baseToken).safeTransfer(disputer, firstDisputeFee + bondQuarter + shareToDisputer);
        IERC20(ds.baseToken).safeTransfer(appealer, appealFee + bondQuarter + shareToAppealer);

        uint256 platformClaim = bond - (bondQuarter * 2);
        if (platformClaim > 0) {
            IERC20(ds.baseToken).safeTransfer(ds.platformAddress, platformClaim);
            emit IRainPool.PlatformClaim({ wallet: ds.platformAddress, amount: platformClaim, option: option });
        }

        emit IRainPool.ResolverSet({ resolver: originalResolver, option: option });
    }

    /**
     * @dev Shared validation for both closePool overloads.
     *
     *      Caller gate: the pool owner (the market creator) may close at any point in the
     *      market's life. Anyone else must hold a position in THIS option — options are
     *      independent binary markets, so a stake in option 1 confers no right to close
     *      option 2 — and must additionally wait out CLOSE_GRACE_PERIOD past the market's
     *      end time. A caller with no stake in the option is rejected outright, at any time.
     *
     */
    function _validateClosePool(LibDiamond.DiamondStorage storage ds, uint256 option) internal view {
        if (option < 1 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }
        if (block.timestamp <= ds.startTime) {
            _revert(IRainPool.SaleStillLive.selector);
        }
        if (ds.optionFinalized[option]) {
            _revert(IRainPool.PoolClosed.selector);
        }

        if (msg.sender == ds.poolOwner) {
            return;
        }

        if (!LibDiamond.isOptionParticipant(option, msg.sender)) {
            _revert(IRainPool.InvalidCaller.selector);
        }

        if (block.timestamp < ds.endTime + ds.CLOSE_GRACE_PERIOD) {
            _revert(IRainPool.SaleStillLive.selector);
        }
    }

    /**
     * @dev Validates that optionSide is 1 or 2. Reverts InvalidSide on miss,
     * matching the error selector used by enterOption / placeBuyOrder /
     * placeSellOrder for the same condition.
     */
    function _validateOptionSide(uint8 optionSide) internal pure {
        if (optionSide != 1 && optionSide != 2) {
            _revert(IRainPool.InvalidSide.selector);
        }
    }

    /**
     * @notice Calculates and escrows the resolver bond for a specific option.
     * @dev Bond is derived from the option's total funds and clamped between
     *      minimum and maximum resolution fees.
     * @param option The option ID to calculate the bond for.
     */
    function _calculateAndEscrowBond(uint256 option) internal {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        ds.optionResolverBond[option] = (ds.optionTotalFunds[option] * 1) / 1000;

        if (ds.baseToken != ds.usdt) {
            uint256 bondInUSDT = LibUtils.getQuoteOut(ds.baseToken, ds.optionResolverBond[option], ds.tokenData);

            if (bondInUSDT > ds.RESOLUTION_FEE_MAX) {
                ds.optionResolverBond[option] = LibUtils.getQuoteIn(ds.RESOLUTION_FEE_MAX, ds.tokenData);
            } else if (bondInUSDT < ds.RESOLUTION_FEE_MIN) {
                ds.optionResolverBond[option] = LibUtils.getQuoteIn(ds.RESOLUTION_FEE_MIN, ds.tokenData);
            }
        } else {
            if (ds.optionResolverBond[option] > ds.RESOLUTION_FEE_MAX) {
                ds.optionResolverBond[option] = ds.RESOLUTION_FEE_MAX;
            } else if (ds.optionResolverBond[option] < ds.RESOLUTION_FEE_MIN) {
                ds.optionResolverBond[option] = ds.RESOLUTION_FEE_MIN;
            }
        }

        IERC20(ds.baseToken).safeTransferFrom(msg.sender, address(this), ds.optionResolverBond[option]);
    }

    /**
     * @notice Calculates fee shares for a specific option based on its total funds.
     * @param option The option ID to calculate fees for.
     */
    function _calculateOptionFees(uint256 option) private {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        // Protocol fees (platform / creator / resolver / closing) are collected
        // per-trade from the taker into their accumulators as trading happens
        // (LibDiamond.collectTradeFee), so the pot holds only winner-backing
        // collateral. The entire pot is the winning pool — nothing is carved out at
        // settlement, and nothing extra is deducted from the claimer at claim time.
        ds.optionWinningPoolShare[option] = ds.optionTotalFunds[option];
    }
}

