// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { IERC20, SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

import { IDispute } from "../interfaces/IDispute.sol";

import { Types } from "../shared/Types.sol";

import { _revert } from "../../utils/Globals.sol";

import { LibDiamond } from "../libraries/LibDiamond.sol";

import { Accounted } from "./base/Accounted.sol";

import { LibUtils } from "../libraries/LibUtils.sol";

import { IRainPool } from "../../interfaces/IRainPool.sol";
import { IRainDeployer } from "../../interfaces/IRainDeployer.sol";

import { IPoolManager } from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";

import { SwapParams } from "@uniswap/v4-core/src/types/PoolOperation.sol";

import { PoolKey } from "@uniswap/v4-core/src/types/PoolKey.sol";

import { CurrencyLibrary, Currency } from "@uniswap/v4-core/src/types/Currency.sol";

import { BalanceDelta, BalanceDeltaLibrary } from "@uniswap/v4-core/src/types/BalanceDelta.sol";

import { MIN_SQRT_PRICE, MAX_SQRT_PRICE, WETH, POOL_MANAGER } from "../../shared/Constants.sol";

import { IWETH9 } from "@uniswap/v4-periphery/src/interfaces/external/IWETH9.sol";

import { SafeCast } from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import { PathKey, PathKeyLibrary } from "../libraries/PathKey.sol";

/**
 * @title DisputeFacet
 * @author Rain Team
 * @notice External interface for the rain pool `Dispute` facet.
 */
contract DisputeFacet is IDispute, Accounted {
    using SafeERC20 for IERC20;
    using BalanceDeltaLibrary for BalanceDelta;
    using SafeCast for int128;
    using SafeCast for uint128;
    using SafeCast for uint256;
    using CurrencyLibrary for address;
    using PathKeyLibrary for PathKey;

    /**
     * @inheritdoc IDispute
     */
    function openDispute(uint256 option) external accounted {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (option == 0 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }
        if (!ds.optionFinalized[option] || ds.optionWinner[option] == 0) {
            _revert(IRainPool.PoolNotClosed.selector);
        }
        if (ds.optionEndTime[option] + ds.DISPUTE_WINDOW < block.timestamp) {
            _revert(IRainPool.DisputeWindowEnded.selector);
        }

        if (ds.optionState[option] == Types.PoolState.NotDisputed) {
            ds.optionState[option] = Types.PoolState.Disputed;
            ds.isOptionDisputed[option] = true;
        } else if (ds.optionState[option] == Types.PoolState.Disputed && ds.optionWinner[option] != 0) {
            ds.optionState[option] = Types.PoolState.Appealed;
            ds.isOptionAppealed[option] = true;
        } else {
            _revert(IRainPool.DisputeAlreadyOpened.selector);
        }

        if (ds.optionState[option] == Types.PoolState.Disputed) {
            ds.optionDispute[option].disputeFee = _calculateDisputeFee(option, ds.DISPUTE_FEE_MAX, ds.DISPUTE_FEE_MIN);

            IERC20(ds.baseToken).safeTransferFrom(msg.sender, address(this), ds.optionDispute[option].disputeFee);

            ds.optionDispute[option].resolver = LibDiamond.baseResolver(ds);
            ds.optionResolver[option] = LibDiamond.liveDisputeResolver(ds);

            emit IRainPool.OpenDispute({
                caller: msg.sender,
                option: option,
                currentWinner: ds.optionWinner[option],
                disputeFee: ds.optionDispute[option].disputeFee
            });

            ds.optionDispute[option].disputedWinner = ds.optionWinner[option];
            ds.optionDispute[option].disputer = msg.sender;
            ds.optionWinner[option] = 0;
            ds.optionResolved[option] = false;
        } else if (ds.optionState[option] == Types.PoolState.Appealed) {
            ds.optionAppeal[option].disputeFee = _calculateDisputeFee(option, ds.DISPUTE_FEE_MAX, ds.APPEAL_FEE_MIN);
            uint256 oracleCost = _calculateAppealOracleCost();

            IERC20(ds.baseToken).safeTransferFrom(
                msg.sender,
                address(this),
                ds.optionAppeal[option].disputeFee + oracleCost
            );

            ds.optionAppeal[option].resolver = LibDiamond.liveDisputeResolver(ds);

            // The oracle is funded ONLY by the appealer's oracle-cost component, collected above
            // on top of their stake. optionResolverShare is never touched: it is reward money,
            // paid at settlement to whichever resolver's answer matches the final winner
            // (ClaimFacet). Funding the oracle from it — as this used to — coupled oracle budget
            // to trading volume and deadlocked appeals on options that never traded.
            uint256 resolverShare;

            if (ds.baseToken != ds.usdt) {
                resolverShare = LibUtils.swapTokensForUSDT(ds.baseToken, oracleCost, ds.tokenData);
            } else {
                resolverShare = oracleCost;
            }
            // ds.oracleFixedFee is retired and 0 on every pool from a live deployer, so in
            // practice the oracle is funded by resolverShare alone. It is no longer prepaid at
            // pool creation — a non-zero value would be pulled straight from collateral here.
            IERC20(ds.usdt).forceApprove(ds.FACTORY, resolverShare + ds.oracleFixedFee);

            ds.optionResolver[option] = IRainDeployer(ds.FACTORY).createOracle(
                _calculateNumberOfOracles(resolverShare),
                resolverShare,
                ds.oracleFixedFee,
                address(this),
                block.timestamp + ds.oracleEndTime,
                // 3-option answer space: 1 = YES, 2 = NO, 3 = "too early" (option was resolved
                // prematurely; handled by ResolutionFacet.resolveAppealTooEarly).
                3,
                ds.ipfsUri
            );

            emit IRainPool.CreateOracle({
                creatorContract: address(this),
                createdContract: ds.optionResolver[option],
                option: option
            });

            emit IRainPool.ResolverClaim(ds.optionResolver[option], option, resolverShare + ds.oracleFixedFee);

            emit IRainPool.OpenAppeal({
                caller: msg.sender,
                option: option,
                currentWinner: ds.optionWinner[option],
                appealFee: ds.optionAppeal[option].disputeFee
            });

            ds.optionAppeal[option].disputedWinner = ds.optionWinner[option];
            ds.optionAppeal[option].disputer = msg.sender;
            ds.optionWinner[option] = 0;
            ds.optionResolved[option] = false;
        }

        if (ds.optionState[option] != Types.PoolState.NotDisputed) {
            emit IRainPool.ResolverSet({ resolver: ds.optionResolver[option], option: option });
        }
    }

    /**
     * @notice Calculates the number of oracles based on the allocated amount.
     * @dev Ensures the number of oracles remains within a defined range.
     *      The base number of oracles is `3`, and additional
     *      oracles are determined by dividing the amount by 1000 times USDT's
     *      decimal factor (i.e. one extra oracle per ~1,000 USDT).
     *      The maximum number of oracles allowed is 100.
     * @param amount The amount allocated for oracle services.
     * @return The calculated number of oracles, constrained within the min-max range.
     */
    function _calculateNumberOfOracles(uint256 amount) internal view returns (uint256) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        uint256 baseOracles = 4; // Minimum number of oracles
        uint256 maxOracles = 100; // Maximum number of oracles

        // Calculate additional oracles based on the amount
        uint256 additionalOracles = (amount) / (1000 * (10 ** ERC20(ds.usdt).decimals()));

        // Calculate the total number of oracles
        uint256 totalOracles = baseOracles + additionalOracles;

        // Ensure the total oracles do not exceed the maximum
        if (totalOracles > maxOracles) {
            totalOracles = maxOracles;
        }

        return totalOracles;
    }

    /**
     * @notice Calculates the dispute fee required to open a dispute.
     *
     * @dev The fee is 0.1% of total pool funds, bounded by minimum and maximum
     * values defined in USDT. If the base token is not USDT, the fee is converted
     * to USDT for clamping and then converted back to the base token.
     *@param option disputed option
     * @param disputeFeeMaxUSDT Maximum dispute fee in USDT.
     * @param disputeFeeMinUSDT Minimum dispute fee in USDT.
     *
     * @return disputeFee Dispute fee denominated in the base token.
     */
    function _calculateDisputeFee(
        uint256 option,
        uint256 disputeFeeMaxUSDT,
        uint256 disputeFeeMinUSDT
    ) internal returns (uint256 disputeFee) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        disputeFee = (ds.optionTotalFunds[option] * 1) / 1_000; // 0.1% of total pool volume is the dispute fee collateral.

        if (ds.baseToken != ds.usdt) {
            uint256 disputeFeeInUSDT = LibUtils.getQuoteOut(ds.baseToken, disputeFee, ds.tokenData);

            if (disputeFeeInUSDT > disputeFeeMaxUSDT) {
                disputeFee = LibUtils.getQuoteIn(disputeFeeMaxUSDT, ds.tokenData);
            } else if (disputeFeeInUSDT < disputeFeeMinUSDT) {
                disputeFee = LibUtils.getQuoteIn(disputeFeeMinUSDT, ds.tokenData);
            }
        } else {
            if (disputeFee > disputeFeeMaxUSDT) {
                disputeFee = disputeFeeMaxUSDT;
            } else if (disputeFee < disputeFeeMinUSDT) {
                disputeFee = disputeFeeMinUSDT;
            }
        }
    }

    /**
     * @notice Calculates the appeal's oracle-cost component, denominated in the pool's base token.
     *
     * @dev `appealOracleCost` is configured in USDT. When the pool's base token is not USDT the
     * charge is quoted back into base token and padded by 1% (mirroring the oracle-fee pad in
     * RainDeployer.createPool), because the collected base token is swapped to USDT again a few
     * lines later to pay the oracle. Without the pad, ordinary swap slippage would leave the
     * oracle underfunded and revert `createOracle` — which would make appealing impossible rather
     * than merely expensive. Any surplus from the pad stays in the pool.
     *
     * Returns 0 when the cost is disabled, so the quoter is never called with a zero input.
     *
     * @return oracleCost The oracle cost denominated in the base token.
     */
    function _calculateAppealOracleCost() internal returns (uint256 oracleCost) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        oracleCost = ds.appealOracleCost;
        if (oracleCost == 0) {
            return 0;
        }

        if (ds.baseToken != ds.usdt) {
            oracleCost = (LibUtils.getQuoteIn(oracleCost, ds.tokenData) * 1010) / 1000;
        }
    }

    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != POOL_MANAGER) {
            _revert(IRainPool.NotPoolManager.selector);
        }

        IPoolManager poolManager = IPoolManager(POOL_MANAGER);

        (PathKey[] memory route, Currency currencyIn, uint256 amountIn, uint256 expectedAmountOut) = abi.decode(
            data,
            (PathKey[], Currency, uint256, uint256)
        );

        Currency current = currencyIn;
        uint256 currentAmount = amountIn;

        for (uint256 i = 0; i < route.length; i++) {
            PathKey memory hop = route[i];

            // derive poolKey + direction
            (PoolKey memory poolKey, bool zeroForOne) = PathKeyLibrary.getPoolAndSwapDirection(hop, current);

            BalanceDelta delta = poolManager.swap({
                key: poolKey,
                params: SwapParams({
                    zeroForOne: zeroForOne,
                    amountSpecified: -int256(currentAmount),
                    sqrtPriceLimitX96: zeroForOne ? MIN_SQRT_PRICE + 1 : MAX_SQRT_PRICE - 1
                }),
                hookData: hop.hookData
            });

            // settle input
            poolManager.sync(current);
            if (CurrencyLibrary.isAddressZero(current)) {
                poolManager.settle{ value: currentAmount }();
            } else {
                IERC20(Currency.unwrap(current)).safeTransfer(address(poolManager), currentAmount);
                poolManager.settle();
            }

            currentAmount = zeroForOne ? delta.amount1().toUint256() : delta.amount0().toUint256();

            current = hop.intermediateCurrency;

            poolManager.take({ currency: current, to: address(this), amount: currentAmount });
        }

        if (currentAmount < expectedAmountOut) {
            revert("Less Amount");
        }

        // wrap ETH if final output is native
        if (CurrencyLibrary.isAddressZero(current)) {
            IWETH9(WETH).deposit{ value: currentAmount }();
        }

        return abi.encode(currentAmount);
    }
}

