// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { Types } from "../shared/Types.sol";

import { IRainDeployer } from "../../interfaces/IRainDeployer.sol";

/**
 * @title IGetter
 * @author Rain Team
 * @notice Interface for the rain pool diamond facet.
 * @dev Defines the external functions for diamond storage getters within the Diamond architecture.
 */
interface IGetter {
    ////////////////////
    // Constants
    ////////////////////

    /**
     * @notice Returns the price magnification factor.
     */
    function PRICE_MAGNIFICATION() external view returns (uint256);

    /**
     * @notice Returns the fee magnification factor.
     */
    function FEE_MAGNIFICATION() external view returns (uint256);

    /**
     * @notice Returns the tick spacing used for price granularity.
     */
    function TICK_SPACING() external view returns (uint256);

    /**
     * @notice Returns the order execution fee.
     */
    function ORDER_EXECUTION_FEE() external view returns (uint256);

    /**
     * @notice Returns the per-fill maker rebate fee (credited to the resting maker).
     */
    function MAKER_REBATE_FEE() external view returns (uint256);

    /**
     * @notice Returns the dispute window duration in seconds.
     */
    function DISPUTE_WINDOW() external view returns (uint256);

    /**
     * @notice Returns how long a non-creator must wait past `endTime()` before they may close.
     */
    function CLOSE_GRACE_PERIOD() external view returns (uint256);

    /**
     * @notice Returns the maximum fee to open a dispute.
     */
    function DISPUTE_FEE_MAX() external view returns (uint256);

    /**
     * @notice Returns the minimum fee to open a dispute.
     */
    function DISPUTE_FEE_MIN() external view returns (uint256);

    /**
     * @notice Returns the minimum fee to open an appeal.
     */
    function APPEAL_FEE_MIN() external view returns (uint256);

    /**
     * @notice Returns the minimum fee to propose a resolution.
     */
    function RESOLUTION_FEE_MIN() external view returns (uint256);

    /**
     * @notice Returns the maximum fee to propose a resolution.
     */
    function RESOLUTION_FEE_MAX() external view returns (uint256);

    ////////////////////
    // Global Scalars
    ////////////////////

    /**
     * @notice Returns the pool start time.
     */
    function startTime() external view returns (uint256);

    /**
     * @notice Returns the pool end time.
     */
    function endTime() external view returns (uint256);

    /**
     * @notice Returns the number of options in the pool.
     */
    function numberOfOptions() external view returns (uint256);

    /**
     * @notice Returns the platform fee.
     */
    function platformFee() external view returns (uint256);

    /**
     * @notice Returns the liquidity fee.
     */
    function liquidityFee() external view returns (uint256);

    /**
     * @notice Returns the creator fee.
     */
    function creatorFee() external view returns (uint256);

    /**
     * @notice Returns the closing fee.
     */
    function closingFee() external view returns (uint256);

    /**
     * @notice Returns the result resolver fee.
     */
    function resultResolverFee() external view returns (uint256);

    /**
     * @notice Returns the oracle fixed fee.
     * @dev DEPRECATED — 0 on every pool created by a live deployer. Not collected at creation and
     *      not paid out at claim; retained for ABI stability. See RainDeployer.oracleFixedFee.
     */
    function oracleFixedFee() external view returns (uint256);

    /**
     * @notice Returns the flat USDT cost an appealer pays to fund the appeal oracle.
     * @dev Snapshotted from the deployer at pool creation. Non-refundable; never forfeited.
     */
    function appealOracleCost() external view returns (uint256);

    /**
     * @notice Returns the oracle end time.
     */
    function oracleEndTime() external view returns (uint256);

    /**
     * @notice Returns the total number of orders added.
     */
    function ordersAdded() external view returns (uint256);

    /**
     * @notice Returns the total number of orders removed.
     */
    function ordersRemoved() external view returns (uint256);

    /**
     * @notice Returns the base token decimals.
     */
    function baseTokenDecimals() external view returns (uint256);

    /**
     * @notice Returns the IPFS URI associated with the pool.
     */
    function ipfsUri() external view returns (string memory);

    ////////////////////
    // Global Addresses
    ////////////////////

    /**
     * @notice Returns the factory contract address.
     */
    function FACTORY() external view returns (address);

    /**
     * @notice Returns the base token address.
     */
    function baseToken() external view returns (address);

    /**
     * @notice Returns the rain token address.
     */
    function rainToken() external view returns (address);

    /**
     * @notice Returns the USDT token address.
     */
    function usdt() external view returns (address);

    /**
     * @notice Returns the pool owner address.
     */
    function poolOwner() external view returns (address);

    /**
     * @notice Returns the platform address.
     */
    function platformAddress() external view returns (address);

    /**
     * @notice Returns the resolver address.
     */
    function resolver() external view returns (address);

    /**
     * @notice Returns the dispute resolver (AI) address.
     */
    function disputeResolver() external view returns (address);

    /**
     * @notice Returns the referrer address.
     */
    function referrer() external view returns (address);

    ////////////////////
    // Global Booleans
    ////////////////////

    /**
     * @notice Returns whether the pool is public.
     */
    function isPublic() external view returns (bool);

    /**
     * @notice Returns whether the resolver is an AI.
     */
    function resolverIsAI() external view returns (bool);

    ////////////////////
    // Level 3 — Global (across all options and sides)
    ////////////////////

    /**
     * @notice Returns the total funds across all options and sides.
     */
    function totalMarketFunds() external view returns (uint256);

    /**
     * @notice Returns the total shares across all options and sides.
     */
    function totalMarketShares() external view returns (uint256);

    ////////////////////
    // V2 AMM — Per Option
    ////////////////////

    /**
     * @notice Returns the AMM Yes-side reserve for a specific option.
     * @param option The option index.
     */
    function ammYesReserve(uint256 option) external view returns (uint256);

    /**
     * @notice Returns the AMM No-side reserve for a specific option.
     * @param option The option index.
     */
    function ammNoReserve(uint256 option) external view returns (uint256);

    /**
     * @notice DEPRECATED — never written, always returns 0.
     * @param option The option index.
     */
    function resolverShareUSDT(uint256 option) external view returns (uint256);

    ////////////////////
    // V2 LP Shares — Per Option
    ////////////////////

    /**
     * @notice Returns the total LP shares issued for a specific option.
     * @param option The option index.
     */
    function totalOptionLPShares(uint256 option) external view returns (uint256);

    /**
     * @notice Returns the LP shares held by a user for a specific option.
     * @param option The option index.
     * @param user The address of the user.
     */
    function userOptionLPShares(uint256 option, address user) external view returns (uint256);

    ////////////////////
    // V2 Swap Fee Accumulator — Per Option
    ////////////////////

    /**
     * @notice Returns the accumulated fee per LP share (Q128) for a specific option.
     * @param option The option index.
     */
    function feePerLPShareX128(uint256 option) external view returns (uint256);

    /**
     * @notice Returns the fee debt per LP share (Q128) for a user in a specific option.
     * @param option The option index.
     * @param user The address of the user.
     */
    function userFeeDebtX128(uint256 option, address user) external view returns (uint256);

    ////////////////////
    // Level 2 — Per Option (Yes + No combined)
    ////////////////////

    /**
     * @notice Returns whether a specific option has been finalized.
     * @param option The option index.
     */
    function optionFinalized(uint256 option) external view returns (bool);

    /**
     * @notice Returns the total funds (Yes + No) for a specific option.
     * @param option The option index.
     */
    function optionTotalFunds(uint256 option) external view returns (uint256);

    /**
     * @notice Returns the total shares (Yes + No) for a specific option.
     * @param option The option index.
     */
    function optionTotalShares(uint256 option) external view returns (uint256);

    ////////////////////
    // Level 1 — Per Option Per Side
    ////////////////////

    /**
     * @notice Returns the funds for a specific option and side.
     * @param option The option index.
     * @param optionSide The side (1 = Yes, 2 = No).
     */
    function optionPerSideFunds(uint256 option, uint8 optionSide) external view returns (uint256);

    /**
     * @notice Returns the shares for a specific option and side.
     * @param option The option index.
     * @param optionSide The side (1 = Yes, 2 = No).
     */
    function optionPerSideShares(uint256 option, uint8 optionSide) external view returns (uint256);

    /**
     * @notice Returns the shares a user holds for a specific option and side.
     * @param option The option index.
     * @param optionSide The side (1 = Yes, 2 = No).
     * @param user The address of the user.
     */
    function userOptionPerSideShares(uint256 option, uint8 optionSide, address user) external view returns (uint256);

    /**
     * @notice Returns the shares a user has in escrow (sell orders) for a specific option and side.
     * @param option The option index.
     * @param optionSide The side (1 = Yes, 2 = No).
     * @param user The address of the user.
     */
    function userSharesPerSideInEscrow(uint256 option, uint8 optionSide, address user) external view returns (uint256);

    /**
     * @notice Returns the funds a user has in escrow (buy orders) for a specific option and side.
     * @param option The option index.
     * @param optionSide The side (1 = Yes, 2 = No).
     * @param user The address of the user.
     */
    function userFundsPerSideInEscrow(uint256 option, uint8 optionSide, address user) external view returns (uint256);

    ////////////////////
    // Order Book — Per Option Per Side
    ////////////////////

    /**
     * @notice Returns the sell order linked list metadata for a specific option, side, and price.
     * @param option The option index.
     * @param optionSide The side (1 = Yes, 2 = No).
     * @param price The price tick.
     */
    function sellOrders(
        uint256 option,
        uint8 optionSide,
        uint256 price
    ) external view returns (int256 headIndex, int256 tailIndex, int256 count, bool isInitialized);

    /**
     * @notice Returns the buy order linked list metadata for a specific option, side, and price.
     * @param option The option index.
     * @param optionSide The side (1 = Yes, 2 = No).
     * @param price The price tick.
     */
    function buyOrders(
        uint256 option,
        uint8 optionSide,
        uint256 price
    ) external view returns (int256 headIndex, int256 tailIndex, int256 count, bool isInitialized);

    /**
     * @notice Returns whether a specific order exists at a given option, side, price, and order ID.
     * @param option The option index.
     * @param optionSide The side (1 = Yes, 2 = No).
     * @param price The price tick.
     * @param orderID The order ID.
     */
    function orderBook(
        uint256 option,
        uint8 optionSide,
        uint256 price,
        uint256 orderID
    ) external view returns (bool exists, int256 index);

    /**
     * @notice Returns the smallest sell order price for a specific option and side.
     * @param option The option index.
     * @param optionSide The side (1 = Yes, 2 = No).
     */
    function firstSellOrderPrice(uint256 option, uint8 optionSide) external view returns (uint256);

    /**
     * @notice Returns the largest buy order price for a specific option and side.
     * @param option The option index.
     * @param optionSide The side (1 = Yes, 2 = No).
     */
    function firstBuyOrderPrice(uint256 option, uint8 optionSide) external view returns (uint256);

    ////////////////////
    // Resolution — Per Option
    ////////////////////

    /**
     * @notice Returns the winning side for a specific option.
     * @param option The option index.
     */
    function optionWinner(uint256 option) external view returns (uint8);

    /**
     * @notice Returns whether a specific option has been resolved.
     * @param option The option index.
     */
    function optionResolved(uint256 option) external view returns (bool);

    /**
     * @notice Returns whether a user has claimed rewards for a specific option.
     * @param option The option index.
     * @param user The address of the user.
     */
    function optionClaimed(uint256 option, address user) external view returns (bool);

    /**
     * @notice Returns the resolution proposer for a specific option.
     * @param option The option index.
     */
    function optionResolutionProposer(uint256 option) external view returns (address);

    /**
     * @notice Returns the resolver bond for a specific option.
     * @param option The option index.
     */
    function optionResolverBond(uint256 option) external view returns (uint256);

    /**
     * @notice Returns the proposed winning side for a specific option.
     * @param option The option index.
     */
    function optionProposedWinner(uint256 option) external view returns (uint8);

    /**
     * @notice Returns the end time for a specific option.
     * @param option The option index.
     */
    function optionEndTime(uint256 option) external view returns (uint256);

    /**
     * @notice Returns the cached end time for a specific option.
     * @param option The option index.
     */
    function optionEndTimeCache(uint256 option) external view returns (uint256);

    ////////////////////
    // Fee Shares — Per Option
    ////////////////////

    /**
     * @notice Returns the winning pool share for a specific option.
     * @param option The option index.
     */
    function optionWinningPoolShare(uint256 option) external view returns (uint256);

    /**
     * @notice Returns the platform share for a specific option.
     * @param option The option index.
     */
    function optionPlatformShare(uint256 option) external view returns (uint256);

    /**
     * @notice Returns the creator share for a specific option.
     * @param option The option index.
     */
    function optionCreatorShare(uint256 option) external view returns (uint256);

    /**
     * @notice Returns the resolver share for a specific option.
     * @param option The option index.
     */
    function optionResolverShare(uint256 option) external view returns (uint256);

    /**
     * @notice Returns the closing share for a specific option.
     * @param option The option index.
     */
    function optionClosingShare(uint256 option) external view returns (uint256);

    /**
     * @notice Returns the order book share for a specific option.
     * @param option The option index.
     */
    function optionOrderBookShare(uint256 option) external view returns (uint256);

    /**
     * @notice Returns whether the first claim for a specific option has been made.
     * @param option The option index.
     */
    function optionFirstClaim(uint256 option) external view returns (bool);

    ////////////////////
    // User Global
    ////////////////////

    /**
     * @notice Returns the number of active sell orders a user has on a given option.
     * @param option The 1-indexed option.
     * @param user The address of the user.
     */
    function userActiveSellOrdersPerOption(uint256 option, address user) external view returns (uint256);

    /**
     * @notice Returns the number of active buy orders a user has on a given option.
     * @param option The 1-indexed option.
     * @param user The address of the user.
     */
    function userActiveBuyOrdersPerOption(uint256 option, address user) external view returns (uint256);

    ////////////////////
    // Other — Per Option
    ////////////////////

    /**
     * @notice Returns the dispute details for a specific option.
     * @param option The option index.
     */
    function optionDispute(
        uint256 option
    ) external view returns (uint256 disputeFee, uint256 disputedWinner, address disputer, address _disputeResolver);

    /**
     * @notice Returns the appeal details for a specific option.
     * @param option The option index.
     */
    function optionAppeal(
        uint256 option
    ) external view returns (uint256 disputeFee, uint256 disputedWinner, address disputer, address appealResolver);

    /**
     * @notice Returns the dispute/appeal state for a specific option.
     * @param option The option index.
     */
    function optionState(uint256 option) external view returns (Types.PoolState);

    /**
     * @notice Returns whether a specific option has been appealed.
     * @param option The option index.
     */
    function isOptionAppealed(uint256 option) external view returns (bool);

    /**
     * @notice Returns the resolver address for a specific option.
     * @param option The option index.
     */
    function optionResolver(uint256 option) external view returns (address);

    /**
     * @notice Returns whether a specific option has been disputed.
     * @param option The option index.
     */
    function isOptionDisputed(uint256 option) external view returns (bool);

    ////////////////////
    // Token Data
    ////////////////////

    /**
     * @notice Returns the token routing configuration for this pool.
     * @return tokenPool The Uniswap pool version used for this token.
     * @return isAllowed Whether the token is allowed by the protocol.
     * @return routerAddress The router contract address.
     * @return routerHelper The router helper contract address.
     * @return pathUSDTToToken Swap path from USDT to the token.
     * @return pathTokenToUSDT Swap path from the token to USDT.
     * @return pathTokenToWETH Swap path from token to WETH.
     */
    function tokenData()
        external
        view
        returns (
            IRainDeployer.TokenPool tokenPool,
            bool isAllowed,
            address routerAddress,
            address routerHelper,
            bytes memory pathUSDTToToken,
            bytes memory pathTokenToUSDT,
            bytes memory pathTokenToWETH
        );

    /**
     * @notice Returns the trading model configured for this pool.
     */
    function tradingModel() external view returns (Types.TradingModel);
}

