        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (option == 0 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }

        // Claims only open after the option is closed via closePool. Until then the
        // option stays in Phase B (tradeable) regardless of how much time has passed —
        // a stale endTime must never auto-open claims on an unresolved option.
        if (!ds.optionFinalized[option]) {
            _revert(IRainPool.PoolNotClosed.selector);
        }
        if (block.timestamp <= ds.optionEndTime[option] + ds.DISPUTE_WINDOW) {
            _revert(IRainPool.DisputeWindowNotEnded.selector);
        }

        // Must be read before the settlement block below, which sets optionFirstClaim and
        // zeroes the share slots this depends on.
