        if (ds.optionWinner[option] == 0 || !ds.optionFinalized[option]) {
            _revert(IRainPool.PoolNotClosed.selector);
        }

        if (
            ds.userSharesPerSideInEscrow[option][1][msg.sender] > 0 ||
            ds.userSharesPerSideInEscrow[option][2][msg.sender] > 0
        ) {
            _revert(IRainPool.UserSellOrderExist.selector);
        }

        // Check buy order escrow for both sides of this option
        if (
            ds.userFundsPerSideInEscrow[option][1][msg.sender] > 0 ||
            ds.userFundsPerSideInEscrow[option][2][msg.sender] > 0
        ) {
            _revert(IRainPool.UserBuyOrderExist.selector);
        }

        // V2 CPMM: LP rewards come from per-trade swap fees (feePerLPShareX128 accumulator)
        uint256 liquidityReward;
        if (ds.userOptionLPShares[option][msg.sender] > 0 && ds.totalOptionLPShares[option] > 0) {
            uint256 accum = ds.feePerLPShareX128[option];
            uint256 debt = ds.userFeeDebtX128[option][msg.sender];
            if (accum > debt) {
                liquidityReward = ((accum - debt) * ds.userOptionLPShares[option][msg.sender]) >> 128;
            }
            // Mark fees as claimed by updating debt to current accumulator
            ds.userFeeDebtX128[option][msg.sender] = accum;
