        uint256 userWinningShares = ds.userOptionPerSideShares[option][winner][msg.sender];

        // LP's shares are inside the AMM — include their proportional winning-side reserves
        uint256 lpWinShares;
        if (ds.userOptionLPShares[option][msg.sender] > 0 && ds.totalOptionLPShares[option] > 0) {
            uint256 winnerReserve = winner == 1 ? ds.ammYesReserve[option] : ds.ammNoReserve[option];
            lpWinShares = Math.mulDiv(
                ds.userOptionLPShares[option][msg.sender],
                winnerReserve,
                ds.totalOptionLPShares[option]
            );
            userWinningShares += lpWinShares;
        }

        uint256 reward;
        uint256 winnerSideShares = ds.optionPerSideShares[option][winner];
        if (winnerSideShares > 0) {
            reward = (userWinningShares * ds.optionWinningPoolShare[option]) / winnerSideShares;
        }

        uint256 totalReward = liquidityReward + reward;

        // Role fees are pushed to their recipients by _firstClaimCheck rather than routed
        // through totalReward, so a recipient holding no winning shares would otherwise be
        // turned away from the very call that pays them.
        if (totalReward == 0 && !owedRole && msg.sender != ds.optionResolutionProposer[option]) {
            _revert(IRainPool.IneligibleToClaim.selector);
