    function _hasRoleReward(uint256 option, address user) private view returns (bool) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (ds.optionFirstClaim[option]) {
            return false;
        }

        // creator (50/50 referrer+owner, else 100% owner). _distributeOptionFees pays this ahead
        // of any dispute branching, so it lands on every path — disputed or not.
        if (ds.optionCreatorShare[option] > 0) {
            if (ds.referrer != address(0)) {
