     */
    function _firstClaimCheck(uint256 option) private {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (ds.optionState[option] == Types.PoolState.Disputed && ds.optionWinner[option] == 0) {
            _revert(IRainPool.WinnerNotDecided.selector);
        }

        uint256 platformAndOrderBook = _distributeOptionFees(option);

        if (ds.optionState[option] == Types.PoolState.Disputed && ds.optionWinner[option] != 0) {
            uint256 disputeFee = ds.optionDispute[option].disputeFee;
            uint256 resolverShare = ds.optionResolverShare[option];
            ds.optionDispute[option].disputeFee = 0;
            ds.optionResolverShare[option] = 0;

            bool disputerRight = ds.optionWinner[option] != ds.optionDispute[option].disputedWinner;

