            if (sharedEach > 0) {
                address disputeResolverRecipient = LibDiamond.liveDisputeResolver(ds);
                IERC20(ds.baseToken).safeTransfer(disputeResolverRecipient, sharedEach);
                emit IRainPool.ResolverClaim({ wallet: disputeResolverRecipient, option: option, amount: sharedEach });
