                IQuestion(ds.optionResolver[option]).timeExtended() == 7 &&
                !IQuestion(ds.optionResolver[option]).winnerFinalized()
            ) {
                try IQuestion(ds.optionResolver[option]).calculateWinnerReadOnly() returns (uint256 winner, uint256) {
                    if (winner < 1 || winner > 2) {
                        _revert(IRainPool.WinnerOutOfBound.selector);
                    }
                    ds.optionWinner[option] = uint8(winner);
                } catch {
