                    }

                    ds.optionWinner[option] = uint8(ds.optionAppeal[option].disputedWinner);
                    emit IRainPool.ChooseWinnerAppeal(
                        option,
                        ds.optionWinner[option],
                        platformAndOrderBook,
                        ds.optionWinningPoolShare[option]
                    );
