    function _settleAppealOutcome(uint256 option, uint256 appealFee) private {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        uint8 finalWinner = ds.optionWinner[option];
        address disputer = ds.optionDispute[option].disputer;
        address appealer = ds.optionAppeal[option].disputer;

        uint256 disputeFee = ds.optionDispute[option].disputeFee;
        ds.optionDispute[option].disputeFee = 0;

        bool disputerRight = finalWinner != uint8(ds.optionDispute[option].disputedWinner);
        bool appealerRight = finalWinner != uint8(ds.optionAppeal[option].disputedWinner);

        uint256 disputerRefund;
        uint256 disputerReward;
        uint256 appealerRefund;
        uint256 appealerReward;
        uint256 toPlatform;

        uint256 forfeitedStakes;
        uint256 sharedPot;
        uint256 bondShared;

        if (disputerRight) {
            disputerRefund = disputeFee;

            // Forfeited only when the closer's answer did not survive.
            uint256 bond = ds.optionResolverBond[option];
            if (bond > 0) {
                ds.optionResolverBond[option] = 0;
                bondShared = bond / 2;
                toPlatform += bond - bondShared;
            }
        } else {
            forfeitedStakes += disputeFee;
        }

        if (appealerRight) {
            appealerRefund = appealFee;
        } else {
            forfeitedStakes += appealFee;
        }

        uint256 resolverShare = ds.optionResolverShare[option];
        ds.optionResolverShare[option] = 0;
        sharedPot += resolverShare;

        address correctResolver;
        if (!appealerRight) {
            correctResolver = LibDiamond.liveDisputeResolver(ds);
        } else if (!disputerRight) {
            correctResolver = ds.resolverIsAI ? LibDiamond.liveResolver(ds) : ds.optionResolutionProposer[option];
        }

        uint256 correctChallengers = (disputerRight ? 1 : 0) + (appealerRight ? 1 : 0);

        uint256 stakeEach;
        if (correctChallengers > 0) {
            stakeEach = forfeitedStakes / correctChallengers;
            toPlatform += forfeitedStakes - (stakeEach * correctChallengers);
        } else {
            toPlatform += forfeitedStakes;
        }

        uint256 bondEach;
        if (correctChallengers > 0) {
            bondEach = bondShared / correctChallengers;
            toPlatform += bondShared - (bondEach * correctChallengers);
        } else {
            toPlatform += bondShared;
        }

        uint256 sharedParties = correctChallengers + (correctResolver != address(0) ? 1 : 0);
        uint256 sharedEach;
        if (sharedParties > 0) {
            sharedEach = sharedPot / sharedParties;
            toPlatform += sharedPot - (sharedEach * sharedParties);

            if (correctResolver != address(0) && sharedEach > 0) {
                IERC20(ds.baseToken).safeTransfer(correctResolver, sharedEach);
                emit IRainPool.ResolverClaim({ wallet: correctResolver, option: option, amount: sharedEach });
            }
        } else {
            toPlatform += sharedPot;
        }

        if (disputerRight) {
            disputerReward = stakeEach + sharedEach + bondEach;
        }
        if (appealerRight) {
            appealerReward = stakeEach + sharedEach + bondEach;
        }

        if (disputerRefund + disputerReward > 0) {
            IERC20(ds.baseToken).safeTransfer(disputer, disputerRefund + disputerReward);
            if (disputerRefund > 0) {
                emit IRainPool.DisputeFeeRefunded({
                    option: option,
                    disputer: disputer,
                    disputeFee: disputerRefund,
                    disputedWinner: uint8(ds.optionDispute[option].disputedWinner)
                });
            }
            if (disputerReward > 0) {
                emit IRainPool.ResolverClaim({ wallet: disputer, option: option, amount: disputerReward });
            }
        }

        if (appealerRefund + appealerReward > 0) {
            IERC20(ds.baseToken).safeTransfer(appealer, appealerRefund + appealerReward);
            if (appealerRefund > 0) {
                emit IRainPool.AppealFeeRefunded({
                    option: option,
                    appealer: appealer,
                    appealFee: appealerRefund,
                    appealedWinner: ds.optionAppeal[option].disputedWinner
                });
            }
            if (appealerReward > 0) {
                emit IRainPool.ResolverClaim({ wallet: appealer, option: option, amount: appealerReward });
            }
        }

        if (toPlatform > 0) {
            IERC20(ds.baseToken).safeTransfer(ds.platformAddress, toPlatform);
            emit IRainPool.PlatformClaim({ wallet: ds.platformAddress, amount: toPlatform, option: option });
        }
    }

    /**
     * @dev Handles refund or burn of the resolver bond after resolution.
     * Refunds the bond to the resolution proposer if the resolver is AI
     * or the proposed winner matches the finalized winner.
     * Otherwise, burns the bond when the proposal is incorrect.
     * No-op when the bond was already consumed by `_settleAppealOutcome`.
     */
    function _refundResolverBond(uint256 option, uint8 winnerSide) private {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        uint256 amount;

        if (ds.optionResolverBond[option] == 0) {
            return;
        }

        if (ds.resolverIsAI || ds.optionProposedWinner[option] == ds.optionWinner[option]) {
            amount = ds.optionResolverBond[option];
            ds.optionResolverBond[option] = 0;
            IERC20(ds.baseToken).safeTransfer(ds.optionResolutionProposer[option], amount);
            emit IRainPool.ResolutionProposerRefund({
                option: option,
                optionSide: winnerSide,
                resolutionProposer: ds.optionResolutionProposer[option],
                resolverBond: amount,
                proposedWinner: ds.optionProposedWinner[option]
            });
        } else if (
            ds.optionResolverBond[option] != 0 &&
            !ds.resolverIsAI &&
            (ds.isOptionDisputed[option] || ds.isOptionAppealed[option])
        ) {
            amount = ds.optionResolverBond[option];
            ds.optionResolverBond[option] = 0;
            IERC20(ds.baseToken).safeTransfer(ds.optionDispute[option].resolver, amount);
        }
    }

    /**
     * @dev Distributes the pre-computed per-option fees.
     * @return platformAndOrderBook Snapshot of the platform + order-book fee sum paid in
     * this call. Returned so `_firstClaimCheck` can emit it in `ChooseWinnerAppeal`
     * events after the storage slots have been zeroed.
     */
    function _distributeOptionFees(uint256 option) private returns (uint256 platformAndOrderBook) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        platformAndOrderBook = ds.optionPlatformShare[option] + ds.optionOrderBookShare[option];
        uint256 creatorAmount = ds.optionCreatorShare[option];

        ds.optionPlatformShare[option] = 0;
        ds.optionOrderBookShare[option] = 0;
        ds.optionCreatorShare[option] = 0;

        LibUtils.swapAndBurn(
            platformAndOrderBook,
            ds.baseToken,
            ds.rainToken,
            ds.platformAddress,
            ds.tokenData,
            option
        );
        LibUtils.referrerCreatorClaim(creatorAmount, ds.referrer, ds.poolOwner, ds.baseToken, option);
    }

    /**
     * @dev Transfers closing rewards in base tokens to the resolver and emits a `ClosingShareClaim` event.
     * @param resolver Address receiving the closing reward.
     * @param closingReward Amount of base tokens to transfer.
     */
    function _transferClosingRewards(address resolver, uint256 option, uint256 closingReward) private {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        IERC20(ds.baseToken).safeTransfer(resolver, closingReward);
        emit IRainPool.ClosingShareClaim(resolver, option, closingReward);
    }
}

