// SPDX-License-Identifier: MIT

pragma solidity 0.8.26;

import { IERC20, SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";

import { IClaim } from "../interfaces/IClaim.sol";

import { Types } from "../shared/Types.sol";

import { LibDiamond } from "../libraries/LibDiamond.sol";

import { Accounted } from "./base/Accounted.sol";
import { LibUtils } from "../libraries/LibUtils.sol";

import { _revert } from "../../utils/Globals.sol";

import { IQuestion } from "../../interfaces/IQuestion.sol";

import { IRainPool } from "../../interfaces/IRainPool.sol";

/**
 * @title ClaimFacet
 * @author Rain Team
 * @notice External interface for the rain pool `Claim` facet.
 */
contract ClaimFacet is IClaim, Accounted {
    using SafeERC20 for IERC20;

    /**
     * @inheritdoc IClaim
     */
    function claim(uint256 option) public accounted {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (option == 0 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }

        // Claims only open after the option is closed via closePool. Until then the
        // option stays in Phase B (tradeable) regardless of how much time has passed —
        // a stale endTime must never auto-open claims on an unresolved option.
        if (!ds.optionFinalized[option]) {
            _revert(IRainPool.PoolNotClosed.selector);
        }
        if (block.timestamp <= ds.optionEndTime[option] + ds.DISPUTE_WINDOW) {
            _revert(IRainPool.DisputeWindowNotEnded.selector);
        }

        // Must be read before the settlement block below, which sets optionFirstClaim and
        // zeroes the share slots this depends on.
        bool owedRole = _hasRoleReward(option, msg.sender);

        // Effects before interactions. `_firstClaimCheck` below makes external calls — most
        // notably `IQuestion.refund()` into the appeal oracle, a money-moving call into a
        // contract this pool does not control. Marking the caller claimed up front means a
        // reentrant `claim` cannot reach the payout path below.
        //
        // The settlement block itself is already covered by `optionFirstClaim`, but that is
        // incidental rather than by design, and it does not cover the caller's own payout.
        // This closes the one reentrancy vector here that does not depend on the base token
        // having a transfer hook.
        if (ds.optionClaimed[option][msg.sender]) {
            _revert(IRainPool.AlreadyClaimed.selector);
        }
        ds.optionClaimed[option][msg.sender] = true;

        if (!ds.optionFirstClaim[option]) {
            ds.optionFirstClaim[option] = true;
            _firstClaimCheck(option);
            _refundResolverBond(option, ds.optionWinner[option]);
            delete ds.optionDispute[option];
            delete ds.optionAppeal[option];
        }
        uint8 winner = ds.optionWinner[option];

        if (ds.optionWinner[option] == 0 || !ds.optionFinalized[option]) {
            _revert(IRainPool.PoolNotClosed.selector);
        }

        if (
            ds.userSharesPerSideInEscrow[option][1][msg.sender] > 0 ||
            ds.userSharesPerSideInEscrow[option][2][msg.sender] > 0
        ) {
            _revert(IRainPool.UserSellOrderExist.selector);
        }

        // Check buy order escrow for both sides of this option
        if (
            ds.userFundsPerSideInEscrow[option][1][msg.sender] > 0 ||
            ds.userFundsPerSideInEscrow[option][2][msg.sender] > 0
        ) {
            _revert(IRainPool.UserBuyOrderExist.selector);
        }

        // V2 CPMM: LP rewards come from per-trade swap fees (feePerLPShareX128 accumulator)
        uint256 liquidityReward;
        if (ds.userOptionLPShares[option][msg.sender] > 0 && ds.totalOptionLPShares[option] > 0) {
            uint256 accum = ds.feePerLPShareX128[option];
            uint256 debt = ds.userFeeDebtX128[option][msg.sender];
            if (accum > debt) {
                liquidityReward = ((accum - debt) * ds.userOptionLPShares[option][msg.sender]) >> 128;
            }
            // Mark fees as claimed by updating debt to current accumulator
            ds.userFeeDebtX128[option][msg.sender] = accum;
        }

        // User's winning shares = direct shares + proportional AMM reserves on winning side
        uint256 userWinningShares = ds.userOptionPerSideShares[option][winner][msg.sender];

        // LP's shares are inside the AMM — include their proportional winning-side reserves
        uint256 lpWinShares;
        if (ds.userOptionLPShares[option][msg.sender] > 0 && ds.totalOptionLPShares[option] > 0) {
            uint256 winnerReserve = winner == 1 ? ds.ammYesReserve[option] : ds.ammNoReserve[option];
            lpWinShares = Math.mulDiv(
                ds.userOptionLPShares[option][msg.sender],
                winnerReserve,
                ds.totalOptionLPShares[option]
            );
            userWinningShares += lpWinShares;
        }

        uint256 reward;
        uint256 winnerSideShares = ds.optionPerSideShares[option][winner];
        if (winnerSideShares > 0) {
            reward = (userWinningShares * ds.optionWinningPoolShare[option]) / winnerSideShares;
        }

        uint256 totalReward = liquidityReward + reward;

        // Role fees are pushed to their recipients by _firstClaimCheck rather than routed
        // through totalReward, so a recipient holding no winning shares would otherwise be
        // turned away from the very call that pays them.
        if (totalReward == 0 && !owedRole && msg.sender != ds.optionResolutionProposer[option]) {
            _revert(IRainPool.IneligibleToClaim.selector);
        }

        IERC20(ds.baseToken).safeTransfer(msg.sender, totalReward);

        emit IRainPool.Claim(msg.sender, option, winner, totalReward);
    }

    /**
     * @dev Whether `user` is owed a role fee that the upcoming `_firstClaimCheck` will pay out,
     * and so may call `claim` without holding winning shares. Mirrors the role-reward block of
     * `InfoFacet.getClaimableAmount` — the two must agree, or the UI reports a balance that
     * `claim` then refuses to pay. Must be called before the settlement block, which flips
     * optionFirstClaim.
     */
    function _hasRoleReward(uint256 option, address user) private view returns (bool) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (ds.optionFirstClaim[option]) {
            return false;
        }

        // creator (50/50 referrer+owner, else 100% owner). _distributeOptionFees pays this ahead
        // of any dispute branching, so it lands on every path — disputed or not.
        if (ds.optionCreatorShare[option] > 0) {
            if (ds.referrer != address(0)) {
                if (user == ds.referrer || user == ds.poolOwner) {
                    return true;
                }
            } else if (user == ds.poolOwner) {
                return true;
            }
        }

        if (ds.isOptionDisputed[option] || ds.isOptionAppealed[option]) {
            return false;
        }

        // resolver share -> AI resolver, or the proposer on non-AI pools
        address resolverRecipient = ds.resolverIsAI ? LibDiamond.liveResolver(ds) : ds.optionResolutionProposer[option];
        if (user == resolverRecipient && ds.optionResolverShare[option] > 0) {
            return true;
        }

        // closing share -> proposer
        if (user == ds.optionResolutionProposer[option] && ds.optionClosingShare[option] > 0) {
            return true;
        }

        // resolver bond refund -> proposer when AI or the proposal was correct
        if (
            user == ds.optionResolutionProposer[option] &&
            ds.optionResolverBond[option] > 0 &&
            (ds.resolverIsAI || ds.optionProposedWinner[option] == ds.optionWinner[option])
        ) {
            return true;
        }

        return false;
    }

    /**
     * @dev Performs required checks and state handling before the first claim per option.
     * Ensures the dispute window has ended or a winner is finalized.
     * Resolves disputes or appeals, distributes fees, refunds dispute costs,
     * and pays the resolver and oracle when applicable.
     */
    function _firstClaimCheck(uint256 option) private {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (ds.optionState[option] == Types.PoolState.Disputed && ds.optionWinner[option] == 0) {
            _revert(IRainPool.WinnerNotDecided.selector);
        }

        uint256 platformAndOrderBook = _distributeOptionFees(option);

        if (ds.optionState[option] == Types.PoolState.Disputed && ds.optionWinner[option] != 0) {
            uint256 disputeFee = ds.optionDispute[option].disputeFee;
            uint256 resolverShare = ds.optionResolverShare[option];
            ds.optionDispute[option].disputeFee = 0;
            ds.optionResolverShare[option] = 0;

            bool disputerRight = ds.optionWinner[option] != ds.optionDispute[option].disputedWinner;

            uint256 sharedPot = resolverShare;
            uint256 bondToDisputer;
            uint256 forfeitedStakes;
            uint256 toPlatform;
            uint256 disputerRefund;

            if (disputerRight) {
                disputerRefund = disputeFee;

                uint256 bond = ds.optionResolverBond[option];
                if (bond > 0) {
                    ds.optionResolverBond[option] = 0;
                    bondToDisputer = bond / 2;
                    toPlatform += bond - bondToDisputer;
                }
            } else {
                forfeitedStakes += disputeFee;
            }

            // Forfeited stakes go to correct challengers only; with none they fall to the platform.
            uint256 stakeEach;
            if (disputerRight) {
                stakeEach = forfeitedStakes;
            } else {
                toPlatform += forfeitedStakes;
            }

            // The shared pot is split with the dispute resolver, which is always correct here.
            uint256 sharedParties = disputerRight ? 2 : 1;
            uint256 sharedEach = sharedPot / sharedParties;
            toPlatform += sharedPot - (sharedEach * sharedParties);

            if (sharedEach > 0) {
                address disputeResolverRecipient = LibDiamond.liveDisputeResolver(ds);
                IERC20(ds.baseToken).safeTransfer(disputeResolverRecipient, sharedEach);
                emit IRainPool.ResolverClaim({ wallet: disputeResolverRecipient, option: option, amount: sharedEach });
            }

            if (disputerRight) {
                address disputer = ds.optionDispute[option].disputer;
                uint256 disputerReward = stakeEach + sharedEach + bondToDisputer;
                IERC20(ds.baseToken).safeTransfer(disputer, disputerRefund + disputerReward);
                emit IRainPool.DisputeFeeRefunded({
                    option: option,
                    disputer: disputer,
                    disputedWinner: uint8(ds.optionDispute[option].disputedWinner),
                    disputeFee: disputerRefund
                });
                if (disputerReward > 0) {
                    emit IRainPool.ResolverClaim({ wallet: disputer, option: option, amount: disputerReward });
                }
            }

            if (toPlatform > 0) {
                IERC20(ds.baseToken).safeTransfer(ds.platformAddress, toPlatform);
                emit IRainPool.PlatformClaim({ wallet: ds.platformAddress, amount: toPlatform, option: option });
            }
        }

        if (ds.optionState[option] == Types.PoolState.Appealed && ds.optionWinner[option] == 0) {
            uint256 appealFee = ds.optionAppeal[option].disputeFee;
            ds.optionAppeal[option].disputeFee = 0;

            if (IQuestion(ds.optionResolver[option]).winnerFinalized()) {
                uint256 oracleWinner = IQuestion(ds.optionResolver[option]).winnerOption();
                if (oracleWinner < 1 || oracleWinner > 2) {
                    _revert(IRainPool.WinnerOutOfBound.selector);
                }
                ds.optionWinner[option] = uint8(oracleWinner);
                emit IRainPool.ChooseWinnerAppeal(
                    option,
                    ds.optionWinner[option],
                    platformAndOrderBook,
                    ds.optionWinningPoolShare[option]
                );
            } else if (
                IQuestion(ds.optionResolver[option]).timeExtended() == 7 &&
                !IQuestion(ds.optionResolver[option]).winnerFinalized()
            ) {
                try IQuestion(ds.optionResolver[option]).calculateWinnerReadOnly() returns (uint256 winner, uint256) {
                    if (winner < 1 || winner > 2) {
                        _revert(IRainPool.WinnerOutOfBound.selector);
                    }
                    ds.optionWinner[option] = uint8(winner);
                } catch {
                    IQuestion.ExternalSourceInfo memory externalSourceInfo = IQuestion(ds.optionResolver[option])
                        .getExternalSource();
                    if (block.timestamp < externalSourceInfo.endTime) {
                        _revert(IRainPool.OracleNotFinalized.selector);
                    }

                    ds.optionWinner[option] = uint8(ds.optionAppeal[option].disputedWinner);
                    emit IRainPool.ChooseWinnerAppeal(
                        option,
                        ds.optionWinner[option],
                        platformAndOrderBook,
                        ds.optionWinningPoolShare[option]
                    );
                }

                uint256 usdtBefore = IERC20(ds.usdt).balanceOf(address(this));
                try IQuestion(ds.optionResolver[option]).refund() {
                    uint256 recovered = IERC20(ds.usdt).balanceOf(address(this)) - usdtBefore;

                    address appealer = ds.optionAppeal[option].disputer;
                    if (recovered > 0 && appealer != address(0)) {
                        IERC20(ds.usdt).safeTransfer(appealer, recovered);
                        emit IRainPool.AppealFeeRefunded({
                            option: option,
                            appealer: appealer,
                            appealFee: recovered,
                            appealedWinner: ds.optionAppeal[option].disputedWinner
                        });
                    }
                } catch {}
            } else {
                _revert(IRainPool.OracleNotFinalized.selector);
            }

            _settleAppealOutcome(option, appealFee);
        }

        if (ds.optionState[option] == Types.PoolState.NotDisputed) {
            uint256 resolverShareNotDisputed = ds.optionResolverShare[option];
            ds.optionResolverShare[option] = 0;

            address resolver;
            if (!ds.resolverIsAI) {
                resolver = ds.optionResolutionProposer[option];
            } else {
                resolver = LibDiamond.liveResolver(ds);
            }
            IERC20(ds.baseToken).safeTransfer(resolver, resolverShareNotDisputed);

            emit IRainPool.ResolverClaim(resolver, option, resolverShareNotDisputed);
        }

        uint256 closingShare = ds.optionClosingShare[option];
        ds.optionClosingShare[option] = 0;

        if (
            !ds.resolverIsAI &&
            (ds.isOptionDisputed[option] || ds.isOptionAppealed[option]) &&
            ds.optionWinner[option] != ds.optionProposedWinner[option]
        ) {
            IERC20(ds.baseToken).safeTransfer(ds.optionDispute[option].resolver, closingShare);
        } else {
            _transferClosingRewards(ds.optionResolutionProposer[option], option, closingShare);
        }
    }

    /**
     * @notice Settles the dispute stake, the appeal stake, the closer's bond and the resolver
     *         share once an appealed option has reached a final winner.
     */
    function _settleAppealOutcome(uint256 option, uint256 appealFee) private {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        uint8 finalWinner = ds.optionWinner[option];
        address disputer = ds.optionDispute[option].disputer;
        address appealer = ds.optionAppeal[option].disputer;

        uint256 disputeFee = ds.optionDispute[option].disputeFee;
        ds.optionDispute[option].disputeFee = 0;

        bool disputerRight = finalWinner != uint8(ds.optionDispute[option].disputedWinner);
        bool appealerRight = finalWinner != uint8(ds.optionAppeal[option].disputedWinner);

        uint256 disputerRefund;
        uint256 disputerReward;
        uint256 appealerRefund;
        uint256 appealerReward;
        uint256 toPlatform;

        uint256 forfeitedStakes;
        uint256 sharedPot;
        uint256 bondShared;

        if (disputerRight) {
            disputerRefund = disputeFee;

            // Forfeited only when the closer's answer did not survive.
            uint256 bond = ds.optionResolverBond[option];
            if (bond > 0) {
                ds.optionResolverBond[option] = 0;
                bondShared = bond / 2;
                toPlatform += bond - bondShared;
            }
        } else {
            forfeitedStakes += disputeFee;
        }

        if (appealerRight) {
            appealerRefund = appealFee;
        } else {
            forfeitedStakes += appealFee;
        }

        uint256 resolverShare = ds.optionResolverShare[option];
        ds.optionResolverShare[option] = 0;
        sharedPot += resolverShare;

        address correctResolver;
        if (!appealerRight) {
            correctResolver = LibDiamond.liveDisputeResolver(ds);
        } else if (!disputerRight) {
            correctResolver = ds.resolverIsAI ? LibDiamond.liveResolver(ds) : ds.optionResolutionProposer[option];
        }

        uint256 correctChallengers = (disputerRight ? 1 : 0) + (appealerRight ? 1 : 0);

        uint256 stakeEach;
        if (correctChallengers > 0) {
            stakeEach = forfeitedStakes / correctChallengers;
            toPlatform += forfeitedStakes - (stakeEach * correctChallengers);
        } else {
            toPlatform += forfeitedStakes;
        }

        uint256 bondEach;
        if (correctChallengers > 0) {
            bondEach = bondShared / correctChallengers;
            toPlatform += bondShared - (bondEach * correctChallengers);
        } else {
            toPlatform += bondShared;
        }

        uint256 sharedParties = correctChallengers + (correctResolver != address(0) ? 1 : 0);
        uint256 sharedEach;
        if (sharedParties > 0) {
            sharedEach = sharedPot / sharedParties;
            toPlatform += sharedPot - (sharedEach * sharedParties);

            if (correctResolver != address(0) && sharedEach > 0) {
                IERC20(ds.baseToken).safeTransfer(correctResolver, sharedEach);
                emit IRainPool.ResolverClaim({ wallet: correctResolver, option: option, amount: sharedEach });
            }
        } else {
            toPlatform += sharedPot;
        }

        if (disputerRight) {
            disputerReward = stakeEach + sharedEach + bondEach;
        }
        if (appealerRight) {
            appealerReward = stakeEach + sharedEach + bondEach;
        }

        if (disputerRefund + disputerReward > 0) {
            IERC20(ds.baseToken).safeTransfer(disputer, disputerRefund + disputerReward);
            if (disputerRefund > 0) {
                emit IRainPool.DisputeFeeRefunded({
                    option: option,
                    disputer: disputer,
                    disputeFee: disputerRefund,
                    disputedWinner: uint8(ds.optionDispute[option].disputedWinner)
                });
            }
            if (disputerReward > 0) {
                emit IRainPool.ResolverClaim({ wallet: disputer, option: option, amount: disputerReward });
            }
        }

        if (appealerRefund + appealerReward > 0) {
            IERC20(ds.baseToken).safeTransfer(appealer, appealerRefund + appealerReward);
            if (appealerRefund > 0) {
                emit IRainPool.AppealFeeRefunded({
                    option: option,
                    appealer: appealer,
                    appealFee: appealerRefund,
                    appealedWinner: ds.optionAppeal[option].disputedWinner
                });
            }
            if (appealerReward > 0) {
                emit IRainPool.ResolverClaim({ wallet: appealer, option: option, amount: appealerReward });
            }
        }

        if (toPlatform > 0) {
            IERC20(ds.baseToken).safeTransfer(ds.platformAddress, toPlatform);
            emit IRainPool.PlatformClaim({ wallet: ds.platformAddress, amount: toPlatform, option: option });
        }
    }

    /**
     * @dev Handles refund or burn of the resolver bond after resolution.
     * Refunds the bond to the resolution proposer if the resolver is AI
     * or the proposed winner matches the finalized winner.
     * Otherwise, burns the bond when the proposal is incorrect.
     * No-op when the bond was already consumed by `_settleAppealOutcome`.
     */
    function _refundResolverBond(uint256 option, uint8 winnerSide) private {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        uint256 amount;

        if (ds.optionResolverBond[option] == 0) {
            return;
        }

        if (ds.resolverIsAI || ds.optionProposedWinner[option] == ds.optionWinner[option]) {
            amount = ds.optionResolverBond[option];
            ds.optionResolverBond[option] = 0;
            IERC20(ds.baseToken).safeTransfer(ds.optionResolutionProposer[option], amount);
            emit IRainPool.ResolutionProposerRefund({
                option: option,
                optionSide: winnerSide,
                resolutionProposer: ds.optionResolutionProposer[option],
                resolverBond: amount,
                proposedWinner: ds.optionProposedWinner[option]
            });
        } else if (
            ds.optionResolverBond[option] != 0 &&
            !ds.resolverIsAI &&
            (ds.isOptionDisputed[option] || ds.isOptionAppealed[option])
        ) {
            amount = ds.optionResolverBond[option];
            ds.optionResolverBond[option] = 0;
            IERC20(ds.baseToken).safeTransfer(ds.optionDispute[option].resolver, amount);
        }
    }

    /**
     * @dev Distributes the pre-computed per-option fees.
     * @return platformAndOrderBook Snapshot of the platform + order-book fee sum paid in
     * this call. Returned so `_firstClaimCheck` can emit it in `ChooseWinnerAppeal`
     * events after the storage slots have been zeroed.
     */
    function _distributeOptionFees(uint256 option) private returns (uint256 platformAndOrderBook) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        platformAndOrderBook = ds.optionPlatformShare[option] + ds.optionOrderBookShare[option];
        uint256 creatorAmount = ds.optionCreatorShare[option];

        ds.optionPlatformShare[option] = 0;
        ds.optionOrderBookShare[option] = 0;
        ds.optionCreatorShare[option] = 0;

        LibUtils.swapAndBurn(
            platformAndOrderBook,
            ds.baseToken,
            ds.rainToken,
            ds.platformAddress,
            ds.tokenData,
            option
        );
        LibUtils.referrerCreatorClaim(creatorAmount, ds.referrer, ds.poolOwner, ds.baseToken, option);
    }

    /**
     * @dev Transfers closing rewards in base tokens to the resolver and emits a `ClosingShareClaim` event.
     * @param resolver Address receiving the closing reward.
     * @param closingReward Amount of base tokens to transfer.
     */
    function _transferClosingRewards(address resolver, uint256 option, uint256 closingReward) private {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        IERC20(ds.baseToken).safeTransfer(resolver, closingReward);
        emit IRainPool.ClosingShareClaim(resolver, option, closingReward);
    }
}

