// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IDiamondCut {
    enum FacetCutAction {
        Add,
        Replace,
        Remove
    }
    // Add=0, Replace=1, Remove=2

    struct FacetCut {
        address facetAddress;
        FacetCutAction action;
        bytes4[] functionSelectors;
    }

    event DiamondCut(FacetCut[] _diamondCut, address _init, bytes _calldata);
    /// @notice Add/replace/remove any number of functions and optionally execute
    ///         a function with delegatecall
    /// @param _diamondCut Contains the facet addresses and function selectors
    /// @param _init The address of the contract or facet to execute _calldata
    /// @param _calldata A function call, including function selector and arguments
    ///                  _calldata is executed with delegatecall on _init
    function diamondCut(FacetCut[] calldata _diamondCut, address _init, bytes calldata _calldata) external;
}

src/diamond/interfaces/ISplitMerge.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface ISplitMerge {
    /**
     * @notice Splits base token collateral into equal YES and NO shares for a specific option.
     * @dev Deposits `amount` of base token and credits the caller with `amount` YES shares
     *      and `amount` NO shares. Zero price impact — AMM reserves are unchanged.
     *      Preserves the solvency invariant: optionTotalFunds == optionPerSideShares[YES] == optionPerSideShares[NO].
     * @param option The option to split collateral into.
     * @param amount The amount of base token to split.
     */
    function split(uint256 option, uint256 amount) external;

    /**
     * @notice Merges equal YES and NO shares back into base token collateral.
     * @dev Burns `amount` YES shares and `amount` NO shares from the caller and returns
     *      `amount` base tokens. Zero price impact — AMM reserves are unchanged.
     *      Requires the caller to hold at least `amount` non-escrowed shares on both sides.
     * @param option The option to merge shares from.
     * @param amount The number of share pairs (YES + NO) to merge.
     */
    function merge(uint256 option, uint256 amount) external;
}

src/diamond/facets/CancelOrderFacet.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.8.26;

import { IERC20, SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import { LibDiamond } from "../libraries/LibDiamond.sol";

import { Accounted } from "./base/Accounted.sol";

import { ICancelOrder } from "../interfaces/ICancelOrder.sol";

import { _revert } from "../../utils/Globals.sol";

import { LinkedListLogic } from "../../libraries/LinkedList.sol";
import { LinkedListStorage } from "../../interfaces/LinkedListStorage.sol";

import { IRainPool } from "../../interfaces/IRainPool.sol";

/**
 * @title CancelOrderFacet
 * @author Rain Team
 * @notice External interface for the rain pool `CancelOrder` facet.
 */
contract CancelOrderFacet is ICancelOrder, Accounted {
    using SafeERC20 for IERC20;
    using LinkedListLogic for LinkedListStorage.LinkedList;

    /**
     * @inheritdoc ICancelOrder
     */
    function cancelSellOrders(
        uint256 option,
        uint8[] memory optionSide,
        uint256[] memory price,
        uint256[] memory orderID
    ) external {
        // No phase or mode gate: cancel must work whenever orders exist, including
        // post-claim-window so users can release escrow before claiming. The
        // per-order existence + maker check below is the authoritative guard.
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (
            price.length != orderID.length ||
            orderID.length != optionSide.length
        ) {
            _revert(IRainPool.ArrayLengthMismatch.selector);
        }

        if (option == 0 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }

        uint256 i = 0;
        for (; i < orderID.length; ) {
            if (optionSide[i] != 1 && optionSide[i] != 2) {
                _revert(IRainPool.InvalidSide.selector);
            }
            if (price[i] == 0 || price[i] > 0.99 ether || price[i] % ds.TICK_SPACING != 0) {
                _revert(IRainPool.InvalidPrice.selector);
            }

            _cancelSellOrder(option, optionSide[i], price[i], orderID[i], msg.sender);

            unchecked {
                ++i;
            }
        }
    }

    /**
     * @inheritdoc ICancelOrder
     */
    function cancelBuyOrders(
        uint256 option,
        uint8[] memory optionSide,
        uint256[] memory price,
        uint256[] memory orderID
    ) external accounted {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (
            price.length != orderID.length ||
            orderID.length != optionSide.length
        ) {
            _revert(IRainPool.ArrayLengthMismatch.selector);
        }

        if (option == 0 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }

        uint256 i = 0;
        for (; i < orderID.length; ) {
            if (optionSide[i] != 1 && optionSide[i] != 2) {
                _revert(IRainPool.InvalidSide.selector);
            }
            if (price[i] == 0 || price[i] > 0.99 ether || price[i] % ds.TICK_SPACING != 0) {
                _revert(IRainPool.InvalidPrice.selector);
            }

            _cancelBuyOrder(option, optionSide[i], price[i], orderID[i], msg.sender);

            unchecked {
                ++i;
            }
        }
    }

    /**
     * @notice Cancels a specific sell order in the order book.
     * @dev Reverts if the order ID is invalid or the caller is not the order's creator.
     *      Emits a {CancelSellOrder} event upon successful cancellation.
     * @param option The option index for which the order was placed.
     * @param optionSide The side of the option (1 or 2).
     * @param price The price at which the order was placed.
     * @param orderID The unique identifier of the order to cancel.
     * @param caller The address of the user calling the function.
     */
    function _cancelSellOrder(
        uint256 option,
        uint8 optionSide,
        uint256 price,
        uint256 orderID,
        address caller
    ) private {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (ds.orderBook[option][optionSide][price][orderID].exists == false) {
            _revert(IRainPool.OrderDoesNotExist.selector);
        }

        LinkedListStorage.LinkedList storage linkedList = ds.sellOrders[option][optionSide][price];

        if (!linkedList.isInitialized) {
            _revert(IRainPool.LinkedListNotInitalized.selector);
        }

        int256 nodeIndex = ds.orderBook[option][optionSide][price][orderID].index;
        uint256 orderAmount = LinkedListLogic.getAmount(linkedList, nodeIndex);
        address sellerAddress = LinkedListLogic.getMaker(linkedList, nodeIndex);

        if (caller != sellerAddress) {
            _revert(IRainPool.CallerNotOrderPlacer.selector);
        }

        linkedList.remove(nodeIndex);
        ds.orderBook[option][optionSide][price][orderID].exists = false;
        ds.orderBook[option][optionSide][price][orderID].index = 0;

        if (LinkedListLogic.isEmpty(linkedList)) {
            uint256 currentFirst = ds.firstSellOrderPrice[option][optionSide];
            if (currentFirst == price) {
                uint256 next = price + ds.TICK_SPACING;
                while (next <= 0.99 ether && LinkedListLogic.isEmpty(ds.sellOrders[option][optionSide][next])) {
                    unchecked {
                        next += ds.TICK_SPACING;
                    }
                }
                // Clamp to the top valid tick when the book is fully drained (next overshoots to
                // 1.0 ether), matching the F-2026-17696 sentinel used on the trade-walk path.
                ds.firstSellOrderPrice[option][optionSide] = next > 0.99 ether ? 0.99 ether : next;
            }
        }

        ds.userActiveSellOrdersPerOption[option][caller]--;
        ds.userSharesPerSideInEscrow[option][optionSide][caller] -= orderAmount;
        ++ds.ordersRemoved;

        emit IRainPool.CancelSellOrder({
            orderOption: option,
            orderOptionSide: optionSide,
            sharesAmount: orderAmount,
            orderPrice: price,
            orderID: orderID,
            orderCreator: sellerAddress
        });
    }

    /**
     * @notice Cancels a specific buy order in the order book.
     * @dev Reverts if the order ID is invalid or the caller is not the order's creator.
     *      Emits a {CancelBuyOrder} event upon successful cancellation.
     * @param option The option index for which the order was placed.
     * @param optionSide The side of the option (1 or 2).
     * @param price The price at which the order was placed.
     * @param orderID The unique identifier of the order to cancel.
     * @param caller The address of the user calling the function.
     */
    function _cancelBuyOrder(
        uint256 option,
        uint8 optionSide,
        uint256 price,
        uint256 orderID,
        address caller
    ) private {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (ds.orderBook[option][optionSide][price][orderID].exists == false) {
            _revert(IRainPool.OrderDoesNotExist.selector);
        }

        LinkedListStorage.LinkedList storage linkedList = ds.buyOrders[option][optionSide][price];

        if (!linkedList.isInitialized) {
            _revert(IRainPool.LinkedListNotInitalized.selector);
        }

        int256 nodeIndex = ds.orderBook[option][optionSide][price][orderID].index;
        uint256 orderAmount = LinkedListLogic.getAmount(linkedList, nodeIndex);
        address buyerAddress = LinkedListLogic.getMaker(linkedList, nodeIndex);

        if (caller != buyerAddress) {
            _revert(IRainPool.CallerNotOrderPlacer.selector);
        }

        linkedList.remove(nodeIndex);
        ds.orderBook[option][optionSide][price][orderID].exists = false;
        ds.orderBook[option][optionSide][price][orderID].index = 0;

        if (LinkedListLogic.isEmpty(linkedList)) {
            uint256 currentFirst = ds.firstBuyOrderPrice[option][optionSide];
            if (currentFirst == price) {
                uint256 next = price - ds.TICK_SPACING;
                while (next >= ds.TICK_SPACING && LinkedListLogic.isEmpty(ds.buyOrders[option][optionSide][next])) {
                    unchecked {
                        next -= ds.TICK_SPACING;
                    }
                }
                // Clamp to the bottom valid tick when the book is fully drained (next undershoots to
                // 0), matching the F-2026-17696 sentinel used on the trade-walk path.
                ds.firstBuyOrderPrice[option][optionSide] = next < ds.TICK_SPACING ? ds.TICK_SPACING : next;
            }
        }

        ds.userActiveBuyOrdersPerOption[option][caller]--;
        ds.userFundsPerSideInEscrow[option][optionSide][caller] -= orderAmount;
        ++ds.ordersRemoved;

        // Refund the escrowed funds back to buyer 

        IERC20(ds.baseToken).safeTransfer(caller, orderAmount);

        emit IRainPool.CancelBuyOrder({
            orderOption: option,
            orderOptionSide: optionSide,
            orderBaseAmount: orderAmount,
            orderPrice: price,
            orderID: orderID,
            orderCreator: buyerAddress
        });
    }
}

src/diamond/interfaces/ICancelOrder.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.8.26;

/**
 * @title ICancelOrder
 * @author Rain Team
 * @notice Interface for the rain pool `CancelOrder` facet.
 * @dev Defines the external functions for cancelling a sell/buy (limit) order within the
 * Diamond architecture.
 */
interface ICancelOrder {
    /* =====================================  FUNCTIONS ===================================== */

    /**
     * @notice Cancels multiple sell orders for a single option in the pool.
     * @dev Cancels orders based on the provided optionSide, price, and orderID arrays.
     *      All arrays must be of equal length and correspond to each other by index.
     * @param option The option ID associated with the orders to cancel.
     * @param optionSide Array of sides (1 or 2) for each order.
     * @param price Array of price values at which the orders were placed.
     * @param orderID Array of order IDs to be cancelled.
     */
    function cancelSellOrders(
        uint256 option,
        uint8[] memory optionSide,
        uint256[] memory price,
        uint256[] memory orderID
    ) external;

