// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import { IRainAccounting } from "../../interfaces/IRainAccounting.sol";
import { IRainDeployer } from "../../interfaces/IRainDeployer.sol";

import { LibDiamond } from "./LibDiamond.sol";

/**
 * @title LibAccounting
 * @notice Pool-side hook into {RainAccounting}, the protocol-wide token ledger.
 * @dev One {snapshot}/{settle} pair per entrypoint, measuring the net balance change. That covers
 *      however many transfers happen inside -- `ClaimFacet.claim` alone has fourteen, and the
 *      order-book fills sit in a nested loop -- and cannot drift against a path the hook did not
 *      know about.
 *
 *      Calls into the ledger are direct, so a ledger that reverts takes the entrypoint down with
 *      it. That is deliberate: a gate is planned inside `recordIncrease` and has to be able to
 *      block. Anything added to the ledger has to be judged on that basis.
 */
library LibAccounting {
    /// @dev Base-token balance before the body runs. Pair every call with {settle}.
    /// @return The pool's current base-token balance.
    function snapshot() internal view returns (uint256) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        return IERC20(ds.baseToken).balanceOf(address(this));
    }

    /// @dev Reports the entrypoint's net base-token movement.
    /// @param balanceBefore The value returned by the matching {snapshot} call.
    function settle(uint256 balanceBefore) internal {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        address ledger = _ledger(ds);

        if (ledger == address(0)) {
            return;
        }

        address token = ds.baseToken;
        uint256 balanceAfter = IERC20(token).balanceOf(address(this));

        if (balanceAfter > balanceBefore) {
            IRainAccounting(ledger).recordIncrease(token, balanceAfter - balanceBefore);
        } else if (balanceBefore > balanceAfter) {
            IRainAccounting(ledger).recordDecrease(token, balanceBefore - balanceAfter);
        }
    }

    /// @dev Resolved from the deployer, not pool storage, so pools cut later pick it up with no
    ///      per-pool config. Zero only before the first `setAccountingAddress` -- accounting cannot
    ///      be switched back off once on.
    ///
    ///      Makes the deployment ORDER load-bearing: the deployer must expose `accounting()` BEFORE
    ///      any pool is cut with these facets. Cut first and every wrapped entrypoint reverts,
    ///      which is a trading halt. See the upgrade script.
    function _ledger(LibDiamond.DiamondStorage storage ds) private view returns (address) {
        return IRainDeployer(ds.FACTORY).accounting();
    }
}

