// SPDX-License-Identifier: MIT

pragma solidity 0.8.26;

import { ICancelOrder } from "../diamond/interfaces/ICancelOrder.sol";

import { IClaim } from "../diamond/interfaces/IClaim.sol";

import { IDispute } from "../diamond/interfaces/IDispute.sol";

import { IGetter } from "../diamond/interfaces/IGetter.sol";

import { IInfo } from "../diamond/interfaces/IInfo.sol";

import { IResolution } from "../diamond/interfaces/IResolution.sol";

import { ISplitMerge } from "../diamond/interfaces/ISplitMerge.sol";

import { ITrading } from "../diamond/interfaces/ITrading.sol";

import { Types } from "../diamond/shared/Types.sol";

import { IRainDeployer } from "./IRainDeployer.sol";

/**
 * @title IRainPool
 * @notice Interface for the RainPool contract.
 */
interface IRainPool is
    ICancelOrder,
    IClaim,
    IDispute,
    IGetter,
    IInfo,
    IResolution,
    ISplitMerge,
    ITrading,
    Types
{
    /* ============================= STRUCTS ====================================== */

    /**
     * @title Params
     * @dev Struct for the params of a rain pool.
     * @notice This struct holds all the necessary information for a rain pool.
     * @param initialLiquidity The initial liquidity amount deposited into the pool, distributed among options.
     * @param liquidityPercentages Percentage distribution of `initialLiquidity` among different options, must sum to 100.
     * @param isPublic Determines if the pool is public (`true`) or private (`false`).
     * @param resolverIsAI Determines if the owner of the pool is also the resolver of the pool.
     * @param deployerContract The address of the deployerContract that created the pool.
     * @param baseToken The address of the base token used in the pool for voting and liquidity contributions.
     * @param poolOwner The address of the owner who controls the pool.
     * @param platformAddress The address of the platform responsible for managing the pool.
     * @param resolver The address of the resolver responsible for selecting the winning option.
     * @param disputeResolver The address of the dispute resolver AI responsible for selecting the winning option
     *        for resolving disputed.
     * @param rainToken The address of the Rain token.
     * @param referrer The address of the referrer of the pool.
     * @param pathTokenWETH The uniswap-path router for swapping to get to RainToken.
     * @param baseTokenDecimals The number of decimals used for the base token.
     * @param startTime The timestamp when the pool becomes active.
     * @param endTime The timestamp when the pool ends.
     * @param numberOfOptions The total number of options available for voting.
     * @param platformFee The fee percentage taken by the platform (e.g., 2.5% is represented as 25).
     * @param liquidityFee The fee percentage allocated to liquidity providers (e.g., 1.2% is represented as 12).
     * @param creatorFee The fee percentage given to the pool creator (e.g., 1% is represented as 10).
     * @param resultResolverFee The fee percentage for resolving the pool results (e.g., 0.1% is represented as 1).
     * @param closingFee The fee percentage for closing the pool results (e.g., 0.2% is represented as 2).
     * @param oracleFixedFee DEPRECATED — expected to be 0. No longer collected at pool creation
     *                       and no longer paid out at claim; a non-zero value would be spent from
     *                       collateral when DisputeFacet funds an appeal oracle.
     * @param oracleEndTime Duration (in seconds) granted to the appeal oracle for voting,
     *                      measured from the moment an appeal opens. NOT an absolute timestamp:
     *                      DisputeFacet computes the final deadline as block.timestamp + oracleEndTime
     *                      at appeal time, so callers must pass a relative duration.
     * @param ipfsUri The IPFS URI storing metadata or additional pool-related information.
     */
    struct Params {
        uint256 initialLiquidity;
        uint256[] liquidityPercentages;
        uint256[] initialYesPrices;
        bool isPublic;
        bool resolverIsAI;
        address deployerContract;
        address baseToken;
        address usdt;
        address poolOwner;
        address platformAddress;
        address resolver;
        address disputeResolver;
        address rainToken;
        address referrer;
        uint256 baseTokenDecimals;
        uint256 startTime;
        uint256 endTime;
        uint256 numberOfOptions;
        uint256 platformFee;
        uint256 liquidityFee;
        uint256 creatorFee;
        uint256 resultResolverFee;
        uint256 closingFee;
        uint256 oracleFixedFee;
        /// @notice Flat, non-refundable USDT charge added on top of the appeal fee, paid by the
        ///         appealer and forwarded straight to the oracle deployed for that appeal. This is
        ///         the sole funding source for appeal oracles — the resolver share is never used.
        uint256 appealOracleCost;
        uint256 oracleEndTime;
        string ipfsUri;
        IRainDeployer.TokenData tokenData;
        IRainPool.TradingModel tradingModel;
        /// @notice Seconds a facet cut must sit queued on this pool before it can be executed.
        ///         Copied from `RainDeployer.upgradeDelay` at creation and frozen for the life of
        ///         the pool — changing the deployer's global never reaches a pool already live.
        ///         `0` makes the pool immutable, which is how every pool created before timelocked
        ///         upgradeability existed behaves. Non-zero values are bounds-checked against
        ///         `LibDiamond.MIN_UPGRADE_DELAY` / `MAX_UPGRADE_DELAY` inside the pool.
        uint256 upgradeDelay;
        /// @notice Minimum initial liquidity for this pool, in USDT units. Copied from
        ///         `RainDeployer.minInitialLiquidity` at creation and enforced inside the pool's
        ///         init (converted through the quoter when the base token is not USDT). Applies to
        ///         both trading models. Zero is rejected (WLDC-706).
        uint256 minInitialLiquidity;
    }

    /// @notice Represents whether an order exists and its index in the linked list.
    struct OrderExists {
        /// @notice True if the order exists in the order book.
        bool exists;
        /// @notice Index of the order in the linked list.
        int256 index;
    }

    /* ============================= EVENTS ====================================== */

    /**
     * @dev Emitted when a user enters an option position.
     * @param option The identifier of the selected option.
     * @param optionSide The side of the option (1 or 2).
     * @param baseAmount The amount of base asset used to enter the option.
     * @param sharesAmount The amount of shares received.
     * @param wallet The address of the user entering the option.
     */
    event EnterOption(uint256 option, uint8 optionSide, uint256 baseAmount, uint256 sharesAmount, address wallet);

    /**
     * @dev Emitted when a user market-sells shares into the resting buy book via `sellOption`.
     * @param option The identifier of the selected option.
     * @param optionSide The side of the option (1 or 2).
     * @param baseAmount The net base asset received by the seller across all fills.
     * @param sharesAmount The amount of shares actually sold (filled); any unfilled remainder stays with the seller.
     * @param wallet The address of the user selling the option shares.
     */
    event SellOption(uint256 option, uint8 optionSide, uint256 baseAmount, uint256 sharesAmount, address wallet);

    /**
     * @dev Emitted when a user provides liquidity.
     * @param option Option in which liquidty is added
     * @param baseAmount The amount of base asset supplied as liquidity.
     * @param lpShares lpshares given for liqiuidity added
     * @param wallet The address of the user providing liquidity.
     */
    event AddLiquidity(uint256 option, uint256 baseAmount, uint256 lpShares, address indexed wallet);

    /**
     * @dev Emitted when a liquidity provider removes liquidity from an option's AMM.
     * @param option The option the LP is exiting.
     * @param lpShares The number of LP shares burned.
     * @param baseTokensReturned The base tokens returned after merging matched YES/NO pairs.
     * @param feesEarned Swap fees claimed at removal time.
     * @param wallet The address of the LP.
     */
    event RemoveLiquidity(
        uint256 option,
        uint256 lpShares,
        uint256 baseTokensReturned,
        uint256 yesReturned,
        uint256 noReturned,
        uint256 feesEarned,
        address indexed wallet
    );

    /**
     * @dev Emitted when shares synchronization occurs.
     * @param option The identifier of the option being synchronized.
     * @param yesReserve The AMM Yes-side reserve after the trade.
     * @param noReserve The AMM No-side reserve after the trade.
     * @param optionTotalFunds The total funds held in the option after the trade.
     */
    event Price(uint256 indexed option, uint256 yesReserve, uint256 noReserve, uint256 optionTotalFunds);

    /**
     * @dev Emitted when a specific option is closed.
     * @param option The option ID that was closed.
     * @param side which side of option eg: yes, no
     */
    event ClosePool(uint256 option, uint8 side);

    /**
     * @notice Emitted when a winning side is chosen for an option.
     * @param option The option ID resolved.
     * @param optionSide The winning side (1 or 2).
     * @param platformShare The amount of base tokens allocated to the platform.
     * @param winningShare The amount of base tokens distributed to the winning side.
     */
    event ChooseWinner(uint256 option, uint8 optionSide, uint256 platformShare, uint256 winningShare);

    /**
     * @notice Emitted when a winning side is chosen for an option after a dispute.
     * @param option The option ID resolved.
     * @param optionSide The winning side (1 or 2).
     * @param platformShare The amount of base tokens allocated to the platform.
     * @param winningShare The amount of base tokens distributed to the winning side.
     */
    event ChooseWinnerDispute(uint256 option, uint8 optionSide, uint256 platformShare, uint256 winningShare);

    /**
     * @notice Emitted when a winning option is finalized for the pool after an appeal.
     * @param option The option ID.
     * @param optionSide The winning side (1 or 2).
     * @param platformShare The amount of base tokens allocated to the platform.
     * @param winningShare The amount of base tokens distributed among users who voted for the winning option.
     */
    event ChooseWinnerAppeal(uint256 option, uint8 optionSide, uint256 platformShare, uint256 winningShare);

    /**
     * @dev Emitted when a user claims their rewards.
     * @param wallet The address of the user claiming the rewards.
     * @param option The identifier of the option.
     * @param winnerSide The side of the winning option (1 or 2).
     * @param winningReward The user's individual reward of winning side.
     */
    event Claim(address indexed wallet, uint256 option, uint8 winnerSide, uint256 winningReward);

    /**
     * @dev Emitted when a new oracle contract is created.
     * @param creatorContract The address of the contract that created the oracle.
     * @param createdContract The address of the newly created oracle contract.
     * @param option The option for which dispute is opened.

     */
    event CreateOracle(address indexed creatorContract, address indexed createdContract, uint256 option);

    /**
     * @notice Emitted when the platform claims its share of the pool funds.
     * @param wallet The address of the platform wallet receiving the funds.
     * @param amount The amount claimed by the platform.
     */
    event PlatformClaim(address indexed wallet, uint256 amount, uint256 option);

    /**
     * @notice Emitted when the creator of the pool claims their share.
     * @param wallet The address of the pool creator.
     * @param amount The amount claimed by the creator.
     */
    event CreatorClaim(address indexed wallet, uint256 amount, uint256 option);

    /**
     * @notice Emitted when the `refferer` of the pool claims their share.
     * @param wallet The address of the pool ``referrer`.
     * @param amount The amount claimed by the ``referrer`.
     */
    event ReferrerClaim(address indexed wallet, uint256 amount, uint256 option);

    /**
     * @notice Emitted when a resting maker is credited a rebate on a filled order-book trade.
     * @param maker The maker (owner of the resting order that was filled).
     * @param option The option the trade occurred on.
     * @param optionSide The side (1 = Yes, 2 = No).
     * @param amount The rebate amount credited to the maker in baseToken.
     */
    event MakerRebate(address indexed maker, uint256 option, uint8 optionSide, uint256 amount);

    /**
     * @notice Emitted when the resolver claims their share for resolving the outcome.
     * @param wallet The address of the resolver.
     * @param option The option ID.
     * @param amount The amount claimed by the resolver.
     */
    event ResolverClaim(address indexed wallet, uint256 option, uint256 amount);

    /**
     * @dev Emitted when a new oracle contract is created.
     * @param resolver The address of the resolver.
     * @param option The option ID.
     */
    event ResolverSet(address indexed resolver, uint256 option);

    /**
     * @notice Emitted when a new sell order is placed.
     * @param orderOption The option the order is placed for.
     * @param orderOptionSide The side of the option (1 or 2).
     * @param orderPrice The price at which the option is being sold.
     * @param sharesAmount The number of shares being sold.
     * @param orderID A unique identifier for the order.
     * @param maker The address of the user placing the order.
     */
    event PlaceSellOrder(
        uint256 orderOption,
        uint8 orderOptionSide,
        uint256 orderPrice,
        uint256 sharesAmount,
        uint256 orderID,
        address indexed maker
    );

    /**
     * @notice Emitted when a new buy order is placed.
     * @param orderOption The option the order is placed for.
     * @param orderOptionSide The side of the option (1 or 2).
     * @param orderPrice The price at which the option is being bought.
     * @param baseAmount The amount of base asset being used to buy the option tokens.
     * @param orderID A unique identifier for the order.
     * @param maker The address of the user placing the order.
     */
    event PlaceBuyOrder(
        uint256 orderOption,
        uint8 orderOptionSide,
        uint256 orderPrice,
        uint256 baseAmount,
        uint256 orderID,
        address indexed maker
    );

    /**
     * @notice Emitted when a sell order is fulfilled and the option tokens are bought.
     * @param orderOption The option being purchased.
     * @param orderOptionSide The side of the option (1 or 2).
     * @param orderPrice The price at which the order was fulfilled.
     * @param sharesAmount The number of shares bought.
     * @param baseAmount The amount of base asset used to buy the option tokens.
     * @param orderID The unique identifier of the fulfilled order.
     * @param maker The address of the user who placed the sell order.
     * @param taker The address of the user who bought the option tokens.
     */
    event ExecuteSellOrder(
        uint256 orderOption,
        uint8 orderOptionSide,
        uint256 orderPrice,
        uint256 sharesAmount,
        uint256 baseAmount,
        uint256 orderID,
        address indexed maker,
        address indexed taker
    );

    /**
     * @notice Emitted when a buy order is fulfilled and the option tokens are bought.
     * @param orderOption The option being purchased.
     * @param orderOptionSide The side of the option (1 or 2).
     * @param orderPrice The price at which the order was fulfilled.
     * @param sharesAmount The number of shares bought.
     * @param baseAmount The amount of base asset used to buy the option tokens.
     * @param orderID The unique identifier of the fulfilled order.
     * @param maker The address of the user who placed the buy order.
     * @param taker The address of the user who sold the option shares.
     */
    event ExecuteBuyOrder(
        uint256 orderOption,
        uint8 orderOptionSide,
        uint256 orderPrice,
        uint256 sharesAmount,
        uint256 baseAmount,
        uint256 orderID,
        address indexed maker,
        address indexed taker
    );

    /**
     * @notice Emitted when a sell order is cancelled.
     * @param orderOption The option associated with the cancelled order.
     * @param orderOptionSide The side of the option (1 or 2).
     * @param sharesAmount The number of shares that were listed in the cancelled order.
     * @param orderPrice The price at which the order was listed.
     * @param orderID The unique identifier for the cancelled order.
     * @param orderCreator The address of the user who created and cancelled the order.
     */
    event CancelSellOrder(
        uint256 orderOption,
        uint8 orderOptionSide,
        uint256 sharesAmount,
        uint256 orderPrice,
        uint256 orderID,
        address indexed orderCreator
    );

    /**
     * @notice Emitted when a buy order is cancelled.
     * @param orderOption The option associated with the cancelled order.
     * @param orderOptionSide The side of the option (1 or 2).
     * @param orderBaseAmount The number of base tokens that were listed in the cancelled order.
     * @param orderPrice The price at which the order was listed.
     * @param orderID The unique identifier for the cancelled order.
     * @param orderCreator The address of the user who created and cancelled the order.
     */
    event CancelBuyOrder(
        uint256 orderOption,
        uint8 orderOptionSide,
        uint256 orderBaseAmount,
        uint256 orderPrice,
        uint256 orderID,
        address indexed orderCreator
    );

    /**
     * @dev Emittted when a Dispute is opened.
     * @param caller The address of the function caller.
     * @param option the option on which dispute is created
     * @param currentWinner The current winner of the pool.
     * @param disputeFee The fee paid by the user if it's not the resolver for dispute.
     */
    event OpenDispute(address indexed caller, uint256 option, uint256 currentWinner, uint256 disputeFee);

    /**
     * @dev Emittted when an Appeal is opened.
     * @param caller The address of the function caller.
     * @param option The option being appealed.
     * @param currentWinner The current winner of the option.
     * @param appealFee The fee paid by the user if it's not the resolver for appeal.
     */
    event OpenAppeal(address indexed caller, uint256 option, uint256 currentWinner, uint256 appealFee);

    /**
     * @dev Emiited when rain tokens are burned.
     * @param amountBurned The amount of rain tokens burned.
     */
    event RainTokenBurned(uint256 amountBurned);

    /**
     * @dev Emitted when a resolution is proposed for a specific option.
     * @param option The option ID being resolved.
     * @param optionSide the side of option ie: yes=1, no=2
     * @param resolutionProposer The address of the user proposing a resolution.
     * @param resolverBond The amount of base tokens escrowed as resolver bond.
     * @param proposedWinner The yes/no winner proposed (true = Yes, false = No).
     */
    event ResolutionProposed(
        uint256 option,
        uint8 optionSide,
        address indexed resolutionProposer,
        uint256 resolverBond,
        uint8 proposedWinner
    );

    /**
     * @dev Emitted when a resolution proposer is refunded their resolver bond.
     * @param option The option ID.
     * @param optionSide the side of option ie: yes=1, no=2
     * @param resolutionProposer The address receiving the refund.
     * @param resolverBond The amount of base tokens refunded.
     * @param proposedWinner The yes/no outcome that was proposed.
     */
    event ResolutionProposerRefund(
        uint256 option,
        uint8 optionSide,
        address indexed resolutionProposer,
        uint256 resolverBond,
        uint8 proposedWinner
    );

    /**
     * @dev Emitted when a resolution is deemed too early and reverted for a specific option.
     * @param option The option ID whose resolution was reverted.
     * @param resolutionProposer The address that proposed the resolution.
     * @param resolverBond The resolver bond that was refunded.
     * @param proposedWinner The yes/no outcome that was proposed.
     */
    event TooEarly(uint256 option, address indexed resolutionProposer, uint256 resolverBond, uint8 proposedWinner);

    /**
     * @dev Emitted when a `disputeFee` is refunded to the `disputer`.
     * @param option The option ID.
     * @param disputer The address of the disputer.
     * @param disputeFee The `disputeFee` escrowed by the disputer.
     * @param disputedWinner The yes/no winner before the dispute was opened.
     */
    event DisputeFeeRefunded(uint256 option, address indexed disputer, uint256 disputeFee, uint8 disputedWinner);

    /**
     * @dev Emitted when a `appealFee` is refunded to the `appealer`.
     * @param option The option ID.
     * @param appealer The address of the appealer.
     * @param appealFee The `appealFee` escrowed by the appealer.
     * @param appealedWinner The winner before the appeal was opened.
     */
    event AppealFeeRefunded(uint256 option, address indexed appealer, uint256 appealFee, uint256 appealedWinner);

    /**
     * @dev Emitted when closing rewards are transferred to a resolver.
     * @param closer The address of the resolver claiming the closing reward.
     * @param option The option ID.
     * @param closingShare The amount of base tokens transferred as closing reward.
     */
    event ClosingShareClaim(address indexed closer, uint256 option, uint256 closingShare);

    /**
     * @dev Emitted when a user splits collateral into equal YES + NO shares.
     * @param option The option the shares belong to.
     * @param amount The amount of collateral split (and shares created per side).
     * @param wallet The user who performed the split.
     */
    event Split(uint256 option, uint256 amount, address indexed wallet);

    /**
     * @dev Emitted when a user merges equal YES + NO shares back into collateral.
     * @param option The option the shares were merged from.
     * @param amount The amount of share pairs merged (and collateral returned).
     * @param wallet The user who performed the merge.
     */
    event Merge(uint256 option, uint256 amount, address indexed wallet);

    /**
     * @dev Emitted when an LP claims accrued swap fees.
     * @param option The option the fees were earned from.
     * @param amount The amount of fees claimed.
     * @param wallet The LP who claimed the fees.
     */
    event ClaimSwapFees(uint256 option, uint256 amount, address indexed wallet);

    /* ========================== ERRORS ========================== */

    /**
     * @dev Error thrown when no token is set.
     */
    error NoTokenSet();

    /**
     * @dev Error thrown when no owner is set.
     */
    error NoOwnerSet();

    /**
     * @dev Error thrown when the start time of a sale has already ended.
     */
    error StartTimeEnded();

    /**
     * @dev Error thrown when the end time is less than the start time.
     */
    error EndTImeLessThanStartTime();

    /**
     * @dev Error thrown when the number of options is invalid (e.g., zero).
     */
    error InvalidOptions();

    /**
     * @dev Error thrown when the sale is not live.
     */
    error SaleNotLive();

    /**
     * @dev Error thrown when the sale is still live.
     */
    error SaleStillLive();

    /**
     * @dev Error thrown when no platform is set.
     */
    error NoPlatformSet();

    /**
     * @dev Error thrown when only the owner can perform the action.
     */
    error OnlyOwner();

    /**
     * @dev Error thrown when only authorized users can perform the action.
     */
    error OnlyAuthority();

    /**
     * @dev Error thrown when only resolver users can perform the action.
     */
    error OnlyResolver();

    /**
     * @dev Error thrown when the pool is closed.
     */
    error PoolClosed();

    /**
     * @dev Error thrown when the pool is open.
     */
    error PoolOpen();

    /**
     * @dev Error thrown when an action has already been claimed.
     */
    error AlreadyClaimed();

    /**
     * @dev Error thrown when the user is ineligible to claim.
     */
    error IneligibleToClaim();

    /**
     * @dev Error thrown when the pool is not yet closed.
     */
    error PoolNotClosed();

    /**
     * @dev Error thrown when the winner option is out of the valid range.
     */
    error WinnerOutOfBound();

    /**
     * @dev Error thrown when the liquidity percentage is invalid.
     */
    error InvalidLiquidityPercentage();

    /**
     * @dev Error thrown when the initial liquidity amount is invalid.
     */
    error InvalidInitialLiquidity();

    /**
     * @dev Error thrown when the amount is not sufficient.
     */
    error InsufficientAmount();

    /**
     * @dev Error thrown if the provided option is not valid.
     */
    error InvalidOption();

    /**
     * @dev Error thrown if the provided option side is not 1 or 2.
     */
    error InvalidSide();

    /**
     * @dev Error thrown if the provided price is not within the allowed range or format.
     */
    error InvalidPrice();

    /**
     * @dev Error thrown if the provided amount is zero or otherwise considered invalid.
     */
    error InvalidAmount();

    /**
     * @dev Thrown when an AMM swap amount is so small the liquidity fee truncates to
     *      zero, which would let the trade execute fee-free at LPs' expense.
     */
    error AmountTooSmall();

    /**
     * @dev Error thrown if the number of options exceeds the maximum allowed limit.
     */
    error MaximumOptionsExceeded();

    /**
     * @dev Thrown when the user does not have enough shares to complete the action.
     */
    error InsufficientUserShares();

    /**
     * @dev Thrown when the user does not have enough LP shares to complete the removal.
     */
    error InsufficientLPShares();

    /**
     * @dev Thrown when a liquidity deposit rounds down to zero LP shares. Minting zero
     *      would donate the deposit's reserve portion to existing LPs, so the whole
     *      deposit is reverted instead.
     */
    error LPSharesZero();

    /**
     * @dev Thrown when a caller tries to cancel an order they did not create.
     */
    error CallerNotOrderPlacer();

    /**
     * @dev Thrown when the caller is not the part of the pool.
     */
    error InvalidCaller();

    /**
     * @dev Thrown when order-book trading is not yet open for the option.
     */
    error OrderBookPhaseNotOpen();

    /**
     * @dev Thrown when a dispute is already opened.
     */
    error DisputeAlreadyOpened();

    /**
     * @dev Thrown when an order with the given ID does not exist in the system.
     */
    error OrderDoesNotExist();

    /**
     * @dev Thrown when trying to place an order that already exists with the given ID.
     */
    error OrderAlreadyExists();

    /**
     * @dev Thrown when a post-only (maker-only) order is placed at a price that would
     *      immediately cross the opposite book and execute as a taker. The order is
     *      rejected rather than routed through the matching loop, so the caller never
     *      pays taker fees against their intent (F-2026-17840).
     */
    error OrderWouldCross();

    /**
     * @dev Thrown when trying to buy an order that does not exist or if the orderBook linked list is not initalized.
     */
    error LinkedListNotInitalized();

    /**
     * @dev Thrown when the array length does not match.
     */
    error ArrayLengthMismatch();

    /**
     * @dev Thrown when the winner has already been decided.
     */
    error WinnerAlreadyFinalized();

    /**
     * @dev Thrown when the user tries to claim their rewards with existing sell orders.
     */
    error UserSellOrderExist();

    /**
     * @dev Thrown when the user tries to claim their rewards with existing Buy orders.
     */
    error UserBuyOrderExist();

    /**
     * @dev Thrown when the pool is in an invalid state for the attempted operation.
     */
    error InvalidPoolState();

    /**
     * @dev Thrown when the specified end price is below the allowed minimum.
     */
    error EndPriceTooLow();

    /**
     * @dev Thrown when the specified end price exceeds the allowed maximum.
     */
    error EndPriceTooHigh();

    /**
     * @dev Thrown when the attempted increase is not necessary or is redundant.
     */
    error NoIncreaseNeeded();

    /**
     * @dev Thrown when a user tries to open a dispute after the dispute window has ended.
     */
    error DisputeWindowEnded();

    /**
     * @dev Thrown when a user tries to claim before the dispute window has ended for a public pool.
     */
    error DisputeWindowNotEnded();

    /**
     * @dev Error thrown when the oracle has not been finalized.
     */
    error OracleNotFinalized();

    /**
     * @dev Error thrown when the oracle has ended the voting and the winner is still `0`.
     */
    error VotingEnded();

    /**
     * @dev Error thrown when oracleEndTime (a duration, in seconds) is `0`.
     *      A zero duration would create an instantly-expired appeal-oracle
     *      deadline and strand claims at ClaimFacet's timeout gate.
     */
    error InvalidOracleEndTime();

    /**
     * @dev Error thrown when the winner is not decided by the resolver.
     */
    error WinnerNotDecided();

    /**
     * @dev Thrown when user is at their `sell order` limit.
     */
    error UserSellOrderLimitReached();

    /**
     * @dev Thrown when user is at their `buy order` limit.
     */
    error UserBuyOrderLimitReached();

    /**
     * @dev Thrown when caller is not the `Pool Manager`.
     */
    error NotPoolManager();

    /**
     * @dev Thrown when an invalid function is called for the specific pool.
     */
    error InvalidCall();

    /**
     * @dev Thrown when the pool has already been initialized.
     */
    error AlreadyInitialized();

    /**
     * @dev Thrown when reward is zero.
     */

    error NoRewardToClaim();

    /**
     * @dev Thrown when `enterOption` is called past its caller-supplied `deadline`.
     */
    error DeadlineExpired();

    /**
     * @dev Thrown when the shares actually credited by `enterOption` fall below
     *      the caller-supplied `minSharesOut`.
     */
    error SlippageExceeded();
}

src/interfaces/IQuestion.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IQuestion {
    /**
     * @dev Struct representing an external source.
     * @param noOfOracles The number of oracles involved in the external source.
     * @param rewardPerOracle The reward allocated for each oracle.
     * @param loyaltyFee The loyalty fee associated with the external source.
     * @param totalExternalSourceCost The total cost of the external source.
     * @param totalOracleReward The total reward for all oracles.
     * @param startTime The start time of the external source.
     * @param endTime The end time of the external source.
     * @param numberOfOptions The total number of options available for the external source.
     * @param externalSourceURI The URI containing the external source details.
     * @param creator The address of the creator of the external source.
     */
    struct ExternalSourceInfo {
        uint256 noOfOracles;
        uint256 rewardPerOracle;
        uint256 loyaltyFee;
        uint256 totalExternalSourceCost;
        uint256 totalOracleReward;
        uint256 startTime;
        uint256 endTime;
        uint256 numberOfOptions;
        string externalSourceURI;
        address creator;
    }

    function winnerOption() external returns (uint256);

    function timeExtended() external returns (uint256);

    function winnerFinalized() external returns (bool);

    function getExternalSource() external view returns (ExternalSourceInfo memory);

    function calculateWinnerReadOnly() external view returns (uint256 option, uint256 reward);

    function refund() external;
}

