// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IDiamondCut {
    enum FacetCutAction {
        Add,
        Replace,
        Remove
    }
    // Add=0, Replace=1, Remove=2

    struct FacetCut {
        address facetAddress;
        FacetCutAction action;
        bytes4[] functionSelectors;
    }

    event DiamondCut(FacetCut[] _diamondCut, address _init, bytes _calldata);

    /// @notice A facet cut has been queued and becomes executable at `eta`.
    /// @dev Emitted before any state the cut describes is applied. The full cut payload is
    ///      carried in the event so the queued upgrade is publicly reviewable during the delay
    ///      without needing the proposer to publish it off-chain.
    event DiamondCutQueued(bytes32 indexed proposalId, uint256 eta, FacetCut[] _diamondCut, address _init, bytes _calldata);

    /// @notice A queued facet cut has been executed. Always paired with a {DiamondCut}.
    event DiamondCutExecuted(bytes32 indexed proposalId);

    /// @notice A queued facet cut has been withdrawn before execution.
    event DiamondCutCancelled(bytes32 indexed proposalId);

    /// @notice This pool was created with `upgradeDelay == 0` and is immutable.
    error UpgradesDisabled();

    /// @notice The delay baked into this pool at creation is outside the hard-coded bounds.
    error InvalidUpgradeDelay();

    /// @notice No proposal with this id is currently queued.
    error CutNotQueued();

    /// @notice This exact cut payload is already queued. Cancel it or execute it first.
    error CutAlreadyQueued();

    /// @notice The delay has not elapsed yet.
    error CutTimelockNotElapsed();

    /// @notice The proposal sat past its grace period and can no longer be executed.
    error CutProposalExpired();

    /// @notice Add/replace/remove any number of functions and optionally execute
    ///         a function with delegatecall
    /// @dev Construction-time entrypoint only. It reverts `AlreadyInitialized` on a live pool:
    ///      there is deliberately no instant-cut path. Every post-construction cut goes through
    ///      {proposeDiamondCut} then {executeDiamondCut}.
    /// @param _diamondCut Contains the facet addresses and function selectors
    /// @param _init The address of the contract or facet to execute _calldata
    /// @param _calldata A function call, including function selector and arguments
    ///                  _calldata is executed with delegatecall on _init
    function diamondCut(FacetCut[] calldata _diamondCut, address _init, bytes calldata _calldata) external;

    /// @notice Queue a facet cut. Executable once `upgradeDelay` has elapsed.
    /// @dev Caller must be the deployer (`ds.FACTORY`), whose owner is the protocol multisig.
    /// @return proposalId Hash identifying this exact cut payload.
    /// @return eta Timestamp from which {executeDiamondCut} succeeds.
    function proposeDiamondCut(
        FacetCut[] calldata _diamondCut,
        address _init,
        bytes calldata _calldata
    ) external returns (bytes32 proposalId, uint256 eta);

    /// @notice Apply a previously queued cut. The payload must hash to a queued proposal whose
    ///         `eta` has passed and whose grace period has not.
    function executeDiamondCut(FacetCut[] calldata _diamondCut, address _init, bytes calldata _calldata) external;

    /// @notice Withdraw a queued cut before it executes.
    function cancelDiamondCut(bytes32 proposalId) external;

    /// @notice Proposal id for a cut payload. Pure helper — mirrors the id the pool derives.
    function diamondCutProposalId(
        FacetCut[] calldata _diamondCut,
        address _init,
        bytes calldata _calldata
    ) external pure returns (bytes32);

    /// @notice Seconds between queueing and executability. Fixed at pool creation; `0` means the
    ///         pool is immutable and every cut path reverts.
    function upgradeDelay() external view returns (uint256);

    /// @notice Earliest execution timestamp for `proposalId`, or `0` if not queued.
    function cutEta(bytes32 proposalId) external view returns (uint256);

    /// @notice Window after `eta` during which a queued cut stays executable.
    function upgradeGracePeriod() external pure returns (uint256);
}

src/diamond/interfaces/IDiamondLoupe.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// A loupe is a small magnifying glass used to look at diamonds.
// These functions look at diamonds
interface IDiamondLoupe {
    /// These functions are expected to be called frequently
    /// by tools.
    struct Facet {
        address facetAddress;
        bytes4[] functionSelectors;
    }

    /// @notice Gets all facet addresses and their four byte function selectors.
    /// @return facets_ Facet
    function facets() external view returns (Facet[] memory facets_);

    /// @notice Gets all the function selectors supported by a specific facet.
    /// @param _facet The facet address.
    /// @return facetFunctionSelectors_
    function facetFunctionSelectors(address _facet) external view returns (bytes4[] memory facetFunctionSelectors_);

    /// @notice Get all the facet addresses used by a diamond.
    /// @return facetAddresses_
    function facetAddresses() external view returns (address[] memory facetAddresses_);

    /// @notice Gets the facet that supports the given selector.
    /// @dev If facet is not found return address(0).
    /// @param _functionSelector The function selector.
    /// @return facetAddress_ The facet address.
    function facetAddress(bytes4 _functionSelector) external view returns (address facetAddress_);
}

