// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { IERC20, SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";

import { LibDiamond } from "../libraries/LibDiamond.sol";

import { LibUtils } from "../libraries/LibUtils.sol";

import { IInfo } from "../interfaces/IInfo.sol";

import { _revert } from "../../utils/Globals.sol";

import { LinkedListLogic } from "../../libraries/LinkedList.sol";
import { LinkedListStorage } from "../../interfaces/LinkedListStorage.sol";

import { IRainPool } from "../../interfaces/IRainPool.sol";
import { IQuestion } from "../../interfaces/IQuestion.sol";

import { Types } from "../shared/Types.sol";

/**
 * @title InfoFacet
 * @author Rain Team
 * @notice External interface for the rain pool info facet.
 */
contract InfoFacet is IInfo {
    using SafeERC20 for IERC20;
    using LinkedListLogic for LinkedListStorage.LinkedList;

    /**
     * @inheritdoc IInfo
     */
    function totalOrders() external view returns (uint256) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        return ds.ordersAdded - ds.ordersRemoved;
    }

    /**
     * @inheritdoc IInfo
     */
    function getDynamicPayout(address user, uint256 option) external view returns (uint256[] memory dynamicPayout) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        // Index 0 unused, 1 = Yes side, 2 = No side
        dynamicPayout = new uint256[](3);

        uint256 optionFunds = ds.optionTotalFunds[option];
        // Protocol fees are collected per-trade from the taker, not deducted at
        // settlement, so the winning side receives the full pot at claim.

        // LP rewards from per-trade swap fees (feePerLPShareX128 accumulator)
        uint256 liquidityReward;
        if (ds.userOptionLPShares[option][user] > 0 && ds.totalOptionLPShares[option] > 0) {
            uint256 accum = ds.feePerLPShareX128[option];
            uint256 debt = ds.userFeeDebtX128[option][user];
            if (accum > debt) {
                liquidityReward = ((accum - debt) * ds.userOptionLPShares[option][user]) >> 128;
            }
        }

        uint256 rewardPayout;
        for (uint8 side = 1; side <= 2; ) {
            if (ds.optionPerSideShares[option][side] > 0) {
                // Direct shares + LP's proportional AMM reserves on this side
                uint256 userSideShares = ds.userOptionPerSideShares[option][side][user];
                if (ds.userOptionLPShares[option][user] > 0 && ds.totalOptionLPShares[option] > 0) {
                    uint256 sideReserve = side == 1 ? ds.ammYesReserve[option] : ds.ammNoReserve[option];
                    userSideShares += Math.mulDiv(
                        ds.userOptionLPShares[option][user],
                        sideReserve,
                        ds.totalOptionLPShares[option]
                    );
                }

                rewardPayout = (userSideShares * ds.PRICE_MAGNIFICATION) / (ds.optionPerSideShares[option][side]);

                rewardPayout = rewardPayout * optionFunds;
                rewardPayout = rewardPayout / ds.PRICE_MAGNIFICATION;

                dynamicPayout[side] = rewardPayout + liquidityReward;
            }
            unchecked {
                ++side;
            }
        }
    }

    /**
     * @inheritdoc IInfo
     */
    function getEntryShares(
        uint256 option,
        uint8 optionSide,
        uint256 amount
    ) external view returns (uint256 returnedShares, uint256 expectedPayout) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (option == 0 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }

        if (optionSide != 1 && optionSide != 2) {
            _revert(IRainPool.InvalidSide.selector);
        }

        if (amount <= 0) {
            _revert(IRainPool.InsufficientAmount.selector);
        }

        uint256 optionFunds = ds.optionTotalFunds[option];
        uint256 totalSharesReceived;

        if (LibDiamond.isAMMPhase(option)) {
            // Mirrors TradingFacet.enterOption AMM path: single-shot CPMM swap.
            // The taker pays the LP swap fee AND the protocol fee off the top.
            uint256 swapFee = (amount * ds.liquidityFee) / ds.FEE_MAGNIFICATION;
            uint256 protocolFee = (amount * LibDiamond.tradeFeeRate()) / ds.FEE_MAGNIFICATION;
            uint256 netAmount = amount - swapFee - protocolFee;
            totalSharesReceived = _cpmmShares(netAmount, ds.ammYesReserve[option], ds.ammNoReserve[option], optionSide);
            optionFunds += netAmount;
        } else if (LibDiamond.isOBPhase(option)) {
            // Mirrors TradingFacet.enterOption OrderBook path: walk the sell book upward.
            // Triggers for OB pools at any time and AMM pools once they flip to Phase B.
            uint256 head = ds.firstSellOrderPrice[option][optionSide];
            uint256 usedAmount;
            uint256 sharesReceived;
            int256 idx;

            while (amount > 1 && head > 0 && head <= 0.99 ether) {
                LinkedListStorage.LinkedList storage linkedList = ds.sellOrders[option][optionSide][head];

                bool tickWasEmpty = !linkedList.isInitialized || linkedList.isEmpty();
                bool consumedAllAtThisTick = false;

                if (!tickWasEmpty) {
                    idx = linkedList.first();
                    while (idx != linkedList.tailIndex && amount > 0) {
                        LinkedListStorage.Order memory order = linkedList.getData(idx);
                        idx = linkedList.next(idx);
                        (usedAmount, sharesReceived) = _getSellOrderAmounts(
                            option,
                            optionSide,
                            head,
                            amount,
                            order.orderID
                        );
                        amount -= usedAmount;
                        totalSharesReceived += sharesReceived;
                    }
                    consumedAllAtThisTick = (idx == linkedList.tailIndex);
                }

                if ((tickWasEmpty || consumedAllAtThisTick) && amount > 0) {
                    unchecked {
                        head += ds.TICK_SPACING;
                    }
                } else {
                    break;
                }
            }
        }

        returnedShares = totalSharesReceived;

        {
            // Winners receive the full pot — protocol fees were already taken at trade time.
            expectedPayout =
                (returnedShares * ds.PRICE_MAGNIFICATION) /
                (returnedShares + ds.optionPerSideShares[option][optionSide]);

            expectedPayout = expectedPayout * optionFunds;
            expectedPayout = (expectedPayout / ds.PRICE_MAGNIFICATION);
        }
    }

    /**
     * @inheritdoc IInfo
     */
    function getSellProceeds(
        uint256 option,
        uint8 optionSide,
        uint256 shares
    ) external view returns (uint256 proceeds, uint256 sharesSold) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (option == 0 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }
        if (optionSide != 1 && optionSide != 2) {
            _revert(IRainPool.InvalidSide.selector);
        }
        if (shares <= 0) {
            _revert(IRainPool.InsufficientAmount.selector);
        }

        // Mirrors TradingFacet.sellOption: walk the BUY book downward from the best bid,
        // filling resting bids until the seller's shares run out or the book is dry.
        // `proceeds` is net of the 1.2% maker rebate — exactly what the seller receives.
        uint256 remaining = shares;
        uint256 head = ds.firstBuyOrderPrice[option][optionSide];

        while (remaining > 1 && head >= ds.TICK_SPACING) {
            LinkedListStorage.LinkedList storage linkedList = ds.buyOrders[option][optionSide][head];

            bool tickWasEmpty = !linkedList.isInitialized || linkedList.isEmpty();
            bool consumedAllAtThisTick = false;

            if (!tickWasEmpty) {
                int256 idx = linkedList.first();
                while (idx != linkedList.tailIndex && remaining > 1) {
                    LinkedListStorage.Order memory order = linkedList.getData(idx);
                    idx = linkedList.next(idx);
                    (uint256 p, uint256 f) = _getBuyOrderAmounts(option, optionSide, head, remaining, order.orderID);
                    proceeds += p;
                    remaining -= f;
                    sharesSold += f;
                }
                consumedAllAtThisTick = (idx == linkedList.tailIndex);
            }

            if ((tickWasEmpty || consumedAllAtThisTick) && remaining > 1) {
                if (head <= ds.TICK_SPACING) {
                    break;
                }
                unchecked {
                    head -= ds.TICK_SPACING;
                }
            } else {
                break;
            }
        }
    }

    /**
     * @inheritdoc IInfo
     */
    function getReturnedLiquidity(
        uint256 option,
        uint256 totalAmount
    ) public view returns (uint256[] memory returnedShares, uint256[] memory returnedAmounts) {
        // Mirror enterLiquidity gating: only valid while the AMM is live (Phase A).
        LibDiamond.enforceAMMPhase(option);
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        // Index 0 unused, 1 = Yes side, 2 = No side
        returnedShares = new uint256[](3);
        returnedAmounts = new uint256[](3);

        uint256 x = ds.ammYesReserve[option];
        uint256 y = ds.ammNoReserve[option];
        uint256 totalReserves = x + y;
        if (totalReserves > 0) {
            // LP deposit is proportional to current AMM reserves
            returnedAmounts[1] = (totalAmount * x) / totalReserves;
            returnedAmounts[2] = totalAmount - returnedAmounts[1];
            // LP shares — must mirror _addLiquidityToOption, which divides by the
            // AMM-reserve sum (x + y), NOT optionTotalFunds. split()/merge() can
            // move optionTotalFunds without touching AMM reserves; using it here
            // would let frontend quotes diverge from on-chain mints.
            uint256 totalLP = ds.totalOptionLPShares[option];
            if (totalLP > 0) {
                returnedShares[1] = Math.mulDiv(totalAmount, totalLP, totalReserves);
                returnedShares[2] = returnedShares[1]; // same LP shares for both sides
            } else {
                returnedShares[1] = totalAmount;
                returnedShares[2] = totalAmount;
            }
        }
    }

    /**
     * @inheritdoc IInfo
     */
    function getRemovedLiquidity(
        uint256 option,
        uint256 lpShares
    ) external view returns (uint256 yesBack, uint256 noBack) {
        // Mirror removeLiquidity gating: AMM-mode, Phase A or B (not the claim window).
        LibDiamond.enforceAMMMode();
        if (!LibDiamond.isAMMPhase(option) && !LibDiamond.isOBPhase(option)) {
            _revert(IRainPool.PoolClosed.selector);
        }
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        uint256 totalLP = ds.totalOptionLPShares[option];
        if (totalLP == 0) {
            return (0, 0);
        }
        yesBack = Math.mulDiv(lpShares, ds.ammYesReserve[option], totalLP);
        noBack = Math.mulDiv(lpShares, ds.ammNoReserve[option], totalLP);
    }

    /**
     * @inheritdoc IInfo
     */
    function getImpactedPrice(uint256 option, uint8 optionSide, uint256 amount) public view returns (uint256) {
        LibDiamond.enforceAMMMode();
        if (optionSide != 1 && optionSide != 2) {
            _revert(IRainPool.InvalidSide.selector);
        }
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        uint256 x = ds.ammYesReserve[option];
        uint256 y = ds.ammNoReserve[option];
        uint256 M = ds.PRICE_MAGNIFICATION;
        uint256 k = Math.mulDiv(x, y, 1);
        // CPMM: after buying `amount` of optionSide, the opposite reserve grows
        // and the bought reserve shrinks via constant product.
        if (optionSide == 1) {
            // Buying YES: y' = y + amount, x' = k / y'
            uint256 yNew = y + amount;
            // price(YES) = y'^2 * M / (k + y'^2)
            uint256 yNewSq = Math.mulDiv(yNew, yNew, 1);
            return Math.mulDiv(yNewSq, M, k + yNewSq);
        } else {
            // Buying NO: x' = x + amount, y' = k / x'
            uint256 xNew = x + amount;
            // price(NO) = x'^2 * M / (k + x'^2)
            uint256 xNewSq = Math.mulDiv(xNew, xNew, 1);
            return Math.mulDiv(xNewSq, M, k + xNewSq);
        }
    }

    /**
     * @inheritdoc IInfo
     */
    function getReturnedShares(uint256 option, uint8 optionSide, uint256 amount) public view returns (uint256) {
        LibDiamond.enforceAMMMode();
        if (optionSide != 1 && optionSide != 2) {
            _revert(IRainPool.InvalidSide.selector);
        }
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        return _cpmmShares(amount, ds.ammYesReserve[option], ds.ammNoReserve[option], optionSide);
    }

    /**
     * @inheritdoc IInfo
     */
    function getAmountRequired(
        uint256 targetPrice,
        uint256 option,
        uint8 optionSide
    ) public view returns (uint256 requiredAmount) {
        LibDiamond.enforceAMMMode();
        if (optionSide != 1 && optionSide != 2) {
            _revert(IRainPool.InvalidSide.selector);
        }
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        requiredAmount = _cpmmAmountRequired(
            targetPrice,
            ds.ammYesReserve[option],
            ds.ammNoReserve[option],
            optionSide,
            ds.PRICE_MAGNIFICATION
        );
    }

    /**
     * @inheritdoc IInfo
     */
    function getCurrentPrice(uint256 option, uint8 optionSide) public view returns (uint256) {
        LibDiamond.enforceAMMMode();
        if (optionSide != 1 && optionSide != 2) {
            _revert(IRainPool.InvalidSide.selector);
        }
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        uint256 x = ds.ammYesReserve[option];
        uint256 y = ds.ammNoReserve[option];
        uint256 total = x + y;
        if (total == 0) return 0;
        // CPMM: price(YES=1) = y/(x+y),  price(NO=2) = x/(x+y)
        return optionSide == 1 ? (y * ds.PRICE_MAGNIFICATION) / total : (x * ds.PRICE_MAGNIFICATION) / total;
    }

    /**
     * @inheritdoc IInfo
     */
    function getDisputeAppealFee(uint256 option) external returns (uint256 stake) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        uint256 disputeFeeMinUSDT = ds.DISPUTE_FEE_MIN;
        uint256 disputeFeeMaxUSDT = ds.DISPUTE_FEE_MAX;

        stake = (ds.optionTotalFunds[option] * 1) / 1_000;

        // An option that is already disputed can only be appealed next, which carries the higher
        // floor and the oracle cost. A dispute round deploys no oracle, so it carries neither.
        bool isAppeal = ds.isOptionDisputed[option];
        if (isAppeal) {
            disputeFeeMinUSDT = ds.APPEAL_FEE_MIN;
        }

        if (ds.baseToken != ds.usdt) {
            uint256 disputeFeeInUSDT = LibUtils.getQuoteOut(ds.baseToken, stake, ds.tokenData);

            if (disputeFeeInUSDT > disputeFeeMaxUSDT) {
                stake = LibUtils.getQuoteIn(disputeFeeMaxUSDT, ds.tokenData);
            } else if (disputeFeeInUSDT < disputeFeeMinUSDT) {
                stake = LibUtils.getQuoteIn(disputeFeeMinUSDT, ds.tokenData);
            }
        } else {
            if (stake > disputeFeeMaxUSDT) {
                stake = disputeFeeMaxUSDT;
            } else if (stake < disputeFeeMinUSDT) {
                stake = disputeFeeMinUSDT;
            }
        }

        // Mirrors DisputeFacet._calculateAppealOracleCost, including its 1% slippage pad. The
        // oracle cost is folded into `stake` so the caller can approve the single returned
        // figure. A dispute round deploys no oracle, so nothing is added there.
        if (isAppeal && ds.appealOracleCost > 0) {
            stake += ds.baseToken != ds.usdt
                ? (LibUtils.getQuoteIn(ds.appealOracleCost, ds.tokenData) * 1010) / 1000
                : ds.appealOracleCost;
        }
    }

    /**
     * @inheritdoc IInfo
     */
    function getResolverBondAmount(uint256 option) external returns (uint256 resolverBondAmount) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        resolverBondAmount = (ds.optionTotalFunds[option] * 1) / 1000;

        if (ds.baseToken != ds.usdt) {
            uint256 disputeFeeInUSDT = LibUtils.getQuoteOut(ds.baseToken, resolverBondAmount, ds.tokenData);

            if (disputeFeeInUSDT > ds.RESOLUTION_FEE_MAX) {
                resolverBondAmount = LibUtils.getQuoteIn(ds.RESOLUTION_FEE_MAX, ds.tokenData);
            } else if (disputeFeeInUSDT < ds.RESOLUTION_FEE_MIN) {
                resolverBondAmount = LibUtils.getQuoteIn(ds.RESOLUTION_FEE_MIN, ds.tokenData);
            }
        } else {
            if (resolverBondAmount > ds.RESOLUTION_FEE_MAX) {
                resolverBondAmount = ds.RESOLUTION_FEE_MAX;
            } else if (resolverBondAmount < ds.RESOLUTION_FEE_MIN) {
                resolverBondAmount = ds.RESOLUTION_FEE_MIN;
            }
        }
    }

    /**
     * @inheritdoc IInfo
     */
    function getSharesReward(address user, uint256 option) external view returns (uint256 sharesReward) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        uint8 winner = ds.optionWinner[option];
        uint256 winningPoolShare = _getWinningPoolShare(option);

        if (winner != 0 && ds.optionPerSideShares[option][winner] > 0) {
            // Direct shares + LP's proportional AMM reserves on winning side
            uint256 userWinningShares = ds.userOptionPerSideShares[option][winner][user];
            if (ds.userOptionLPShares[option][user] > 0 && ds.totalOptionLPShares[option] > 0) {
                uint256 winnerReserve = winner == 1 ? ds.ammYesReserve[option] : ds.ammNoReserve[option];
                userWinningShares += Math.mulDiv(
                    ds.userOptionLPShares[option][user],
                    winnerReserve,
                    ds.totalOptionLPShares[option]
                );
            }
            sharesReward = (userWinningShares * winningPoolShare) / ds.optionPerSideShares[option][winner];
        }
    }

    /**
     * @inheritdoc IInfo
     */
    function getLiquidityReward(address user, uint256 option) external view returns (uint256 liquidityReward) {
        LibDiamond.enforceAMMMode();
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        // V2 CPMM: LP rewards come from per-trade swap fees (feePerLPShareX128 accumulator)
        if (ds.userOptionLPShares[option][user] > 0 && ds.totalOptionLPShares[option] > 0) {
            uint256 accum = ds.feePerLPShareX128[option];
            uint256 debt = ds.userFeeDebtX128[option][user];
            if (accum > debt) {
                liquidityReward = ((accum - debt) * ds.userOptionLPShares[option][user]) >> 128;
            }
        }
    }

    /**
     * @inheritdoc IInfo
     */
    function getCreatorReward(uint256 option) external view returns (uint256 creatorReward) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        // Fees accrue per-trade into the accumulator; return the amount collected so far.
        creatorReward = ds.optionCreatorShare[option];
    }

    /**
     * @inheritdoc IInfo
     */
    function getResolverReward(uint256 option) external view returns (uint256 resolverReward) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        // Fees accrue per-trade into the accumulator; return the amount collected so far.
        resolverReward = ds.optionResolverShare[option];
    }

    /**
     * @inheritdoc IInfo
     */
    function getClaimableAmount(address user, uint256 option) external view returns (uint256 total) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        // Already claimed → nothing left to claim.
        if (ds.optionClaimed[option][user]) {
            return 0;
        }

        // Resolve the effective winner. On appealed options the final winner lives in
        // the oracle and is not persisted to storage until the first claim runs
        // _firstClaimCheck, so mirror that oracle read here instead of reporting 0.
        uint8 winner = ds.optionWinner[option];
        if (winner == 0 && ds.optionState[option] == Types.PoolState.Appealed) {
            winner = _oracleWinner(option);
        }
        if (winner == 0) {
            return 0;
        }

        // 1) Winning payout — exact, mirrors claim() using the FROZEN snapshot.
        uint256 lpShares = ds.userOptionLPShares[option][user];
        uint256 totLp = ds.totalOptionLPShares[option];

        if (lpShares > 0 && totLp > 0) {
            uint256 accum = ds.feePerLPShareX128[option];
            uint256 debt = ds.userFeeDebtX128[option][user];
            if (accum > debt) {
                total += ((accum - debt) * lpShares) >> 128;
            }
        }

        uint256 userWin = ds.userOptionPerSideShares[option][winner][user];
        if (lpShares > 0 && totLp > 0) {
            uint256 winnerReserve = winner == 1 ? ds.ammYesReserve[option] : ds.ammNoReserve[option];
            userWin += Math.mulDiv(lpShares, winnerReserve, totLp);
        }

        uint256 sideShares = ds.optionPerSideShares[option][winner];
        if (sideShares > 0) {
            total += (userWin * ds.optionWinningPoolShare[option]) / sideShares;
        }

        // 2) Role rewards the user is owed, mirroring ClaimFacet._firstClaimCheck branch for
        //    branch. Gated on !optionFirstClaim: role fees are paid exactly once, at the first
        //    claim, and unlike the share slots they are not zeroed here — so after the first
        //    claim they must not be counted.
        if (!ds.optionFirstClaim[option]) {
            // creator (50/50 referrer+owner, else 100% owner). _distributeOptionFees pays this
            // ahead of any dispute branching, so it lands on every path — disputed or not.
            uint256 creatorShare = ds.optionCreatorShare[option];
            if (ds.referrer != address(0)) {
                if (user == ds.referrer) {
                    total += creatorShare / 2;
                }
                if (user == ds.poolOwner) {
                    total += creatorShare - creatorShare / 2;
                }
            } else if (user == ds.poolOwner) {
                total += creatorShare;
            }

            Types.PoolState state = ds.optionState[option];

            // Set when the dispute/appeal settlement already consumed the resolver bond, so the
            // `_refundResolverBond` mirror below does not credit it a second time.
            bool bondSettled;

            if (state == Types.PoolState.NotDisputed) {
                // resolver share -> AI resolver, or the proposer on non-AI pools
                address resolverRecipient = ds.resolverIsAI
                    ? LibDiamond.liveResolver(ds)
                    : ds.optionResolutionProposer[option];
                if (user == resolverRecipient) {
                    total += ds.optionResolverShare[option];
                }

                if (user == ds.poolOwner && ds.baseToken == ds.usdt) {
                    total += ds.oracleFixedFee;
                }
            } else if (state == Types.PoolState.Disputed) {
                // Nobody appealed, so the dispute resolver's answer is final by default and it
                // takes the resolver share whichever way the verdict went.
                if (user == LibDiamond.liveDisputeResolver(ds)) {
                    total += ds.optionResolverShare[option];
                }

                // The disputer recovers their stake and takes the forfeit bucket — here just the
                // closer's bond — when they overturned the close. Otherwise their stake is
                // forfeited to the platform, which is not a claimant.
                if (winner != ds.optionDispute[option].disputedWinner) {
                    bondSettled = true;
                    if (user == ds.optionDispute[option].disputer) {
                        total += ds.optionDispute[option].disputeFee + ds.optionResolverBond[option];
                    }
                }

                if (user == ds.poolOwner && ds.baseToken == ds.usdt) {
                    total += ds.oracleFixedFee;
                }
            } else {
                // Appealed. Mirrors ClaimFacet._settleAppealOutcome: a forfeit bucket split evenly
                // among the challengers who were right, plus the resolver share routed to
                // whichever resolver's answer matches the final winner.
                bool disputerRight = winner != uint8(ds.optionDispute[option].disputedWinner);
                bool appealerRight = winner != uint8(ds.optionAppeal[option].disputedWinner);

                uint256 disputeFee = ds.optionDispute[option].disputeFee;
                uint256 appealFee = ds.optionAppeal[option].disputeFee;

                uint256 forfeited;
                if (disputerRight) {
                    bondSettled = true;
                    forfeited += ds.optionResolverBond[option];
                } else {
                    forfeited += disputeFee;
                }
                if (!appealerRight) {
                    forfeited += appealFee;
                }

                uint256 correctChallengers = (disputerRight ? 1 : 0) + (appealerRight ? 1 : 0);
                uint256 each = correctChallengers > 0 ? forfeited / correctChallengers : 0;

                if (disputerRight && user == ds.optionDispute[option].disputer) {
                    total += disputeFee + each;
                }
                if (appealerRight && user == ds.optionAppeal[option].disputer) {
                    total += appealFee + each;
                }

                if (!appealerRight) {
                    // The appeal upheld the dispute resolver's answer.
                    if (user == LibDiamond.liveDisputeResolver(ds)) {
                        total += ds.optionResolverShare[option];
                    }
                } else if (!disputerRight) {
                    // The appeal overturned it and restored the original answer.
                    address originalResolver = ds.resolverIsAI
                        ? LibDiamond.liveResolver(ds)
                        : ds.optionResolutionProposer[option];
                    if (user == originalResolver) {
                        total += ds.optionResolverShare[option];
                    }
                }
                // Both resolvers overturned -> the share goes to the platform, not a claimant.

                // Omitted: on the oracle-timeout path (timeExtended == 7) the appealer additionally
                // gets their oracle cost back, in USDT, if the oracle's refund() succeeds. That
                // hinges on an external call and on the oracle actually holding the funds, so it
                // cannot be predicted here — this figure is a floor for the appealer on that path.
            }

            // closing share -> the dispute resolver when a non-AI proposer called it wrong,
            // otherwise the proposer. Paid on every state.
            address closingRecipient = (!ds.resolverIsAI &&
                (ds.isOptionDisputed[option] || ds.isOptionAppealed[option]) &&
                winner != ds.optionProposedWinner[option])
                ? ds.optionDispute[option].resolver
                : ds.optionResolutionProposer[option];
            if (user == closingRecipient) {
                total += ds.optionClosingShare[option];
            }

            // resolver bond -> proposer when AI or the proposal was correct, else forfeited to
            // the dispute resolver. Mirrors ClaimFacet._refundResolverBond, which is a no-op when
            // the settlement above already paid the bond out as part of the forfeit bucket.
            if (!bondSettled) {
                if (ds.resolverIsAI || ds.optionProposedWinner[option] == winner) {
                    if (user == ds.optionResolutionProposer[option]) {
                        total += ds.optionResolverBond[option];
                    }
                } else if (
                    (ds.isOptionDisputed[option] || ds.isOptionAppealed[option]) &&
                    user == ds.optionDispute[option].resolver
                ) {
                    total += ds.optionResolverBond[option];
                }
            }
        }
    }

    /**
     * @inheritdoc IInfo
     */
    function isOptionParticipant(uint256 option, address user) external view returns (bool) {
        return LibDiamond.isOptionParticipant(option, user);
    }

    /**
     * @dev Read-only winner resolution for appealed options whose winner has not yet
     *      been persisted to storage (that write happens on the first claim). Mirrors
     *      the oracle read in ClaimFacet._firstClaimCheck: use the oracle's read-only
     *      result, falling back to the pre-appeal winner when the oracle produced no
     *      consensus. Returns 0 when no valid winner can be determined yet, so the
     *      caller keeps reporting 0 (never over-reports on an unfinalized appeal).
     */
    function _oracleWinner(uint256 option) private view returns (uint8 winner) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        try IQuestion(ds.optionResolver[option]).calculateWinnerReadOnly() returns (uint256 w, uint256) {
            // Only 1/2 are claimable winners; anything else (including 3 = "too early", which
            // means the option will be reopened via resolveAppealTooEarly rather than paid out)
            // previews as 0 so this never over-reports a claimable balance on an unfinalized appeal.
            if (w >= 1 && w <= 2) {
                winner = uint8(w);
            }
        } catch {
            uint256 preAppealWinner = ds.optionAppeal[option].disputedWinner;
            if (preAppealWinner >= 1 && preAppealWinner <= 2) {
                winner = uint8(preAppealWinner);
            }
        }
    }

    /**
     * @dev Checks the values for the `amountExecuted` and `shareAmount` against a specific sell order in the order
     * book.
     * @param option The index of the option being bought.
     * @param optionSide The side of the option (1 or 2).
     * @param price The price per unit for the sell order.
     * @param fundsAmount The amount of funds user provides to buy the order.
     * @param orderID The unique identifier of the sell order to be fulfilled.
     * @return amountExecuted The amount in baseToken received by the seller.
     * @return shareAmount The amount of shares received by the buyer.
     */
    function _getSellOrderAmounts(
        uint256 option,
        uint8 optionSide,
        uint256 price,
        uint256 fundsAmount,
        uint256 orderID
    ) private view returns (uint256 amountExecuted, uint256 shareAmount) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        LinkedListStorage.LinkedList storage linkedList = ds.sellOrders[option][optionSide][price];

        int256 nodeIndex = ds.orderBook[option][optionSide][price][orderID].index;

        uint256 orderAmount = LinkedListLogic.getAmount(linkedList, nodeIndex);

        // Mirror TradingFacet._executeSellOrder: size shares down so the taker's funds
        // cover the maker's notional plus the per-fill maker rebate AND the protocol
        // fee, and return `amountExecuted` as the taker's total spend
        // (gross + rebate + protocol fee).
        uint256 maxGross = (fundsAmount * ds.FEE_MAGNIFICATION) /
            (ds.FEE_MAGNIFICATION + ds.MAKER_REBATE_FEE + LibDiamond.tradeFeeRate());
        shareAmount = (maxGross * ds.PRICE_MAGNIFICATION) / price;

        if (orderAmount > shareAmount) {
            orderAmount = shareAmount;
        } else {
            shareAmount = orderAmount;
        }

        uint256 grossProceeds = (orderAmount * price) / (ds.PRICE_MAGNIFICATION);
        uint256 makerRebate = (grossProceeds * ds.MAKER_REBATE_FEE) / ds.FEE_MAGNIFICATION;
        uint256 protocolFee = (grossProceeds * LibDiamond.tradeFeeRate()) / ds.FEE_MAGNIFICATION;
        amountExecuted = grossProceeds + makerRebate + protocolFee;
    }

    /**
     * @dev Preview helper mirroring TradingFacet._executeBuyOrder for one resting bid:
     *      returns the base `proceeds` the seller receives (gross minus the 1.2% maker
     *      rebate and the protocol fee) and the shares consumed from `sellShares`
     *      against this bid.
     */
    function _getBuyOrderAmounts(
        uint256 option,
        uint8 optionSide,
        uint256 price,
        uint256 sellShares,
        uint256 orderID
    ) private view returns (uint256 proceeds, uint256 sharesFilled) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        LinkedListStorage.LinkedList storage linkedList = ds.buyOrders[option][optionSide][price];
        int256 nodeIndex = ds.orderBook[option][optionSide][price][orderID].index;
        uint256 orderAmount = LinkedListLogic.getAmount(linkedList, nodeIndex); // bid funds (base)

        sharesFilled = (orderAmount * ds.PRICE_MAGNIFICATION) / price; // shares this bid can absorb

        uint256 amountExecuted;
        if (sellShares >= sharesFilled) {
            amountExecuted = orderAmount; // bid fully consumed
        } else {
            sharesFilled = sellShares; // partial: seller's remaining size caps the fill
            amountExecuted = (sellShares * price) / ds.PRICE_MAGNIFICATION;
        }

        uint256 makerRebate = (amountExecuted * ds.MAKER_REBATE_FEE) / ds.FEE_MAGNIFICATION;
        uint256 protocolFee = (amountExecuted * LibDiamond.tradeFeeRate()) / ds.FEE_MAGNIFICATION;
        proceeds = amountExecuted - makerRebate - protocolFee;
    }

    // ─── Private CPMM helpers (pure math, used by simulation functions) ────

    /**
     * @dev CPMM shares returned when buying `amount` of `optionSide`.
     *      Split amount → YES + NO, sell opposite into AMM.
     *      Buying YES: shares = A*(x+y+A)/(y+A)
     *      Buying NO:  shares = A*(x+y+A)/(x+A)
     */
    function _cpmmShares(uint256 amount, uint256 x, uint256 y, uint8 optionSide) private pure returns (uint256) {
        uint256 denom = optionSide == 1 ? y + amount : x + amount;
        return Math.mulDiv(amount, x + y + amount, denom);
    }

    /**
     * @dev CPMM amount required to move price to `targetPrice`.
     *      reserveTarget = sqrt(k * p / (M - p)), amount = reserveTarget - currentReserve.
     */
    function _cpmmAmountRequired(
        uint256 targetPrice,
        uint256 x,
        uint256 y,
        uint8 optionSide,
        uint256 M
    ) private pure returns (uint256) {
        if (x == 0 || y == 0 || targetPrice >= M) return 0;
        uint256 kTimesP = Math.mulDiv(x, Math.mulDiv(y, targetPrice, M - targetPrice), 1);
        uint256 reserveTarget = Math.sqrt(kTimesP);
        if (reserveTarget * reserveTarget < kTimesP) {
            unchecked {
                ++reserveTarget;
            }
        }
        uint256 currentReserve = optionSide == 1 ? y : x;
        if (reserveTarget <= currentReserve) return 1;
        return reserveTarget - currentReserve;
    }

    /**
     * @dev Returns the reward for the winning side of an option. Protocol fees are
     *      collected per-trade from the taker (not carved out at settlement), so the
     *      winning pool is the entire pot.
     * @param option The option to calculate the winning pool share for.
     */
    function _getWinningPoolShare(uint256 option) private view returns (uint256 winningPoolShare) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        winningPoolShare = ds.optionTotalFunds[option];
    }
}

src/interfaces/IRainDeployer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { Types } from "../diamond/shared/Types.sol";

import { IDiamondCut } from "../diamond/interfaces/IDiamondCut.sol";

/**
 * @title IRainDeployer
 * @notice Interface for the RainDeployer contract.
 */
interface IRainDeployer {
    /* ========================== STRUCTS ======================================= */

    /**
     * @notice Struct to define parameters for creating a RainPool.
     * @param isPublic Indicates whether the pool is public or private.
     * @param resolverIsAI Indicates whether the owner is the pool resolver or not.
     * @param poolOwner The address of the pool owner.
     * @param referrer The address of the pool referrer.
     * @param startTime The timestamp when the pool starts.
     * @param endTime The timestamp when the pool ends.
     * @param numberOfOptions The total number of options available in the pool.
     * @param oracleEndTime Duration (in seconds) granted to the appeal oracle for voting,
     *                      measured from the moment an appeal opens. NOT an absolute timestamp:
     *                      DisputeFacet computes the final deadline as block.timestamp + oracleEndTime
     *                      at appeal time, so callers must pass a relative duration (e.g. `3 days`).
     * @param ipfsUri The IPFS URI containing metadata for the pool.
     * @param initialLiquidity The amount of initial liquidity added to the pool.
     * @param liquidityPercentages An array representing the percentage allocation of liquidity to each option.
     */
    struct Params {
        bool isPublic;
        bool resolverIsAI;
        address poolOwner;
        address referrer;
        uint256 startTime;
        uint256 endTime;
        uint256 numberOfOptions;
        uint256 oracleEndTime;
        string ipfsUri;
        uint256 initialLiquidity;
        uint256[] liquidityPercentages;
        uint256[] initialYesPrices;
        address baseToken;
        Types.TradingModel tradingModel;
    }

    /**
     * @notice Stores configuration and routing data for a supported token.
     * @dev Used to determine swap routes, pool type, and allowance status for a token.
     */
    struct TokenData {
        /// @notice The Uniswap pool version used for this token.
        TokenPool tokenPool;
        /// @notice Indicates whether the token is currently allowed by the protocol.
        bool isAllowed;
        /// @notice The address of the router contract used for swaps.
        address routerAddress;
        /// @notice The address of the router helper contract, if applicable.
        address routerHelper;
        /// @notice The Uniswap swap path from USDT to the token.
        bytes pathUSDTToToken;
        /// @notice The Uniswap swap path from the token to USDT.
        bytes pathTokenToUSDT;
        /// @notice The Uniswap swap path from the token to WETH.
        bytes pathTokenWETH;
    }

    /* ================================= ENUMS ================================= */

    /**
     * @notice Supported Uniswap pool versions.
     * @param V2 Uniswap V2 pool.
     * @param V3 Uniswap V3 pool.
     * @param V4 Uniswap V4 pool.
     */
    enum TokenPool {
        V2,
        V3,
        V4
    }

    /* =============================  EVENTS ==================================== */

    /**
     * @notice Emitted when a new pool is created.
     * @param poolAddress The address of the newly created pool.
     * @param poolCreator The address of the pool creator.
     * @param uri The IPFS URI containing pool metadata.
     * @param tradingModel The trading model selected for the pool (AMM or OrderBook).
     */
    event PoolCreated(
        address indexed poolAddress,
        address indexed poolCreator,
        string uri,
        Types.TradingModel tradingModel
    );

    /**
     * @notice Emitted when a token is set for a pool.
     * @param poolAddress The address of the pool for which the token is set.
     * @param tokenAddress The address of the token assigned to the pool.
     * @param tokenDecimals The number of decimals used by the token.
     * @param tokenName The name of the token.
     * @param tokenSymbol The symbol of the token.
     */
    event PoolTokenSet(
        address indexed poolAddress,
        address indexed tokenAddress,
        uint256 tokenDecimals,
        string tokenName,
        string tokenSymbol
    );

    /**
     * @notice Emitted when a new token is added to the list of allowed tokens.
     * @param tokenAddress The address of the newly allowed token.
     * @param tokenDecimals The number of decimals used by the token.
     * @param tokenName The name of the token.
     * @param tokenSymbol The symbol of the token.
     */
    event NewTokenAllowed(address indexed tokenAddress, uint256 tokenDecimals, string tokenName, string tokenSymbol);

    /**
     * @notice Emitted when an existing token is removed from the list of allowed tokens.
     * @param tokenAddress The address of the disallowed token.
     * @param tokenDecimals The number of decimals used by the token.
     * @param tokenName The name of the token.
     * @param tokenSymbol The symbol of the token.
     */
    event ExistingTokenDisallowed(
        address indexed tokenAddress,
        uint256 tokenDecimals,
        string tokenName,
        string tokenSymbol
    );

    /**
     * @notice Emitted when a configured protocol address is updated by the owner.
     * @param parameter A human-readable name identifying which address was updated.
     * @param oldAddress The previous address.
     * @param newAddress The new address.
     */
    event AddressUpdated(string parameter, address indexed oldAddress, address indexed newAddress);

    /**
     * @notice Emitted when a protocol fee parameter is updated by the owner.
     * @param parameter A human-readable name identifying which fee was updated.
     * @param oldValue The previous fee value.
     * @param newValue The new fee value.
     */
    event FeeUpdated(string parameter, uint256 oldValue, uint256 newValue);

    /**
     * @notice Emitted when a diamond facet address and its selectors are updated by the owner.
     * @param facet A human-readable name identifying which facet was updated.
     * @param oldFacet The previous facet address.
     * @param newFacet The new facet address.
     * @param selectors The function selectors registered for the new facet.
     */
    event FacetUpdated(string facet, address indexed oldFacet, address indexed newFacet, bytes4[] selectors);

    /**
     * @notice Emitted when the delay stamped onto newly created pools changes.
     * @dev Pools already live are unaffected.
     */
    event UpgradeDelayUpdated(uint256 oldDelay, uint256 newDelay);

    /**
     * @notice Emitted when the minimum initial liquidity stamped onto newly created pools changes.
     * @dev Denominated in USDT. Pools already live are unaffected.
     */
    event MinInitialLiquidityUpdated(uint256 oldValue, uint256 newValue);

    /**
     * @notice Emitted when a facet cut is queued against a pool.
     * @dev The pool emits `DiamondCutQueued` with the full payload in the same transaction; this
     * event exists so the whole estate's upgrade activity can be followed from one address.
     */
    event PoolCutProposed(address indexed pool, bytes32 indexed proposalId, uint256 eta);

    /// @notice Emitted when a queued facet cut is applied to a pool.
    event PoolCutExecuted(address indexed pool, bytes32 indexed proposalId);

    /// @notice Emitted when a queued facet cut is withdrawn before execution.
    event PoolCutCancelled(address indexed pool, bytes32 indexed proposalId);

    /* ============================= ERRORS ================================= */

    /**
     * @dev Thrown when an action is attempted by an address that is not a created pool.
     */
    error OnlyCreatedPool();

    /**
     * @dev Thrown when the address is not valid.
     */
    error InvalidAddress();

    /**
     * @dev Thrown when a user passes an invalid value.
     */
    error InvalidValue();

    /**
     * @dev Thrown when there's a mismatch between the amount the user has passed and the
       balance of the the new `RainPool`.
     */
    error BalanceMismatch();

    /**
     * @dev Thrown when a user passes an invalid initial liquidity.
     */
    error InvalidInitialLiquidity();

    /**
     * @dev Thrown when there is a length mismatch between array or number of options.
     */
    error LengthMismatch();

    /**
     * @dev Thrown when there is a array length of function selectors array is 0.
     */
    error InvalidBytes();

    /**
     * @dev Thrown when a user tries to create a pool with an invalid token.
     */
    error TokenNotAllowed();

    /**
     * @dev Thrown when the pool liquidity for the external provided pool is insufficient to perform a swap.
     */
    error InsufficientPoolLiquidity();

    /**
     * @dev Thrown when path is not valid for swapping.
     */
    error InvalidPath();

    /**
     * @dev Thrown when a private pool is created with the OrderBook trading model.
     *      Private pools must use the AMM trading model.
     */
    error OrderBookNotAllowedForPrivatePool();

    /**
     * @dev Thrown when the four resolution-time fees (platform, creator, resultResolver, closing)
     *      would sum to FEE_MAGNIFICATION or more. Such a configuration underflows the winning-pool
     *      share computation in ResolutionFacet._calculateOptionFees and would brick resolution.
     */
    error InvalidFeeConfiguration();

    /**
     * @dev Thrown by `createPool` while `minInitialLiquidity` is 0. The slot reads 0 on an
     *      upgraded proxy until the owner sets it, and a zero floor would re-open the bypass
     *      WLDC-706 closes, so pool creation fails closed rather than silently unfloored.
     */
    error MinInitialLiquidityNotSet();

    /* ============================= FUNCTIONS ================================= */

    /**
     * @notice Returns the address of the Oracle Factory used for creating oracle contracts.
     * @dev This address is set during deployment and used for resolving results.
     * @return The address of the Oracle Factory contract.
     */
    function oracleFactoryAddress() external view returns (address);

    /**
     * @notice Returns the address of the base token used in the pools.
     * @dev The base token is the primary currency used for transactions within the platform.
     * @return The address of the base token contract.
     */
    function baseToken() external view returns (address);

    /**
     * @notice Returns the platform's designated address for receiving fees.
     * @dev All platform fees are transferred to this address.
     * @return The address where platform fees are collected.
     */
    function platformAddress() external view returns (address);

    /**
     * @notice Returns the address for the backend pool result resolver AI.
     * @return The address of the resolver AI.
     */
    function resolverAI() external view returns (address);

    /**
     * @notice Returns the liquidity fee percentage.
     * @dev The liquidity fee is applied to the total pool funds.
     * @return The liquidity fee percentage.
     */
    function liquidityFee() external view returns (uint256);

    /**
     * @notice Returns the platform fee percentage.
     * @dev This fee is deducted from the total pool funds as a platform charge.
     * @return The platform fee percentage.
     */
    function platformFee() external view returns (uint256);

    /**
     * @notice Returns the fixed fee charged for oracle services.
     * @dev DEPRECATED. The prepaid oracle budget is retired — pools no longer collect it
     */
    function oracleFixedFee() external view returns (uint256);

    /**
     * @notice Returns the flat USDT cost of deploying an appeal oracle.
     * @dev Charged on top of the appeal stake, paid by the appealer and forwarded straight to the
     * oracle created for that appeal. Non-refundable and never forfeited — it is a cost, not a bond.
     * This is the sole funding source for appeal oracles; the resolver share is never spent on them.
     * Only appeals carry this charge: a dispute round deploys no oracle, so it has nothing to pay for.
     * @return The flat appeal oracle cost, denominated in USDT.
     */
    function appealOracleCost() external view returns (uint256);

    /**
     * @notice Seconds a facet cut must sit queued on a pool before it can be executed.
     * @dev Stamped onto each pool at creation and frozen there. Changing it here only affects
     * pools created afterwards. `0` mints immutable pools.
     * @return The upgrade delay applied to newly created pools, in seconds.
     */
    function upgradeDelay() external view returns (uint256);

    /**
     * @notice Sets the upgrade delay stamped onto newly created pools.
     * @dev Owner only. Accepts `0` (immutable pools) or a value within the protocol's delay
     * bounds. Never reaches a pool that is already live.
     * @param newUpgradeDelay The new delay in seconds.
     */
    function setUpgradeDelay(uint256 newUpgradeDelay) external;

    /**
     * @notice Minimum initial liquidity a pool may be created with, denominated in USDT.
     * @dev Stamped onto each pool at creation as its `MINIMUM_LIQUIDITY` and enforced inside the
     * pool's own init code, converted through the Uniswap quoter when the pool's base token is not
     * USDT. Applies to both trading models. Changing it here only affects pools created afterwards.
     * @return The floor in USDT units.
     */
    function minInitialLiquidity() external view returns (uint256);

    /**
     * @notice Predicts whether an inflow of `amount` in `token` would be refused by the USDR
     *         solvency gate, and the largest amount that would not be.
     *
     * @dev Exists so callers do not have to reproduce the rule. Doing that off-chain means
     *      hardcoding USDR's engine address, its `reserveFactor` arithmetic, the fail-open
     *      behaviour, and the per-token scoping -- every one of which has moved at least once,
     *      and each of which becomes a client release when it moves again. This reads the same
     *      storage the gate reads, so the two cannot drift.
     *
     *      Answers for pools that do not exist yet, which is the case a pool-side view cannot
     *      serve: `createPool` records the initial liquidity through the ledger like any other
     *      inflow, so a market can be refused before there is a market to ask.
     *
     *      EXACT FOR MARKET CREATION, CONSERVATIVE FOR TRADES. The initial liquidity of a new
     *      pool flows entirely in, so the prediction is precise. An order-book order that matches
     *      resting asks pays money back out in the same call, so the pool's NET inflow is smaller
     *      than `amount` and an order somewhat above `maxAmount` can still succeed. Treat this as
     *      authoritative when creating a market, and as a warning when trading -- do not disable
     *      a trade on it, or orders the chain would have accepted get blocked.
     *
     *      NOT A SUBSTITUTE FOR HANDLING THE REVERT. Headroom is shared across every pool and
     *      every user, and USDR moves the threshold whenever its reserve or its collateral prices
     *      move. A `false` here is a snapshot, not a promise; `SolvencyGateActive` remains the
     *      only reliable signal.
     *
     * @param token The currency of the inflow -- a pool's base token.
     * @param amount The inflow being considered. Zero never reverts.
     * @return willRevert True when this inflow would revert `SolvencyGateActive`.
     * @return maxAmount The largest inflow that would pass, in `token` units.
     *         `type(uint256).max` means unbounded: the gate is off, unreadable, or does not apply
     *         to this token. Cap an input field at `min(balance, maxAmount)`.
     */
    function previewSolvency(
        address token,
        uint256 amount
    ) external view returns (bool willRevert, uint256 maxAmount);

    /**
     * @notice Sets the minimum initial liquidity stamped onto newly created pools.
     * @dev Owner only. Must be non-zero. Never reaches a pool that is already live.
     * @param newMinInitialLiquidity The new floor in USDT units.
     */
    function setMinInitialLiquidity(uint256 newMinInitialLiquidity) external;

    /**
     * @notice Queues a facet cut against a pool this deployer created.
     * @dev Owner only. The pool starts its own timelock; nothing is applied by this call.
     * @param pool The pool to upgrade.
     * @param poolDiamondCut The facet cut payload.
     * @param init Optional initializer address, delegatecalled by the pool when the cut executes.
     * @param initCalldata Calldata for `init`.
     * @return proposalId Hash committing to this exact payload.
     * @return eta Timestamp from which the cut becomes executable.
     */
    function proposePoolCut(
        address pool,
        IDiamondCut.FacetCut[] calldata poolDiamondCut,
        address init,
        bytes calldata initCalldata
    ) external returns (bytes32 proposalId, uint256 eta);

    /**
     * @notice Executes a previously queued facet cut once the pool's delay has elapsed.
     * @dev Owner only. The pool re-derives the proposal id from the payload, so only the exact
     * cut that was queued can land.
     * @param pool The pool to upgrade.
     * @param poolDiamondCut The facet cut payload, identical to the queued one.
     * @param init Optional initializer address.
     * @param initCalldata Calldata for `init`.
     */
    function executePoolCut(
        address pool,
        IDiamondCut.FacetCut[] calldata poolDiamondCut,
        address init,
        bytes calldata initCalldata
    ) external;

    /**
     * @notice Withdraws a queued facet cut before it executes.
     * @dev Owner only.
     * @param pool The pool holding the queued cut.
     * @param proposalId The queued proposal's id.
     */
    function cancelPoolCut(address pool, bytes32 proposalId) external;

    /**
     * @notice Returns the fee percentage allocated to pool creators.
     * @dev Pool creators receive a percentage of the total pool funds as their share.
     * @return The creator fee percentage.
     */
    function creatorFee() external view returns (uint256);

    /**
     * @notice Returns the fee percentage allocated to pool closer.
     * @dev Pool closer receive a percentage of the total pool funds as their share.
     * @return The closer fee percentage.
     */
    function closingFee() external view returns (uint256);

    /**
     * @notice Returns the fee percentage allocated to result resolvers.
     * @dev This fee compensates external resolvers who determine the pool outcome.
     * @return The result resolver fee percentage.
     */
    function resultResolverFee() external view returns (uint256);

    /**
     * @notice Returns the address of the `disputeResolverAI`.
     * @dev This is the address for the dispute resolver AI.
     * @return The address of the Dispute Resolver.
     */
    function disputeResolverAI() external view returns (address);

    /**
     * @notice Checks if a given address corresponds to a deployed pool.
     * @dev This function verifies if a pool was created using the deployer contract.
     * @param pool The address of the pool to check.
     * @return True if the pool exists, false otherwise.
     */
    function createdPools(address pool) external view returns (bool);

    /**
     * @notice Returns the address of the rain token.
     * @return The address of the rain token.
     */
    function rainToken() external view returns (address);

    /**
     * @notice Returns the address of the rain pool diamond factory.
     * @return The address of the rain pool diamond factory.
     */
    function diamondFactory() external view returns (address);

    /**
     * @notice Returns the address of the protocol-wide token ledger.
     * @dev Pools resolve the ledger through this getter rather than holding it in their own
     *      storage, so pools cut after deployment pick it up with no per-pool configuration.
     *      Zero only before it is first set; the pool-side hook is a no-op until then.
     * @return The RainAccounting address, or zero when never set.
     */
    function accounting() external view returns (address);

    /**
     * @notice Updates the protocol-wide token ledger.
     * @dev Can only be called by the contract owner. Zero is REJECTED -- once accounting is on it
     *      stays on, because the ledger does not catch up on whatever moved while it was off.
     * @param newAccounting The new RainAccounting address. Must be non-zero.
     */
    function setAccountingAddress(address newAccounting) external;

    /**
     * @notice Returns all function selectors provided by a specific facet.
     * @dev The `facet` parameter corresponds to the facet contract’s address
     *      registered within the diamond storage.
     * @param facet The facet address to query.
     * @param index The facet address to query.
     * @return The `facetSelectors`. The array of 4-byte function selectors implemented by that facet.
     */
    function facetFunctionSelectors(address facet, uint256 index) external view returns (bytes4);

    /**
     * @notice Returns the address of the DiamondCut facet.
     * @dev This facet handles adding, replacing, or removing functions within the diamond.
     * @return The address of the DiamondCut facet.
     */
    function diamondCutFacet() external view returns (address);

    /**
     * @notice Returns the address of the DiamondLoupe facet.
     * @dev This facet provides introspection functions for inspecting diamond facets and selectors.
     * @return The address of the DiamondLoupe facet.
     */
    function diamondLoupeFacet() external view returns (address);

    /**
     * @notice Returns the address of the DiamondTrading facet.
     * @dev This facet contains the logic related to trading or marketplace operations.
     * @return The address of the DiamondTrading facet.
     */
    function diamondTradingFacet() external view returns (address);

    /**
     * @notice Returns the address of the DiamondResolution facet.
     * @dev This facet manages dispute resolutions or settlement logic.
     * @return The address of the DiamondResolution facet.
     */
    function diamondResolutionFacet() external view returns (address);

    /**
     * @notice Returns the address of the DiamondDispute facet.
     * @dev This facet contains the logic for initiating and handling disputes.
     * @return The address of the DiamondDispute facet.
     */
    function diamondDisputeFacet() external view returns (address);

    /**
     * @notice Returns the address of the DiamondClaim facet.
     * @dev This facet manages claim logic, such as withdrawals, settlements, or reward claims.
     * @return The address of the DiamondClaim facet.
     */
    function diamondClaimFacet() external view returns (address);

    /**
     * @notice Returns the address of the DiamondCancelOrder facet.
     * @dev This facet provides functionality for canceling or invalidating active orders.
     * @return The address of the DiamondCancelOrder facet.
     */
    function diamondCancelOrderFacet() external view returns (address);

    /**
     * @notice Returns the address of the DiamondInfo facet.
     * @dev This facet provides informational and metadata retrieval functions.
     * @return The address of the DiamondInfo facet.
     */
    function diamondInfoFacet() external view returns (address);

    /**
     * @notice Returns the address of the DiamondGetter facet.
     * @dev This facet exposes read-only getter functions for on-chain data inspection.
     * @return The address of the DiamondGetter facet.
     */
    function diamondGetterFacet() external view returns (address);

    /**
     * @notice Returns the address of the Diamond Oracle Fee Facet.
     * @dev DEPRECATED — the OracleFee facet was removed and is no longer cut into new pools.
     */
    function diamondOracleFeeFacet() external view returns (address);

    /**
     * @notice Returns the address of the Diamond SplitMerge Facet.
     * @dev This facet provides zero-price-impact split and merge operations.
     * @return The address of the SplitMerge facet.
     */
    function diamondSplitMergeFacet() external view returns (address);

    /**
     * @notice Returns configuration and routing data for a given token.
     * @dev Flattens and returns the stored TokenData struct associated with the token address.
     * @param tokenAddress The address of the token being queried.
     * @return The Uniswap pool version used for this token.
     * @return The indicator of whether the token is currently allowed by the protocol.
     * @return The address of the router contract used for swaps.
     * @return The address of the router helper contract, if applicable.
     * @return The Uniswap swap path from USDT to the token.
     * @return The Uniswap swap path from the token to USDT.
     * @return The Uniswap swap path from the token to WETH.
     */
    function tokenData(
        address tokenAddress
    ) external view returns (TokenPool, bool, address, address, bytes calldata, bytes calldata, bytes calldata);

    /**
     * @notice Initializes the Rain Deployer contract with required parameters.
     * @dev This function sets the core addresses and fee structures for the contract.
     * It should only be called once during contract deployment.
     * @param _oracleFactoryAddress The address of the Oracle Factory contract.
     * @param _baseToken The address of the base token used for transactions.
     * @param _platformAddress The address where platform fees are collected.
     * @param _resolverAI The address of the pool result resolver AI.
     * @param _disputeResolverAI The address of the dispute resolver AI.
     * @param _rainToken The address of the Rain Token.
     * @param _diamondFactory The address of the diamond factory.
     * @param _liquidityFee The percentage fee allocated for liquidity providers.
     * @param _platformFee The percentage fee collected by the platform.
     * @param _oracleFixedFee DEPRECATED — pass 0.
     * @param _creatorFee The percentage fee allocated to pool creators.
     * @param _resultResolverFee The percentage fee paid to result resolvers.
     * @param _closingFee The percentage fee paid to the pool closers.
     */
    function initialize(
        address _oracleFactoryAddress,
        address _baseToken,
        address _platformAddress,
        address _resolverAI,
        address _disputeResolverAI,
        address _rainToken,
        address _diamondFactory,
        uint256 _liquidityFee,
        uint256 _platformFee,
        uint256 _oracleFixedFee,
        uint256 _creatorFee,
        uint256 _resultResolverFee,
        uint256 _closingFee
    ) external;

    /**
     * @notice Creates a new RainPool contract instance with the given parameters.
     * @dev Deploys a new RainPool contract and transfers the necessary base tokens
     * for initial liquidity and oracle fees if applicable.
     * @param params A struct containing all required parameters for pool creation.
     * @return The address of the newly created RainPool contract.
     */
    function createPool(IRainDeployer.Params memory params) external returns (address);

    /**
     * @notice Creates an external oracle for resolving a pool's outcome.
     * @dev This function deploys a new oracle via the oracle factory contract.
     * @param numberOfOracles The number of oracle nodes to be created.
     * @param oracleReward The total reward distributed among the oracle nodes.
     * @param fixedFee A fixed fee for oracle creation.
     * @param creator The address of the pool creator.
     * @param endTime The timestamp when the oracle's result should be finalized.
     * @param totalNumberOfOptions The number of possible outcomes the oracle will validate.
     * @param questionUri A reference URI (e.g., IPFS) containing the event details.
     * @return The address of the newly created oracle.
     */
    function createOracle(
        uint256 numberOfOracles,
        uint256 oracleReward,
        uint256 fixedFee,
        address creator,
        uint256 endTime,
        uint256 totalNumberOfOptions,
        string memory questionUri
    ) external returns (address);

    /* =========================== SETTERS ====================================== */

    /**
     * @notice Updates the address of the resolver AI EOA.
     * @dev Can only be called by the contract owner.
     * @param newResolverAI The new resolver AI EOA address.
     */
    function setResolverAI(address newResolverAI) external;

    /**
     * @notice Updates the address of the Oracle Factory contract.
     * @dev Can only be called by the contract owner.
     * @param newOracleFactoryAddress The new oracle factory address.
     */
    function setOracleFactoryAddress(address newOracleFactoryAddress) external;

    /**
     * @notice Updates the base token and its decimal precision.
     * @dev Can only be called by the contract owner.
     * @param newBaseToken The address of the new base token.
     */
    function setBaseToken(address newBaseToken) external;

    // `setOracleFixedFee` was removed with the oracle fixed fee itself.

    /**
     * @notice Updates the flat USDT cost charged to an appealer to fund the appeal oracle.
     * @dev Can only be called by the contract owner. Applies to pools created after the change;
     * existing pools keep the value snapshotted at their creation.
     * @param newAppealOracleCost The new appeal oracle cost, denominated in USDT.
     */
    function setAppealOracleCost(uint256 newAppealOracleCost) external;

    /**
     * @notice Updates the fee allocated to pool creators.
     * @dev Can only be called by the contract owner.
     * @param newCreatorFee The new creator fee.
     */
    function setCreatorFee(uint256 newCreatorFee) external;

    /**
     * @notice Updates the fee allocated to pool closers.
     * @dev Can only be called by the contract owner.
     * @param newClosingFee The new closing fee.
     */

    function setClosingFee(uint256 newClosingFee) external;

    /**
     * @notice Updates the fee allocated to the result resolver.
     * @dev Can only be called by the contract owner.
     * @param newResultResolverFee The new result resolver fee.
     */
    function setResultResolverFee(uint256 newResultResolverFee) external;

    /**
     * @notice Updates the platform's treasury address.
     * @dev Can only be called by the contract owner.
     * @param newPlatformAddress The new platform address.
     */
    function setPlatformAddress(address newPlatformAddress) external;

    /**
     * @notice Updates the liquidity fee percentage.
     * @dev Can only be called by the contract owner.
     * @param newLiquidityFee The new liquidity fee percentage.
     */
    function setLiquidityFee(uint256 newLiquidityFee) external;

    /**
     * @notice Updates the platform fee percentage.
     * @dev Owner only, and only affects pools created afterwards -- each pool snapshots the fee
     *      at creation.
     *
     *      ZERO IS ALLOWED, unlike the other fee setters. It switches the protocol's own cut off,
     *      which is what a promotional period wants. Settlement already copes: the option's
     *      platform share computes to 0, and `LibUtils.swapAndBurn` no-ops on a zero input rather
     *      than sending a zero swap to the router. A redundant write is still rejected.
     * @param newPlatformFee The new platform fee percentage. 0 disables the platform cut.
     */
    function setPlatformFee(uint256 newPlatformFee) external;

    /**
     * @notice Updates the address of the Dispute Resolver AI.
     * @dev Can only be called by the contract owner.
     * @param newDisputeResolverAI The new RainFactory address.
     */
    function setDisputeResolverAI(address newDisputeResolverAI) external;

    /**
     * @notice Updates the DiamondCut facet address and its function selectors.
     * @dev Only callable by the contract owner.
     * @param newDiamondCutFacet The new facet contract address.
     * @param newFacetFunctionSelectors The function selectors belonging to the facet.
     */
    function setNewDiamondCutFacet(address newDiamondCutFacet, bytes4[] calldata newFacetFunctionSelectors) external;

    /**
     * @notice Updates the DiamondLoupe facet address and its function selectors.
     * @dev Only callable by the contract owner.
     * @param newDiamondLoupeFacet The new facet contract address.
     * @param newFacetFunctionSelectors The function selectors belonging to the facet.
     */
    function setNewDiamondLoupeFacet(
        address newDiamondLoupeFacet,
        bytes4[] calldata newFacetFunctionSelectors
    ) external;

    /**
     * @notice Updates the DiamondTrading facet address and its function selectors.
     * @dev Only callable by the contract owner.
     * @param newDiamondTradingFacet The new facet contract address.
     * @param newFacetFunctionSelectors The function selectors belonging to the facet.
     */
    function setNewDiamondTradingFacet(
        address newDiamondTradingFacet,
        bytes4[] calldata newFacetFunctionSelectors
    ) external;

    /**
     * @notice Updates the DiamondResolution facet address and its function selectors.
     * @dev Only callable by the contract owner.
     * @param newDiamondResolutionFacet The new facet contract address.
     * @param newFacetFunctionSelectors The function selectors belonging to the facet.
     */
    function setNewDiamondResolutionFacet(
        address newDiamondResolutionFacet,
        bytes4[] calldata newFacetFunctionSelectors
    ) external;

    /**
     * @notice Updates the DiamondDispute facet address and its function selectors.
     * @dev Only callable by the contract owner.
     * @param newDiamondDisputeFacet The new facet contract address.
     * @param newFacetFunctionSelectors The function selectors belonging to the facet.
     */
    function setNewDiamondDisputeFacet(
        address newDiamondDisputeFacet,
        bytes4[] calldata newFacetFunctionSelectors
    ) external;

    /**
     * @notice Updates the DiamondClaim facet address and its function selectors.
     * @dev Only callable by the contract owner.
     * @param newDiamondClaimFacet The new facet contract address.
     * @param newFacetFunctionSelectors The function selectors belonging to the facet.
     */
    function setNewDiamondClaimFacet(
        address newDiamondClaimFacet,
        bytes4[] calldata newFacetFunctionSelectors
    ) external;

    /**
     * @notice Updates the DiamondCancelOrder facet address and its function selectors.
     * @dev Only callable by the contract owner.
     * @param newDiamondCancelOrderFacet The new facet contract address.
     * @param newFacetFunctionSelectors The function selectors belonging to the facet.
     */
    function setNewDiamondCancelOrderFacet(
        address newDiamondCancelOrderFacet,
        bytes4[] calldata newFacetFunctionSelectors
    ) external;

    /**
     * @notice Updates the DiamondInfo facet address and its function selectors.
     * @dev Only callable by the contract owner.
     * @param newDiamondInfoFacet The new facet contract address.
     * @param newFacetFunctionSelectors The function selectors belonging to the facet.
     */
    function setNewDiamondInfoFacet(address newDiamondInfoFacet, bytes4[] calldata newFacetFunctionSelectors) external;

    /**
     * @notice Updates the DiamondGetter facet address and its function selectors.
     * @dev Only callable by the contract owner.
     * @param newDiamondGetterFacet The new facet contract address.
     * @param newFacetFunctionSelectors The function selectors belonging to the facet.
     */
    function setNewDiamondGetterFacet(
        address newDiamondGetterFacet,
        bytes4[] calldata newFacetFunctionSelectors
    ) external;

    // `setNewOracleFeeFacet` was removed with the OracleFee facet.
    /**
     * @notice Updates the SplitMerge facet address and its function selectors.
     * @dev Only callable by the contract owner.
     * @param newDiamondSplitMergeFacet The new facet contract address.
     * @param newFacetFunctionSelectors The function selectors belonging to the facet.
     */
    function setNewSplitMergeFacet(
        address newDiamondSplitMergeFacet,
        bytes4[] calldata newFacetFunctionSelectors
    ) external;

    /**
     * @notice Allows a new token to be used by the protocol.
     * @dev Stores routing and pool configuration for the token and marks it as allowed.
     *      Access to this function is typically restricted (e.g., owner or governance).
     * @param newTokenAddress The address of the token to be allowed.
     * @param tokenData_ The configuration data associated with the token, including
     *        pool type, router addresses, and swap paths.
     */
    function allowNewToken(address newTokenAddress, IRainDeployer.TokenData calldata tokenData_) external;

    /**
     * @notice Removes a token previously allowed by the protocol.
     * @dev Only the owner has the authority to call this function.
     */
    function disallowExistingToken(address tokenAddress) external;
}

