    function firstBuyOrderPrice(uint256 option, uint8 optionSide) external view returns (uint256) {
        return LibDiamond.diamondStorage().firstBuyOrderPrice[option][optionSide];
    }

    ////////////////////
    // Resolution — Per Option
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function optionWinner(uint256 option) external view returns (uint8) {
        return LibDiamond.diamondStorage().optionWinner[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionResolved(uint256 option) external view returns (bool) {
        return LibDiamond.diamondStorage().optionResolved[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionClaimed(uint256 option, address user) external view returns (bool) {
        return LibDiamond.diamondStorage().optionClaimed[option][user];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionResolutionProposer(uint256 option) external view returns (address) {
        return LibDiamond.diamondStorage().optionResolutionProposer[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionResolverBond(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionResolverBond[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionProposedWinner(uint256 option) external view returns (uint8) {
        return LibDiamond.diamondStorage().optionProposedWinner[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionEndTime(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionEndTime[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionEndTimeCache(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionEndTimeCache[option];
    }

    function optionPhaseBActivationTime(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionPhaseBActivationTime[option];
    }

    function PHASE_B_DELAY() external view returns (uint256) {
        return LibDiamond.diamondStorage().PHASE_B_DELAY;
    }

    /**
     * @inheritdoc IGetter
     */
    function CLOSE_GRACE_PERIOD() external view returns (uint256) {
        return LibDiamond.diamondStorage().CLOSE_GRACE_PERIOD;
    }

    ////////////////////
    // Fee Shares — Per Option
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function optionWinningPoolShare(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionWinningPoolShare[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionPlatformShare(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionPlatformShare[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionCreatorShare(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionCreatorShare[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionResolverShare(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionResolverShare[option];
    }


    /**
     * @inheritdoc IGetter
     */
    function optionClosingShare(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionClosingShare[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionOrderBookShare(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionOrderBookShare[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionFirstClaim(uint256 option) external view returns (bool) {
        return LibDiamond.diamondStorage().optionFirstClaim[option];
    }

    ////////////////////
    // User Global
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function userActiveSellOrdersPerOption(uint256 option, address user) external view returns (uint256) {
        return LibDiamond.diamondStorage().userActiveSellOrdersPerOption[option][user];
    }

    /**
     * @inheritdoc IGetter
     */
    function userActiveBuyOrdersPerOption(uint256 option, address user) external view returns (uint256) {
        return LibDiamond.diamondStorage().userActiveBuyOrdersPerOption[option][user];
    }

    ////////////////////
    // Other — Per Option
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function optionDispute(
        uint256 option
    ) external view returns (uint256 disputeFee, uint256 disputedWinner, address disputer, address _disputeResolver) {
        IRainPool.Dispute storage d = LibDiamond.diamondStorage().optionDispute[option];

        return (d.disputeFee, d.disputedWinner, d.disputer, d.resolver);
    }

    /**
     * @inheritdoc IGetter
     */
    function optionAppeal(
        uint256 option
    ) external view returns (uint256 disputeFee, uint256 disputedWinner, address disputer, address appealResolver) {
        IRainPool.Dispute storage d = LibDiamond.diamondStorage().optionAppeal[option];

        return (d.disputeFee, d.disputedWinner, d.disputer, d.resolver);
    }

    /**
     * @inheritdoc IGetter
     */
    function optionState(uint256 option) external view returns (Types.PoolState) {
        return LibDiamond.diamondStorage().optionState[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function isOptionAppealed(uint256 option) external view returns (bool) {
        return LibDiamond.diamondStorage().isOptionAppealed[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionResolver(uint256 option) external view returns (address) {
        // Mirrors the auth check in ResolutionFacet.chooseWinner: role-derived for
        // open/disputed options, the stored oracle CONTRACT once appealed.
        return LibDiamond.currentResolver(LibDiamond.diamondStorage(), option);
    }

    /**
     * @inheritdoc IGetter
     */
    function isOptionDisputed(uint256 option) external view returns (bool) {
        return LibDiamond.diamondStorage().isOptionDisputed[option];
    }

    ////////////////////
    // Token Data
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function tokenData()
        external
        view
        returns (IRainDeployer.TokenPool, bool, address, address, bytes memory, bytes memory, bytes memory)
    {
        IRainDeployer.TokenData storage td = LibDiamond.diamondStorage().tokenData;

        return (
            td.tokenPool,
            td.isAllowed,
            td.routerAddress,
            td.routerHelper,
            td.pathUSDTToToken,
            td.pathTokenToUSDT,
            td.pathTokenWETH
        );
    }

    /**
     * @inheritdoc IGetter
     */
    function tradingModel() external view returns (Types.TradingModel) {
        return LibDiamond.diamondStorage().tradingModel;
    }
}

