// SPDX-License-Identifier: MIT

pragma solidity 0.8.26;

import { IGetter } from "../interfaces/IGetter.sol";

import { Types } from "../shared/Types.sol";

import { LibDiamond } from "../libraries/LibDiamond.sol";

import { LinkedListStorage } from "../../interfaces/LinkedListStorage.sol";

import { IRainPool } from "../../interfaces/IRainPool.sol";

import { IRainDeployer } from "../../interfaces/IRainDeployer.sol";

/**
 * @title GetterFacet
 * @author Rain Team
 * @notice External interface for the rain pool `Getter` facet.
 */
contract GetterFacet is IGetter {
    ////////////////////
    // Constants
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function PRICE_MAGNIFICATION() external view returns (uint256) {
        return LibDiamond.diamondStorage().PRICE_MAGNIFICATION;
    }

    /**
     * @inheritdoc IGetter
     */
    function FEE_MAGNIFICATION() external view returns (uint256) {
        return LibDiamond.diamondStorage().FEE_MAGNIFICATION;
    }

    /**
     * @inheritdoc IGetter
     */
    function TICK_SPACING() external view returns (uint256) {
        return LibDiamond.diamondStorage().TICK_SPACING;
    }

    /**
     * @inheritdoc IGetter
     */
    function ORDER_EXECUTION_FEE() external view returns (uint256) {
        return LibDiamond.diamondStorage().ORDER_EXECUTION_FEE;
    }

    /**
     * @inheritdoc IGetter
     */
    function MAKER_REBATE_FEE() external view returns (uint256) {
        return LibDiamond.diamondStorage().MAKER_REBATE_FEE;
    }

    /**
     * @inheritdoc IGetter
     */
    function DISPUTE_WINDOW() external view returns (uint256) {
        return LibDiamond.diamondStorage().DISPUTE_WINDOW;
    }

    /**
     * @inheritdoc IGetter
     */
    function DISPUTE_FEE_MAX() external view returns (uint256) {
        return LibDiamond.diamondStorage().DISPUTE_FEE_MAX;
    }

    /**
     * @inheritdoc IGetter
     */
    function DISPUTE_FEE_MIN() external view returns (uint256) {
        return LibDiamond.diamondStorage().DISPUTE_FEE_MIN;
    }

    /**
     * @inheritdoc IGetter
     */
    function APPEAL_FEE_MIN() external view returns (uint256) {
        return LibDiamond.diamondStorage().APPEAL_FEE_MIN;
    }

    /**
     * @inheritdoc IGetter
     */
    function RESOLUTION_FEE_MIN() external view returns (uint256) {
        return LibDiamond.diamondStorage().RESOLUTION_FEE_MIN;
    }

    /**
     * @inheritdoc IGetter
     */
    function RESOLUTION_FEE_MAX() external view returns (uint256) {
        return LibDiamond.diamondStorage().RESOLUTION_FEE_MAX;
    }

    ////////////////////
    // Global Scalars
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function startTime() external view returns (uint256) {
        return LibDiamond.diamondStorage().startTime;
    }

    /**
     * @inheritdoc IGetter
     */
    function endTime() external view returns (uint256) {
        return LibDiamond.diamondStorage().endTime;
    }

    /**
     * @inheritdoc IGetter
     */
    function numberOfOptions() external view returns (uint256) {
        return LibDiamond.diamondStorage().numberOfOptions;
    }

    /**
     * @inheritdoc IGetter
     */
    function platformFee() external view returns (uint256) {
        return LibDiamond.diamondStorage().platformFee;
    }

    /**
     * @inheritdoc IGetter
     */
    function liquidityFee() external view returns (uint256) {
        return LibDiamond.diamondStorage().liquidityFee;
    }

    /**
     * @inheritdoc IGetter
     */
    function creatorFee() external view returns (uint256) {
        return LibDiamond.diamondStorage().creatorFee;
    }

    /**
     * @inheritdoc IGetter
     */
    function closingFee() external view returns (uint256) {
        return LibDiamond.diamondStorage().closingFee;
    }

    /**
     * @inheritdoc IGetter
     */
    function resultResolverFee() external view returns (uint256) {
        return LibDiamond.diamondStorage().resultResolverFee;
    }

    /**
     * @inheritdoc IGetter
     */
    function oracleFixedFee() external view returns (uint256) {
        return LibDiamond.diamondStorage().oracleFixedFee;
    }

    /**
     * @inheritdoc IGetter
     */
    function appealOracleCost() external view returns (uint256) {
        return LibDiamond.diamondStorage().appealOracleCost;
    }

    /**
     * @inheritdoc IGetter
     */
    function oracleEndTime() external view returns (uint256) {
        return LibDiamond.diamondStorage().oracleEndTime;
    }

    /**
     * @inheritdoc IGetter
     */
    function ordersAdded() external view returns (uint256) {
        return LibDiamond.diamondStorage().ordersAdded;
    }

    /**
     * @inheritdoc IGetter
     */
    function ordersRemoved() external view returns (uint256) {
        return LibDiamond.diamondStorage().ordersRemoved;
    }

    /**
     * @inheritdoc IGetter
     */
    function baseTokenDecimals() external view returns (uint256) {
        return LibDiamond.diamondStorage().baseTokenDecimals;
    }

    /**
     * @inheritdoc IGetter
     */
    function ipfsUri() external view returns (string memory) {
        return LibDiamond.diamondStorage().ipfsUri;
    }

    ////////////////////
    // Global Addresses
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function FACTORY() external view returns (address) {
        return LibDiamond.diamondStorage().FACTORY;
    }

    /**
     * @inheritdoc IGetter
     */
    function baseToken() external view returns (address) {
        return LibDiamond.diamondStorage().baseToken;
    }

    /**
     * @inheritdoc IGetter
     */
    function rainToken() external view returns (address) {
        return LibDiamond.diamondStorage().rainToken;
    }

    /**
     * @inheritdoc IGetter
     */
    function usdt() external view returns (address) {
        return LibDiamond.diamondStorage().usdt;
    }

    /**
     * @inheritdoc IGetter
     */
    function poolOwner() external view returns (address) {
        return LibDiamond.diamondStorage().poolOwner;
    }

    /**
     * @inheritdoc IGetter
     */
    function platformAddress() external view returns (address) {
        return LibDiamond.diamondStorage().platformAddress;
    }

    /**
     * @inheritdoc IGetter
     */
    function resolver() external view returns (address) {
        // Late-bound: the authoritative resolver is the deployer's current `resolverAI`, not the
        // copy taken at pool creation. Returning the stale copy would show the frontend an
        // address that can no longer resolve after a key rotation.
        return LibDiamond.liveResolver(LibDiamond.diamondStorage());
    }

    /**
     * @inheritdoc IGetter
     */
    function disputeResolver() external view returns (address) {
        return LibDiamond.liveDisputeResolver(LibDiamond.diamondStorage());
    }

    /**
     * @inheritdoc IGetter
     */
    function referrer() external view returns (address) {
        return LibDiamond.diamondStorage().referrer;
    }

    ////////////////////
    // Global Booleans
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function isPublic() external view returns (bool) {
        return LibDiamond.diamondStorage().isPublic;
    }

    /**
     * @inheritdoc IGetter
     */
    function resolverIsAI() external view returns (bool) {
        return LibDiamond.diamondStorage().resolverIsAI;
    }

    ////////////////////
    // Level 3 — Global (across all options and sides)
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function totalMarketFunds() external view returns (uint256) {
        return LibDiamond.diamondStorage().totalMarketFunds;
    }

    /**
     * @inheritdoc IGetter
     */
    function totalMarketShares() external view returns (uint256) {
        return LibDiamond.diamondStorage().totalMarketShares;
    }

    ////////////////////
    // V2 AMM — Per Option
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function ammYesReserve(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().ammYesReserve[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function ammNoReserve(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().ammNoReserve[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function resolverShareUSDT(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().resolverShareUSDT[option];
    }


    ////////////////////
    // V2 LP Shares — Per Option
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function totalOptionLPShares(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().totalOptionLPShares[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function userOptionLPShares(uint256 option, address user) external view returns (uint256) {
        return LibDiamond.diamondStorage().userOptionLPShares[option][user];
    }

    ////////////////////
    // V2 Swap Fee Accumulator — Per Option
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function feePerLPShareX128(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().feePerLPShareX128[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function userFeeDebtX128(uint256 option, address user) external view returns (uint256) {
        return LibDiamond.diamondStorage().userFeeDebtX128[option][user];
    }

    ////////////////////
    // Level 2 — Per Option (Yes + No combined)
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function optionFinalized(uint256 option) external view returns (bool) {
        return LibDiamond.diamondStorage().optionFinalized[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionTotalFunds(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionTotalFunds[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionTotalShares(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionTotalShares[option];
    }

    ////////////////////
    // Level 1 — Per Option Per Side
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function optionPerSideFunds(uint256 option, uint8 optionSide) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionPerSideFunds[option][optionSide];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionPerSideShares(uint256 option, uint8 optionSide) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionPerSideShares[option][optionSide];
    }

    /**
     * @inheritdoc IGetter
     */
    function userOptionPerSideShares(uint256 option, uint8 optionSide, address user) external view returns (uint256) {
        return LibDiamond.diamondStorage().userOptionPerSideShares[option][optionSide][user];
    }

    /**
     * @inheritdoc IGetter
     */
    function userSharesPerSideInEscrow(uint256 option, uint8 optionSide, address user) external view returns (uint256) {
        return LibDiamond.diamondStorage().userSharesPerSideInEscrow[option][optionSide][user];
    }

    /**
     * @inheritdoc IGetter
     */
    function userFundsPerSideInEscrow(uint256 option, uint8 optionSide, address user) external view returns (uint256) {
        return LibDiamond.diamondStorage().userFundsPerSideInEscrow[option][optionSide][user];
    }

    ////////////////////
    // Order Book — Per Option Per Side
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function sellOrders(
        uint256 option,
        uint8 optionSide,
        uint256 price
    ) external view returns (int256, int256, int256, bool) {
        LinkedListStorage.LinkedList storage list = LibDiamond.diamondStorage().sellOrders[option][optionSide][price];

        return (list.headIndex, list.tailIndex, list.count, list.isInitialized);
    }

    /**
     * @inheritdoc IGetter
     */
    function buyOrders(
        uint256 option,
        uint8 optionSide,
        uint256 price
    ) external view returns (int256, int256, int256, bool) {
        LinkedListStorage.LinkedList storage list = LibDiamond.diamondStorage().buyOrders[option][optionSide][price];

        return (list.headIndex, list.tailIndex, list.count, list.isInitialized);
    }

    /**
     * @inheritdoc IGetter
     */
    function orderBook(
        uint256 option,
        uint8 optionSide,
        uint256 price,
        uint256 orderID
    ) external view returns (bool, int256) {
        IRainPool.OrderExists storage o = LibDiamond.diamondStorage().orderBook[option][optionSide][price][orderID];

        return (o.exists, o.index);
    }

    /**
     * @inheritdoc IGetter
     */
    function firstSellOrderPrice(uint256 option, uint8 optionSide) external view returns (uint256) {
        return LibDiamond.diamondStorage().firstSellOrderPrice[option][optionSide];
    }

    /**
     * @inheritdoc IGetter
     */
    function firstBuyOrderPrice(uint256 option, uint8 optionSide) external view returns (uint256) {
        return LibDiamond.diamondStorage().firstBuyOrderPrice[option][optionSide];
    }

    ////////////////////
    // Resolution — Per Option
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function optionWinner(uint256 option) external view returns (uint8) {
        return LibDiamond.diamondStorage().optionWinner[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionResolved(uint256 option) external view returns (bool) {
        return LibDiamond.diamondStorage().optionResolved[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionClaimed(uint256 option, address user) external view returns (bool) {
        return LibDiamond.diamondStorage().optionClaimed[option][user];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionResolutionProposer(uint256 option) external view returns (address) {
        return LibDiamond.diamondStorage().optionResolutionProposer[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionResolverBond(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionResolverBond[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionProposedWinner(uint256 option) external view returns (uint8) {
        return LibDiamond.diamondStorage().optionProposedWinner[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionEndTime(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionEndTime[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionEndTimeCache(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionEndTimeCache[option];
    }

    function optionPhaseBActivationTime(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionPhaseBActivationTime[option];
    }

    function PHASE_B_DELAY() external view returns (uint256) {
        return LibDiamond.diamondStorage().PHASE_B_DELAY;
    }

    /**
     * @inheritdoc IGetter
     */
    function CLOSE_GRACE_PERIOD() external view returns (uint256) {
        return LibDiamond.diamondStorage().CLOSE_GRACE_PERIOD;
    }

    ////////////////////
    // Fee Shares — Per Option
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function optionWinningPoolShare(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionWinningPoolShare[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionPlatformShare(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionPlatformShare[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionCreatorShare(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionCreatorShare[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionResolverShare(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionResolverShare[option];
    }


    /**
     * @inheritdoc IGetter
     */
    function optionClosingShare(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionClosingShare[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionOrderBookShare(uint256 option) external view returns (uint256) {
        return LibDiamond.diamondStorage().optionOrderBookShare[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionFirstClaim(uint256 option) external view returns (bool) {
        return LibDiamond.diamondStorage().optionFirstClaim[option];
    }

    ////////////////////
    // User Global
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function userActiveSellOrdersPerOption(uint256 option, address user) external view returns (uint256) {
        return LibDiamond.diamondStorage().userActiveSellOrdersPerOption[option][user];
    }

    /**
     * @inheritdoc IGetter
     */
    function userActiveBuyOrdersPerOption(uint256 option, address user) external view returns (uint256) {
        return LibDiamond.diamondStorage().userActiveBuyOrdersPerOption[option][user];
    }

    ////////////////////
    // Other — Per Option
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function optionDispute(
        uint256 option
    ) external view returns (uint256 disputeFee, uint256 disputedWinner, address disputer, address _disputeResolver) {
        IRainPool.Dispute storage d = LibDiamond.diamondStorage().optionDispute[option];

        return (d.disputeFee, d.disputedWinner, d.disputer, d.resolver);
    }

    /**
     * @inheritdoc IGetter
     */
    function optionAppeal(
        uint256 option
    ) external view returns (uint256 disputeFee, uint256 disputedWinner, address disputer, address appealResolver) {
        IRainPool.Dispute storage d = LibDiamond.diamondStorage().optionAppeal[option];

        return (d.disputeFee, d.disputedWinner, d.disputer, d.resolver);
    }

    /**
     * @inheritdoc IGetter
     */
    function optionState(uint256 option) external view returns (Types.PoolState) {
        return LibDiamond.diamondStorage().optionState[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function isOptionAppealed(uint256 option) external view returns (bool) {
        return LibDiamond.diamondStorage().isOptionAppealed[option];
    }

    /**
     * @inheritdoc IGetter
     */
    function optionResolver(uint256 option) external view returns (address) {
        // Mirrors the auth check in ResolutionFacet.chooseWinner: role-derived for
        // open/disputed options, the stored oracle CONTRACT once appealed.
        return LibDiamond.currentResolver(LibDiamond.diamondStorage(), option);
    }

    /**
     * @inheritdoc IGetter
     */
    function isOptionDisputed(uint256 option) external view returns (bool) {
        return LibDiamond.diamondStorage().isOptionDisputed[option];
    }

    ////////////////////
    // Token Data
    ////////////////////

    /**
     * @inheritdoc IGetter
     */
    function tokenData()
        external
        view
        returns (IRainDeployer.TokenPool, bool, address, address, bytes memory, bytes memory, bytes memory)
    {
        IRainDeployer.TokenData storage td = LibDiamond.diamondStorage().tokenData;

        return (
            td.tokenPool,
            td.isAllowed,
            td.routerAddress,
            td.routerHelper,
            td.pathUSDTToToken,
            td.pathTokenToUSDT,
            td.pathTokenWETH
        );
    }

    /**
     * @inheritdoc IGetter
     */
    function tradingModel() external view returns (Types.TradingModel) {
        return LibDiamond.diamondStorage().tradingModel;
    }
}

