pragma solidity 0.8.26;

/**
 * @title IDispute
 * @author Rain Team
 * @notice Interface for the rain pool `Dispute` facet.
 * @dev Defines the external functions for opening a dispute within the Diamond architecture.
 */
interface IDispute {
    /* ===================================== FUNCTIONS ===================================== */

    /**
     * @notice Starts a dispute for a specific option if a user disagrees with the chosen winner.
     * @dev This function can only be called within the dispute window after the option has been
     *     resolved. It takes a fee from the user to start a dispute. The amount is only returned
     *     to the user in case the oracle selects the winning option provided by the user. The
     *     max amount allowed is $1000.
     * @param option The option ID to dispute.
     */
    function openDispute(uint256 option) external;
}

src/diamond/interfaces/IGetter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { Types } from "../shared/Types.sol";

import { IRainDeployer } from "../../interfaces/IRainDeployer.sol";

/**
 * @title IGetter
 * @author Rain Team
 * @notice Interface for the rain pool diamond facet.
 * @dev Defines the external functions for diamond storage getters within the Diamond architecture.
 */
interface IGetter {
    ////////////////////
    // Constants
    ////////////////////

    /**
     * @notice Returns the price magnification factor.
     */
    function PRICE_MAGNIFICATION() external view returns (uint256);

    /**
     * @notice Returns the fee magnification factor.
     */
    function FEE_MAGNIFICATION() external view returns (uint256);

    /**
     * @notice Returns the tick spacing used for price granularity.
     */
    function TICK_SPACING() external view returns (uint256);

    /**
     * @notice Returns the order execution fee.
     */
    function ORDER_EXECUTION_FEE() external view returns (uint256);

    /**
     * @notice Returns the per-fill maker rebate fee (credited to the resting maker).
     */
    function MAKER_REBATE_FEE() external view returns (uint256);

    /**
     * @notice Returns the dispute window duration in seconds.
     */
    function DISPUTE_WINDOW() external view returns (uint256);

    /**
     * @notice Returns how long a non-creator must wait past `endTime()` before they may close.
     */
    function CLOSE_GRACE_PERIOD() external view returns (uint256);

    /**
     * @notice Returns the maximum fee to open a dispute.
     */
    function DISPUTE_FEE_MAX() external view returns (uint256);

    /**
     * @notice Returns the minimum fee to open a dispute.
     */
    function DISPUTE_FEE_MIN() external view returns (uint256);

    /**
     * @notice Returns the minimum fee to open an appeal.
     */
    function APPEAL_FEE_MIN() external view returns (uint256);

    /**
     * @notice Returns the minimum fee to propose a resolution.
     */
    function RESOLUTION_FEE_MIN() external view returns (uint256);

    /**
     * @notice Returns the maximum fee to propose a resolution.
     */
    function RESOLUTION_FEE_MAX() external view returns (uint256);

    ////////////////////
    // Global Scalars
    ////////////////////

    /**
     * @notice Returns the pool start time.
     */
    function startTime() external view returns (uint256);

    /**
     * @notice Returns the pool end time.
     */
    function endTime() external view returns (uint256);

    /**
     * @notice Returns the number of options in the pool.
     */
    function numberOfOptions() external view returns (uint256);

    /**
     * @notice Returns the platform fee.
     */
    function platformFee() external view returns (uint256);

    /**
     * @notice Returns the liquidity fee.
     */
    function liquidityFee() external view returns (uint256);

    /**
     * @notice Returns the creator fee.
     */
    function creatorFee() external view returns (uint256);

    /**
     * @notice Returns the closing fee.
     */
    function closingFee() external view returns (uint256);

    /**
     * @notice Returns the result resolver fee.
     */
    function resultResolverFee() external view returns (uint256);

    /**
     * @notice Returns the oracle fixed fee.
     * @dev DEPRECATED — 0 on every pool created by a live deployer. Not collected at creation and
     *      not paid out at claim; retained for ABI stability. See RainDeployer.oracleFixedFee.
     */
    function oracleFixedFee() external view returns (uint256);

    /**
     * @notice Returns the flat USDT cost an appealer pays to fund the appeal oracle.
     * @dev Snapshotted from the deployer at pool creation. Non-refundable; never forfeited.
     */
    function appealOracleCost() external view returns (uint256);

    /**
     * @notice Returns the oracle end time.
     */
    function oracleEndTime() external view returns (uint256);

    /**
     * @notice Returns the total number of orders added.
     */
    function ordersAdded() external view returns (uint256);

    /**
     * @notice Returns the total number of orders removed.
     */
    function ordersRemoved() external view returns (uint256);

    /**
     * @notice Returns the base token decimals.
     */
    function baseTokenDecimals() external view returns (uint256);

    /**
     * @notice Returns the IPFS URI associated with the pool.
     */
    function ipfsUri() external view returns (string memory);

    ////////////////////
    // Global Addresses
    ////////////////////

    /**
     * @notice Returns the factory contract address.
     */
    function FACTORY() external view returns (address);

    /**
     * @notice Returns the base token address.
     */
    function baseToken() external view returns (address);

    /**
     * @notice Returns the rain token address.
     */
    function rainToken() external view returns (address);

    /**
     * @notice Returns the USDT token address.
     */
    function usdt() external view returns (address);

    /**
     * @notice Returns the pool owner address.
     */
    function poolOwner() external view returns (address);

    /**
     * @notice Returns the platform address.
     */
    function platformAddress() external view returns (address);

    /**
     * @notice Returns the resolver address.
     */
    function resolver() external view returns (address);

    /**
     * @notice Returns the dispute resolver (AI) address.
     */
    function disputeResolver() external view returns (address);

    /**
     * @notice Returns the referrer address.
     */
    function referrer() external view returns (address);

    ////////////////////
    // Global Booleans
    ////////////////////

    /**
     * @notice Returns whether the pool is public.
     */
    function isPublic() external view returns (bool);

    /**
     * @notice Returns whether the resolver is an AI.
     */
    function resolverIsAI() external view returns (bool);

    ////////////////////
    // Level 3 — Global (across all options and sides)
    ////////////////////

    /**
     * @notice Returns the total funds across all options and sides.
     */
    function totalMarketFunds() external view returns (uint256);

    /**
     * @notice Returns the total shares across all options and sides.
     */
    function totalMarketShares() external view returns (uint256);

    ////////////////////
    // V2 AMM — Per Option
    ////////////////////

    /**
     * @notice Returns the AMM Yes-side reserve for a specific option.
     * @param option The option index.
     */
    function ammYesReserve(uint256 option) external view returns (uint256);

    /**
     * @notice Returns the AMM No-side reserve for a specific option.
     * @param option The option index.
     */
    function ammNoReserve(uint256 option) external view returns (uint256);

    /**
     * @notice DEPRECATED — never written, always returns 0.
     * @param option The option index.
     */
    function resolverShareUSDT(uint256 option) external view returns (uint256);

    ////////////////////
    // V2 LP Shares — Per Option
    ////////////////////

    /**
     * @notice Returns the total LP shares issued for a specific option.
     * @param option The option index.
     */
    function totalOptionLPShares(uint256 option) external view returns (uint256);

    /**
     * @notice Returns the LP shares held by a user for a specific option.
     * @param option The option index.
     * @param user The address of the user.
     */
    function userOptionLPShares(uint256 option, address user) external view returns (uint256);

    ////////////////////
    // V2 Swap Fee Accumulator — Per Option
    ////////////////////

    /**
     * @notice Returns the accumulated fee per LP share (Q128) for a specific option.
     * @param option The option index.
     */
    function feePerLPShareX128(uint256 option) external view returns (uint256);

    /**
