// SPDX-License-Identifier: MIT

pragma solidity 0.8.26;

import { IERC20, SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import { LibDiamond } from "../libraries/LibDiamond.sol";

import { Accounted } from "./base/Accounted.sol";


import { ISplitMerge } from "../interfaces/ISplitMerge.sol";

import { _revert } from "../../utils/Globals.sol";

import { IRainPool } from "../../interfaces/IRainPool.sol";

/**
 * @title SplitMergeFacet
 * @author Rain Team
 * @notice Provides zero-price-impact split and merge operations for the conditional token framework.
 * @dev Split converts base token collateral into equal YES + NO shares.
 *      Merge converts equal YES + NO shares back into base token collateral.
 *      Neither operation touches AMM reserves — prices are unaffected.
 */
contract SplitMergeFacet is ISplitMerge, Accounted {
    using SafeERC20 for IERC20;

    /**
     * @inheritdoc ISplitMerge
     */
    function split(uint256 option, uint256 amount) external accounted {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (option == 0 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }
        // Allowed in Phase A and Phase B; blocked once the claim window opens.
        // Works for both trading models — split/merge never touch AMM reserves
        // or order-book state, just per-side share buckets.
        if (!LibDiamond.isAMMPhase(option) && !LibDiamond.isOBPhase(option)) {
            _revert(IRainPool.SaleNotLive.selector);
        }
        // Once closePool has run, optionFinalized is permanently true and never
        // reset by dispute cycles. Using it (not optionResolved, which fluctuates)
        // ensures the issuance lock survives the full dispute/appeal lifecycle.
        if (ds.optionFinalized[option]) {
            _revert(IRainPool.SaleNotLive.selector);
        }
        if (amount == 0) {
            _revert(IRainPool.InsufficientAmount.selector);
        }

        // Effects before interactions. The collateral pull is the only external call here, and
        // a base token with a transfer hook would otherwise hand the caller control between the
        // gate checks above and the share writes below — long enough to reenter `closePool`,
        // set `optionFinalized`, and have this call then mint shares against an option the
        // issuance lock had already closed. Writing first means the split lands before any
        // reentrant close, which is the correct ordering. `merge` below already does this.
        ds.optionTotalFunds[option] += amount;
        ds.optionTotalShares[option] += amount;
        ds.optionPerSideFunds[option][1] += amount;
        ds.optionPerSideFunds[option][2] += amount;
        ds.optionPerSideShares[option][1] += amount;
        ds.optionPerSideShares[option][2] += amount;
        ds.userOptionPerSideShares[option][1][msg.sender] += amount;
        ds.userOptionPerSideShares[option][2][msg.sender] += amount;
        ds.totalMarketFunds += amount;
        ds.totalMarketShares += amount;


        IERC20(ds.baseToken).safeTransferFrom(msg.sender, address(this), amount);

        emit IRainPool.Split(option, amount, msg.sender);
    }

    /**
     * @inheritdoc ISplitMerge
     */
    function merge(uint256 option, uint256 amount) external accounted {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (option == 0 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }
        if (!LibDiamond.isAMMPhase(option) && !LibDiamond.isOBPhase(option)) {
            _revert(IRainPool.SaleNotLive.selector);
        }
        // Same reason as split: optionFinalized is the permanent gate, not
        // optionResolved which is reset to false on every openDispute call.
        if (ds.optionFinalized[option]) {
            _revert(IRainPool.SaleNotLive.selector);
        }
        if (amount == 0) {
            _revert(IRainPool.InsufficientAmount.selector);
        }

        uint256 availableYes = ds.userOptionPerSideShares[option][1][msg.sender] -
            ds.userSharesPerSideInEscrow[option][1][msg.sender];
        uint256 availableNo = ds.userOptionPerSideShares[option][2][msg.sender] -
            ds.userSharesPerSideInEscrow[option][2][msg.sender];

        if (availableYes < amount || availableNo < amount) {
            _revert(IRainPool.InsufficientUserShares.selector);
        }

        ds.userOptionPerSideShares[option][1][msg.sender] -= amount;
        ds.userOptionPerSideShares[option][2][msg.sender] -= amount;
        ds.optionPerSideFunds[option][1] -= amount;
        ds.optionPerSideFunds[option][2] -= amount;
        ds.optionPerSideShares[option][1] -= amount;
        ds.optionPerSideShares[option][2] -= amount;
        ds.optionTotalFunds[option] -= amount;
        ds.optionTotalShares[option] -= amount;
        ds.totalMarketFunds -= amount;
        ds.totalMarketShares -= amount;


        IERC20(ds.baseToken).safeTransfer(msg.sender, amount);

        emit IRainPool.Merge(option, amount, msg.sender);
    }
}

